  var retry=doc.createElement('button');retry.type='button';retry.textContent='Retry 3D display';retry.onclick=function(){cfRetryRenderer12NJ();};panel.appendChild(retry);
  var diagnostics=doc.createElement('button');diagnostics.type='button';diagnostics.textContent='Open startup details';diagnostics.onclick=function(){if(window.CFStartup12LJ)window.CFStartup12LJ.open();};panel.appendChild(diagnostics);
