function pad(x,z,rx,rz){var m=new THREE.Mesh(cfBoxGeometry12JG(rx,0.15,rz),new THREE.MeshStandardMaterial({color:0xa39a86,roughness:0.97})); m.position.set(x,-1.98,z); plant.add(m); return m;}

/* Small bolt-head bumps around a flange seam ring -- real bolted vessel joints
   show these; a bare smooth torus reads as welded, not flanged. axis='y' for a
   horizontal ring (bVert/bTower's head seams), axis='x' for a vertical ring
   (bHoriz's, since that vessel lies on its side). Shared by all three vessel
   builders below instead of repeating the loop three times. */
function boltRing(cx,cy,cz,radius,axis,k){
 var n=12;
 for(var bi=0;bi<n;bi++){
  var a=(bi/n)*Math.PI*2;
  var bolt=new THREE.Mesh(cfCylinderGeometry12JG(radius*0.045,radius*0.045,radius*0.05,6),mDark);
  if(axis==='y'){bolt.position.set(cx+Math.cos(a)*radius,cy,cz+Math.sin(a)*radius); bolt.rotation.x=Math.PI/2;}
  else{bolt.position.set(cx,cy+Math.cos(a)*radius,cz+Math.sin(a)*radius); bolt.rotation.z=Math.PI/2;}
  add(bolt,k);
 }
}
