    [-1,1].forEach(function(dx){[-1,1].forEach(function(dy){K.cyl(.035,.035,.028,col*w/4+dx*(w/4-.21),yy+dy*(row/2-.20),side*(d/2+.062),m.bolt,'jacket-fastener','z');});});
