 pad(x,z,r*3.6,r*3.6);
 K.cyl(r*.95,r,3,0,1.4+GY,0,m.frame,'skirt','y',true);
 // Original cylindrical shell split into jacket courses without changing its envelope.
 var shellBottom=3+GY,shellH=h-4,courses=12,course=shellH/courses;
 for(var c=0;c<courses;c++){K.cyl(R,R,course,0,shellBottom+(c+.5)*course,0,c%2?m.jacket:m.light,'shell-course','y',true);}
