 for(var c=0;c<=courses;c++){if(c===0||c===4||c===11)continue;K.ring(R+.009,.025,0,shellBottom+c*course,0,m.edge,'jacket-band','y');}
 // Surface seams are thin jacket details, not instrument tubing.
 [10,120,170,230,340].forEach(function(deg){var t=deg*Math.PI/180;var strip=K.box(.028,shellH-.08,.016,Math.cos(t)*(R+.007),shellBottom+shellH/2,Math.sin(t)*(R+.007),m.shade,'jacket-longitudinal-seam');strip.rotation.y=Math.PI/2-t;});
 K.ring(r*.96,.07,0,GY+.20,0,m.bolt,'base-flange','y');
 for(var i=0;i<16;i++){var a=i*Math.PI/8;K.cyl(.075,.075,.25,Math.cos(a)*r*.95,GY+.31,Math.sin(a)*r*.95,m.bolt,'skirt-anchor','y');}
 // Existing lower manway is detailed in-place; no new shell penetration is asserted.
 K.cyl(.35,.35,.12,-R,5+GY,0,m.edge,'manway-neck','x');
 K.cyl(.40,.40,.055,-R-.09,5+GY,0,m.bolt,'manway-cover','x');
