 for(var y=GY+3;y<high-1;y+=8){[-.52,.52].forEach(function(s){K.bar([(Math.sqrt(R*R-s*s)-.02)*ux+s*tx,y,(Math.sqrt(R*R-s*s)-.02)*uz+s*tz],[rad*ux+s*tx,y,rad*uz+s*tz],.04,m.edge,'ladder-bracket');});}
