/* ── reciprocating / centrifugal compressor skid ── */
function flowSeg(a,b,col){
 var dir=new THREE.Vector3().subVectors(b,a); var len=dir.length(); if(len<0.001)return;
 dir.normalize();
 var mat=new THREE.MeshBasicMaterial({color:col});
 var tube=new THREE.Mesh(cfCylinderGeometry12JG(0.05,0.05,len,8),mat);
 tube.position.copy(a).addScaledVector(dir,len/2);
 tube.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir);
 plant.add(tube);
}
