 box('footplate',2.7,.22,2.65,0,.22,0,mSteel);
 [-1,1].forEach(function(a){[-1,1].forEach(function(b){cylinder('base-anchor',.06,.06,.15,.38,mFlange,a*1.09,b*1.04);});});
