 for(var j=0;j<8;j++){var a=j*Math.PI/4,top=V(x+Math.cos(a)*.64,GY+3.21,z+Math.sin(a)*.64),bottom=V(x+Math.cos(a)*1.06,GY+2.47,z+Math.sin(a)*1.06),d=top.clone().sub(bottom);var rib=new THREE.Mesh(cfBoxGeometry12JG(.065,d.length(),.12),mSteel);rib.position.copy(bottom).addScaledVector(d,.5);rib.quaternion.setFromUnitVectors(V(0,1,0),d.clone().normalize());own(rib,'tapered-housing-rib');}
 cylinder('adapter-lower-flange',.74,.74,.11,3.33,mFlange);
 cylinder('vertical-drive-coupling-guard',.45,.45,.68,3.71,mDark);
 // The retained 12KA shaft animation fits inside this guard, on a vertical axis.
