 cylinder('top-mounted-motor',.64,.64,1.48,5.05,mat);
 for(var j=0;j<20;j++){var a=j*Math.PI/10,fin=box('motor-cooling-fin',.08,1.40,.14,Math.cos(a)*.665,5.05,Math.sin(a)*.665,mSteel);fin.rotation.y=-a;}
