 for(var j=0;j<12;j++){var a=j*Math.PI/6;cylinder('casing-cover-bolt',.055,.055,.12,1.61,mSteel,Math.cos(a)*1.03,Math.sin(a)*1.03);}
 // Preserve the exact pre-existing local suction route (pipe12hn_0); its far end
