 preserved.segments.concat(preserved.elbows).forEach(function(m){m.userData.part12MM='retained-suction-boundary';m.userData.owner12MM=k;parts.push(m);});
 var suctionCasing=[x+.96,GY+1.4,z-.36];
 line([[x+1.9,GY+1.4,z-1.4],[x+1.9,GY+1.4,z-.36],suctionCasing],.32,'suction-casing-nozzle');
