 [-1.1,0.4].forEach(function(zz){var rib=new THREE.Mesh(cfTorusGeometry12JG(1.0,0.07,8,24),mDark); rib.rotation.x=Math.PI/2; rib.position.set(x,GY+1.45,z+zz-2.6); add(rib,k);});
