/* ── rack-style pipe run: up to rack elevation, over, down into target ── */
/* 12GB - 3D GEOMETRY ONLY. Keep the same endpoint/connection graph.
   Remove generated collinear detours, including a lane overshoot immediately
   retraced on the same centreline. No vessel, process state or controller changes. */
function cf3dCleanRackPoints(points){
 var clean=[],eps2=1e-12;
 (points||[]).forEach(function(p){
  if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||!Number.isFinite(p.z))return;
  var q=p.clone();
  if(clean.length&&q.distanceToSquared(clean[clean.length-1])<eps2)return;
  while(clean.length>1){
   var a=clean[clean.length-2],b=clean[clean.length-1];
   var ux=b.x-a.x,uy=b.y-a.y,uz=b.z-a.z;
   var vx=q.x-b.x,vy=q.y-b.y,vz=q.z-b.z;
   var cx=uy*vz-uz*vy,cy=uz*vx-ux*vz,cz=ux*vy-uy*vx;
   var scale=(ux*ux+uy*uy+uz*uz)*(vx*vx+vy*vy+vz*vz);
   if(cx*cx+cy*cy+cz*cz>eps2*Math.max(1,scale))break;
   clean.pop();
  }
  if(!clean.length||q.distanceToSquared(clean[clean.length-1])>=eps2)clean.push(q);
 });
 return clean;
}
