function libNavigateToLearned(key){var r=libLearnedRecord(key);if(!r)return;if(r.recordType==='pid_document'){var ci=libPidCategoryIndex();if(ci>=0)libSel.cat=ci;if(r.pidInfoKey&&INFO[r.pidInfoKey])libSel.key=r.pidInfoKey;else libSel.key=key;libRenderCats();libRenderList(document.getElementById('libSearch').value.trim()||null);libRenderDetail();return;}var parentKey=r.parentKey||libStaticKeyByTag(r.parentTag);if(parentKey&&INFO[parentKey]){var ci2=libLearnedCategoryIndex(r);if(ci2>=0)libSel.cat=ci2;libSel.key=parentKey;libRenderCats();libRenderList(document.getElementById('libSearch').value.trim()||null);libRenderDetail();setTimeout(function(){libOpenLearnedChild(key);},0);}else{libSel.key=key;libRenderList(document.getElementById('libSearch').value.trim()||null);libRenderDetail();}}
