function libRenderList(filterText){var el=document.getElementById('libList');if(!el)return;var viewKey=String(libSel.cat)+'|'+String(filterText||'');if(LIB_LIST_FILTER!==viewKey){LIB_LIST_FILTER=viewKey;LIB_LIST_LIMIT=100;}if(libSel.cat==='pdf'){renderPdfLibrary();return;}var keys,learnedMap=libLearnedRecords(),learnedKeys=Object.keys(learnedMap);if(filterText){var tokens=String(filterText).toLowerCase().split(/\s+/).filter(Boolean),staticIdx=libStaticSearchIndex();keys=Object.keys(staticIdx).filter(function(k){var t=staticIdx[k];return tokens.every(function(q){return k.toLowerCase().indexOf(q)>=0||t.indexOf(q)>=0;});});learnedKeys.forEach(function(k){var t=(k+' '+libLearnedSearchText(k)).toLowerCase();if(tokens.every(function(q){return t.indexOf(q)>=0;}))keys.push(k);});keys=keys.filter(function(k,i,a){return a.indexOf(k)===i;}).sort(function(a,b){return libTag(a).localeCompare(libTag(b));});}else if(libSel.cat==='learned')keys=learnedKeys.sort(function(a,b){return libTag(a).localeCompare(libTag(b));});else if(libSel.cat==='unfiled')keys=libUnfiledLearnedKeys().sort(function(a,b){return libTag(a).localeCompare(libTag(b));});else if(typeof libSel.cat==='number'&&LIB_CATS[libSel.cat])keys=LIB_CATS[libSel.cat][1].slice().concat(libLearnedKeysForCat(libSel.cat));else keys=[];keys=Array.from(new Set(keys));if(!keys.length){el.innerHTML='<div style="padding:14px 16px;color:#5a6b7c;font-size:12px;">'+(filterText?'No matches.':'Choose a system on the left, or search above.')+'</div>';return;}var allKeys=keys;keys=allKeys.slice(0,LIB_LIST_LIMIT);el.innerHTML=keys.map(function(k){var r=libIsLearnedKey(k)?learnedMap[k]:null,tag=libTag(k),sub='';if(r&&r.recordType==='pid_document')sub='<span style="display:block;color:#7a9fb8;font-size:9.5px;margin-top:2px;">P&amp;IDs › '+ryanEscape(r.pidSystemFolder||'Unfiled')+' › '+ryanEscape(r.drawingNumber||r.drawingShort||'drawing')+'</span>';else if(r&&r.parentTag)sub='<span style="display:block;color:#688195;font-size:9.5px;margin-top:2px;">'+ryanEscape((r.libraryCategory||r.system||'')+' › '+(r.parentTitle||r.parentTag))+'</span>';else if(r&&(r.libraryCategory||r.system))sub='<span style="display:block;color:#688195;font-size:9.5px;margin-top:2px;">'+ryanEscape(r.libraryCategory||r.system)+'</span>';if(!r){var ch=libLearnedChildrenForParent(k,tag),pr=libLearnedPidForInfoKey(k),notes=[];if(ch.length)notes.push(ch.length+' learned device'+(ch.length===1?'':'s'));if(pr)notes.push((pr.facts||[]).length+' learned P&amp;ID facts');if(notes.length)sub='<span style="display:block;color:#6ea981;font-size:9.5px;margin-top:2px;">'+notes.join(' · ')+'</span>';}return '<div class="libitem'+(libSel.key===k?' act':'')+'" data-k="'+ryanEscape(k)+'" style="padding:8px 14px;cursor:pointer;color:'+(libSel.key===k?'#fff':'#c3ccd4')+';background:'+(libSel.key===k?'#1c2733':'transparent')+';font-size:12px;border-bottom:1px solid #182028;">'+ryanEscape(tag)+sub+'</div>';}).join('')+(allKeys.length>keys.length?'<button id="libMoreRows" style="width:100%;margin-top:8px;">Show next 100 ('+keys.length+' of '+allKeys.length+')</button>':'');var more=document.getElementById('libMoreRows');if(more)more.onclick=function(){var pos=el.scrollTop;LIB_LIST_LIMIT+=100;libRenderList(filterText);el.scrollTop=pos;};el.querySelectorAll('.libitem').forEach(function(d){d.addEventListener('click',function(){var k=d.getAttribute('data-k');if(libIsLearnedKey(k)){libNavigateToLearned(k);return;}libCloseLearnedChild();libSel.key=k;el.querySelectorAll('.libitem').forEach(function(x){x.classList.toggle('act',x===d);x.style.background=x===d?'#1c2733':'transparent';x.style.color=x===d?'#fff':'#c3ccd4';});libRenderDetail();});});}
function libRenderDetail(){var el=document.getElementById('libDetail');if(!el)return;if(ryanQaRenderDetail(el,libSel.key))return;var k=libSel.key,learned=libIsLearnedKey(k)?libLearnedRecord(k):null,info=k?INFO[k]:null;if(k==null){el.innerHTML='<div style="color:#5a6b7c;font-size:13px;">Select an item from the list to view its full reference notes.</div>';return;}if(learned){var staticKey=learned.recordType==='pid_document'?learned.pidInfoKey:libLearnedStaticKey(learned.tag);el.innerHTML='<div style="font-size:18px;font-weight:700;color:#eef2f7;margin-bottom:4px;">'+ryanEscape(learned.primaryTitle||learned.tag)+'</div><div style="font-size:11px;color:#5a6b7c;margin-bottom:16px;">'+(learned.recordType==='pid_document'?'P&amp;ID drawing record':'Learned Reference Library record')+'</div>'+libLearnedDetailHtml(learned)+(staticKey&&INFO[staticKey]?'<div style="margin-top:16px;"><button data-act="openstatic" data-k="'+ryanEscape(staticKey)+'" style="background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:6px 14px;cursor:pointer;font:700 12px inherit;">Open built-in reference entry</button></div>':'');var sb=el.querySelector('[data-act="openstatic"]');if(sb)sb.addEventListener('click',function(){libSel.key=sb.getAttribute('data-k');libRenderList(document.getElementById('libSearch').value.trim()||null);libRenderDetail();});return;}var hasEquip=!!(typeof EQP!=='undefined'&&EQP[k]),tag=libTag(k),directLearned=libLearnedRecords()[libLearnedKey(tag)]||null,pidLearned=libLearnedPidForInfoKey(k),children=libLearnedChildrenForParent(k,tag);if(!info){el.innerHTML='<div style="font-size:18px;font-weight:700;color:#eef2f7;margin-bottom:4px;">'+ryanEscape(tag)+'</div><div style="font-size:11px;color:#5a6b7c;margin-bottom:16px;">'+(hasEquip?'Tag key: '+ryanEscape(k):'')+'</div><div style="color:#8a97a4;font-size:13px;font-style:italic;">No detailed reference notes for this item yet.</div>'+(hasEquip?'<div style="margin-top:20px;"><button data-act="libgoto" data-k="'+ryanEscape(k)+'" style="background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:6px 14px;cursor:pointer;font:700 12px inherit;">View in 3-D model \u25B6</button></div>':'');var b0=el.querySelector('[data-act="libgoto"]');if(b0)b0.addEventListener('click',function(){closeLibrary();go(k);});return;}var childHtml='';if(children.length){childHtml='<div style="margin-top:18px;border-top:1px solid #294735;padding-top:14px;"><div style="font-size:13px;font-weight:800;color:#bdf2ca;margin-bottom:7px;">Attached devices / Ryan-learned records</div><div style="font-size:10.5px;color:#688195;margin-bottom:9px;">These attachments are filed under this equipment page. Open a device to see the preserved operator description, source attachment, and extracted facts.</div>'+children.map(function(r){return '<button data-lib-child="'+ryanEscape(r.key)+'" style="display:block;width:100%;text-align:left;background:#10241a;border:1px solid #2d6445;border-radius:6px;padding:9px 11px;margin:6px 0;color:#d9f5df;cursor:pointer;"><b>'+ryanEscape(r.primaryTitle||r.tag)+'</b><span style="display:block;color:#7fa08a;font-size:10px;margin-top:2px;">'+ryanEscape((r.operatorDescriptions&&r.operatorDescriptions[0])||((r.facts||[]).length+' learned facts'))+'</span></button>';}).join('')+'</div>';}el.innerHTML='<div style="font-size:18px;font-weight:700;color:#eef2f7;margin-bottom:4px;">'+info.t+'</div><div style="font-size:11px;color:#5a6b7c;margin-bottom:16px;">'+(hasEquip?'Tag key: '+k:'Operating knowledge / procedure \u2014 not tied to a specific 3-D item')+'</div><ul style="margin:0;padding-left:20px;color:#c3ccd4;font-size:13.5px;line-height:1.85;">'+(info.d||[]).map(function(s){return '<li>'+s+'</li>';}).join('')+'</ul>'+(pidLearned?'<div style="margin-top:18px;border-top:1px solid #294735;padding-top:14px;">'+libLearnedDetailHtml(pidLearned)+'</div>':'')+(directLearned?'<div style="margin-top:18px;border-top:1px solid #294735;padding-top:14px;">'+libLearnedDetailHtml(directLearned)+'</div>':'')+childHtml+(hasEquip?'<div style="margin-top:20px;"><button data-act="libgoto" data-k="'+k+'" style="background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:6px 14px;cursor:pointer;font:700 12px inherit;">View in 3-D model \u25B6</button></div>':'');var b=el.querySelector('[data-act="libgoto"]');if(b)b.addEventListener('click',function(){closeLibrary();go(k);});el.querySelectorAll('[data-lib-child]').forEach(function(btn){btn.addEventListener('click',function(){libOpenLearnedChild(btn.getAttribute('data-lib-child'));});});}
/* ===== Clearfork P&IDs — local PDF library (IndexedDB, not baked into this file) =====
   Ryan can add real P&ID PDFs here over time without ever touching the HTML source.
   Stored per-browser via IndexedDB; nothing here is a recreation, it's the actual file. */
/* ═══ Crew Schedule / Calendar popup -- real uploaded rotation as seed data,
   IndexedDB-persisted so it survives closing the popup and restarting the
   browser (same machine/browser profile -- this is client-side storage, not a
   server, so it does not sync across devices and is lost if the user clears
   site data; that limit is real and stated here rather than glossed over).
   Scope deliberately smaller than the full "Master Update" ask -- built: a
   real crew grid (add/remove employee, add/cycle shift days, extend the
   calendar, copy the current rotation forward) and a simple per-date notes/
   to-do list. NOT built this pass (all real, separate pieces of work, named
   here rather than silently skipped): full month/week/day calendar layouts
   with rich event fields (permits, LOTO, parts, recurrence, attachments);
   Employee Manager with qualifications/training/contact fields; PDF/Excel/
   CSV export; outage-block linking; revision history/audit trail/undo; and
   any Ryan integration (Ryan-the-AI-coach itself is not built -- see the
   handoff, §5/§13). */
/* 12NB presentation only: existing schedule data/rotation/undo/IndexedDB and
   operator control handlers remain authoritative. No plant clock runs here. */
var CF_SCHEDULE_VIEW_12NB={start:null,goto:'',pending:null,returnScroll:null};
function cfSchedLocalDate12NB(d){d=d||new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function cfSchedOffset12NB(ds,n){var d=new Date(ds+'T12:00:00');d.setDate(d.getDate()+n);return cfSchedLocalDate12NB(d);}
function cfSchedValidDate12NB(ds){if(!/^\d{4}-\d{2}-\d{2}$/.test(ds||''))return false;var d=new Date(ds+'T12:00:00');return !isNaN(d)&&cfSchedLocalDate12NB(d)===ds;}
function cfScheduleCapture12NB(root){
 var box=root.querySelector('#cfSchedule12NB');if(!box)return null;
 var body=box.querySelector('.popb'),grid=box.querySelector('#cfSchedGrid12NB'),active=document.activeElement;
 var state={top:body?body.scrollTop:0,x:grid?grid.scrollLeft:0,y:grid?grid.scrollTop:0,open:[],details:[],focus:null};
 box.querySelectorAll('details[id]').forEach(function(e){state.details.push(e.id);if(e.open)state.open.push(e.id);});
 if(active&&box.contains(active)&&active.id){state.focus={id:active.id,start:active.selectionStart,end:active.selectionEnd};}
 return state;
}
function cfScheduleRestore12NB(root,saved){
 var box=root.querySelector('#cfSchedule12NB');if(!box)return;
 var body=box.querySelector('.popb'),grid=box.querySelector('#cfSchedGrid12NB'),v=CF_SCHEDULE_VIEW_12NB,pending=v.pending;
 if(saved){if(body)body.scrollTop=saved.top;if(grid){grid.scrollLeft=saved.x;grid.scrollTop=saved.y;}saved.details.forEach(function(id){var n=document.getElementById(id);if(n)n.open=saved.open.indexOf(id)>=0;});
  if(saved.focus&&!pending){var n=document.getElementById(saved.focus.id);if(n){try{n.focus({preventScroll:true});if(typeof saved.focus.start==='number')n.setSelectionRange(saved.focus.start,saved.focus.end);}catch(e){}}}}
 if(!pending)return;v.pending=null;
 if(pending==='editor'||pending==='bulk'){
  var target=box.querySelector(pending==='editor'?'#cfSchedEditor12NB':'#cfSchedBulk12NB');
  if(target&&body){body.scrollTop+=target.getBoundingClientRect().top-body.getBoundingClientRect().top-10;var title=target.querySelector('[tabindex]');if(title)title.focus({preventScroll:true});}
 }else if(pending==='return'&&v.returnScroll){var r=v.returnScroll;if(body)body.scrollTop=r.top;if(grid){grid.scrollTop=r.y;grid.scrollLeft=r.x;}v.returnScroll=null;
 }else if(pending==='today'||pending==='range'){
  if(grid){if(pending==='range'){grid.scrollTop=0;grid.scrollLeft=0;}else{var row=grid.querySelector('[data-sched-today12nb]');if(row)grid.scrollTop=Math.max(0,row.offsetTop-48);}}
  if(body&&grid)body.scrollTop+=grid.getBoundingClientRect().top-body.getBoundingClientRect().top-38;
 }
}
function cfControlLayout12NB(){
 var root=document.getElementById('eqt');if(!root||root.style.display==='none')return;
 var head=root.querySelector('.ehead'),foot=root.querySelector('.ebar');
 if(head&&head.offsetHeight)root.style.setProperty('--cf-control-head12nb',head.offsetHeight+'px');
 if(foot&&foot.offsetHeight)root.style.setProperty('--cf-control-foot12nb',foot.offsetHeight+'px');
}
function cfInstallMobileSchedule12NB(){
 if(window.CFMobileSchedule12NB)return window.CFMobileSchedule12NB;
 var root=document.getElementById('eqt'),screen=document.getElementById('eqtscr'),nav=document.getElementById('eqtnav');if(!root||!screen||!nav)return null;
 var pending=false;function layout(){if(pending)return;pending=true;requestAnimationFrame(function(){pending=false;cfControlLayout12NB();});}
 if(typeof ResizeObserver!=='undefined'){var ro=new ResizeObserver(layout);ro.observe(root.querySelector('.ehead'));ro.observe(root.querySelector('.ebar'));}
 window.addEventListener('resize',layout,{passive:true});if(window.visualViewport)window.visualViewport.addEventListener('resize',layout,{passive:true});
 root.querySelector('#notifBellBtn').setAttribute('aria-label','Open notifications');
 nav.setAttribute('aria-label','Process control screens');nav.setAttribute('tabindex','0');nav.setAttribute('title','Swipe left or right to reach all process screens');
 // New view commands are handled separately; existing shift/note commands use the original dispatcher.
 screen.addEventListener('click',function(e){
  var t=e.target.closest('[data-act]');if(!t||!screen.contains(t))return;var a=t.getAttribute('data-act'),v=CF_SCHEDULE_VIEW_12NB;
  if(a==='schedcell'){v.returnScroll=cfScheduleCapture12NB(screen);v.pending='editor';}
  else if(a==='schedbulktoggle'&&!PLANT.schedBulkOpen){v.returnScroll=cfScheduleCapture12NB(screen);v.pending='bulk';}
  else if(a==='schedpickcancel'||a==='schedbulkcancel'||a==='schedbulkapply'){v.pending='return';}
  if(a==='schednbtoday'||a==='schednbprev'||a==='schednbnext'||a==='schednbgoto'){
   e.preventDefault();e.stopImmediatePropagation();var today=cfSchedLocalDate12NB(),start=v.start||cfSchedOffset12NB(today,-4);
   if(a==='schednbtoday'){v.start=null;v.pending='today';}
   else if(a==='schednbgoto'){var field=screen.querySelector('#cfSchedGoto12NB'),ds=field?field.value:v.goto;if(!cfSchedValidDate12NB(ds)){if(field)field.reportValidity();return;}v.start=ds;v.goto=ds;v.pending='range';}
   else{v.start=cfSchedOffset12NB(start,a==='schednbprev'?-14:14);v.pending='range';}
   renderScreen();
  }
 },true);
 document.addEventListener('keydown',function(e){if(e.key==='Escape'&&PLANT.popup==='schedule'&&root.style.display!=='none'){e.preventDefault();PLANT.popup=null;renderScreen();document.getElementById('scheduleBtn').focus();}});
 screen.addEventListener('input',function(e){if(e.target.id==='cfSchedGoto12NB')CF_SCHEDULE_VIEW_12NB.goto=e.target.value;});
 layout();window.CFMobileSchedule12NB={build:'12NB',scope:'Responsive presentation; no process or schedule-storage migration',refresh:layout};return window.CFMobileSchedule12NB;
}

var SCHED_SEED={
 employees:[
  {id:'e1',name:'Jeremiah Burc',crew:1,active:true},
  {id:'e2',name:'Brad Skryzneki',crew:1,active:true},
  {id:'e3',name:'Phil Kehayas',crew:2,active:true},
  {id:'e4',name:'zach',crew:2,active:true},
  {id:'e5',name:'Triston Kocher',crew:3,active:true},
  {id:'e6',name:'(name missing in source spreadsheet -- Crew 3, second slot)',crew:3,active:true},
  {id:'e7',name:'Carl Hooker',crew:4,active:true},
  {id:'e8',name:'Ryan Neely',crew:4,active:true},
 ],
 /* Rotation-pattern employees: shift code is COMPUTED from a repeating cycle
    rather than stored per date, so the schedule never goes stale no matter
    when this is reopened. A specific date in `shifts[empId]` (below) always
    overrides the computed pattern -- that's the real "add a day if I cover"
    mechanism Ryan asked for: click any cell, even on a rotation employee, and
    it becomes a one-off override without disturbing the underlying pattern.
    Only Ryan Neely's real current rotation was given (confirmed real,
    dictated directly, 8/8/2026): 3 days (Fri-Sun) \u2192 1 off (Mon) \u2192 3
    nights \u2192 3 off \u2192 4 days \u2192 7 off \u2192 4 nights \u2192 3 off \u2192 repeat
    (28-day cycle, anchored so day 1 = 2026-08-07). The other 7 employees'
    real rotations were never dictated for the current date, so they are
    NOT converted to a pattern and simply keep showing their real imported
    June 2026 data (now historical) under the dates it actually applies to --
    left honest rather than guessed forward into August. */
 rotations:{
  e8:{cycleStart:'2026-08-07',pattern:['D','D','D','','N','N','N','','','','D','D','D','D','','','','','','','','N','N','N','N','','','']} /* verified element-by-element against Ryan's exact stated dates before shipping -- see handoff */
 },
 /* Real imported rotation, June 14-27 2026 (the first 14-day pay period in the
    uploaded sheet), now keyed by actual calendar date rather than a day-offset
    array so it stays correct regardless of when this file is reopened.
    "Jeremiah Burc" vs a later "Jeremiah Burch" spelling and the missing e6
    name are real inconsistencies in the source file, preserved rather than
    silently corrected/guessed. */
 shifts:{
  e1:{'2026-06-15':'D','2026-06-16':'D','2026-06-17':'D','2026-06-18':'D','2026-06-26':'N','2026-06-27':'N'},
  e2:{'2026-06-15':'D','2026-06-16':'D','2026-06-17':'D','2026-06-18':'D','2026-06-26':'N','2026-06-27':'N'},
  e3:{'2026-06-19':'N','2026-06-20':'N','2026-06-21':'N','2026-06-22':'N','2026-06-26':'D','2026-06-27':'D'},
  e4:{'2026-06-19':'N','2026-06-20':'N','2026-06-21':'N','2026-06-22':'N','2026-06-26':'D','2026-06-27':'D'},
  e5:{'2026-06-14':'N','2026-06-15':'N','2026-06-19':'D','2026-06-20':'D','2026-06-21':'D','2026-06-23':'N','2026-06-24':'N','2026-06-25':'N'},
  e6:{'2026-06-14':'N','2026-06-15':'N','2026-06-19':'D','2026-06-20':'D','2026-06-21':'D','2026-06-22':'D','2026-06-23':'N','2026-06-24':'N','2026-06-25':'N'},
  e7:{'2026-06-14':'D','2026-06-16':'N','2026-06-17':'N','2026-06-18':'N','2026-06-19':'N','2026-06-20':'N','2026-06-22':'D','2026-06-23':'D','2026-06-24':'D','2026-06-25':'D'},
  /* e8 (Ryan Neely) intentionally has no leftover June entries -- he's now a
     rotation employee (see `rotations.e8` above); mixing stale flat June
     entries back in would just be dead data shadowing the real pattern. */
 },
 notes:{},
 /* Per-employee/per-date schedule notes; starred in the exact D/N cell. */
 dayNotes:{}
};
/*12PZ: one additive, browser-local roster update. No plant or control writes.*/
function cfScheduleRosterUpdate12PZ(S){
 var result={build:'12PZ',changed:false,status:'unavailable',employeeId:null,message:''};
 function fail(message){result.status='review-required';result.message=message;return result;}
 function object(v){return !!v&&typeof v==='object'&&!Array.isArray(v);}
 function name(v){return String(v||'').trim().toLowerCase().replace(/\s+/g,' ');}
 if(!object(S)||!Array.isArray(S.employees)||!object(S.shifts)||!object(S.rotations))return fail('Shane Dobbs was not added: the saved Schedule needs review. Existing records were left unchanged.');
 if(S.rosterUpdates12PZ!=null&&!object(S.rosterUpdates12PZ))return fail('The saved roster-update record needs review; no employee was replaced.');
 var done=S.rosterUpdates12PZ&&S.rosterUpdates12PZ.shaneDobbs;
 if(done){result.status='already-applied';result.employeeId=done.employeeId||null;return result;}
 var rows=S.employees,ids=Object.create(null);
 for(var i=0;i<rows.length;i++){
  var r=rows[i];if(!object(r)||typeof r.id!=='string'||!r.id||ids[r.id])return fail('The saved employee identifiers need review; no employee was replaced.');ids[r.id]=true;
 }
 var matches=rows.filter(function(e){return name(e.name)==='shane dobbs';});
 if(matches.length>1)return fail('More than one Shane Dobbs record exists. Choose the correct record before assigning a rotation; no records were merged.');
 var e=matches[0]||null,pattern=SCHED_SEED.rotations.e8.pattern.slice(),anchor='2026-11-13',oldSlot=null,slot=-1;
 if(e&&e.active===false)return fail('Shane Dobbs is already archived in this browser. The archived record was not reactivated or duplicated.');
 if(e&&S.rotations[e.id]){
  var rot=S.rotations[e.id];
  if(rot.cycleStart!==anchor||JSON.stringify(rot.pattern)!==JSON.stringify(pattern))return fail('Shane Dobbs already has a different saved rotation. It was preserved rather than overwritten.');
 }
 if(!e){
  slot=rows.findIndex(function(x){var n=String(x.name||'').trim();return x.active!==false&&(!n||/^\(name missing in source spreadsheet -- Crew \d+, second slot\)$/i.test(n));});
  if(slot>=0)oldSlot=rows[slot];
  var base='shane_dobbs_12pz',id=base,suffix=2;
  while(ids[id]||Object.prototype.hasOwnProperty.call(S.shifts,id)||Object.prototype.hasOwnProperty.call(S.rotations,id)||(S.dayNotes&&Object.prototype.hasOwnProperty.call(S.dayNotes,id)))id=base+'_'+suffix++;
  e={id:id,name:'Shane Dobbs',crew:oldSlot?oldSlot.crew:3,active:true,addedBy12PZ:true};
 }
 // All conflict checks above complete before the first mutation. Never move the
 // unnamed slot's historical shifts/notes to a newly identified employee.
 if(!matches.length){
  if(oldSlot){oldSlot.active=false;rows.splice(slot,0,e);}
  else rows.push(e);
  S.shifts[e.id]={};
 }
 if(!S.rotations[e.id])S.rotations[e.id]={cycleStart:anchor,effectiveFrom:anchor,pattern:pattern,source:'Operator request: Nov13-15 DAY; Nov16 OFF; Nov17-19 NIGHT; same 28-day cycle as Ryan Neely.'};
 var conflicts=[];
 ['D','D','D','','N','N','N'].forEach(function(code,i){var ds=cfSchedOffset12NB(anchor,i),manual=(S.shifts[e.id]||{})[ds];if(manual!=null&&manual!==code)conflicts.push(ds);});
 if(!S.rosterUpdates12PZ)S.rosterUpdates12PZ={};
 S.rosterUpdates12PZ.shaneDobbs={revision:'12PZ',employeeId:e.id,cycleStart:anchor,requestedOffDate:'2026-11-16',retainedUnnamedEmployeeId:oldSlot?oldSlot.id:null,placement:oldSlot?'unused-slot':matches.length?'existing-exact-name':'new-column-no-unused-slot',manualOverridesPreserved:true};
 result.changed=true;result.employeeId=e.id;result.status='applied';
 if(conflicts.length)result.message='Shane Dobbs rotation added, but existing manual entries on '+conflicts.join(', ')+' remain in place. Use Reset to pattern on those dates to use the requested rotation.';
 else if(!oldSlot&&!matches.length)result.message='Shane Dobbs was added as a new column in the intended Crew 3 group because the former unused slot is occupied. No named employee was replaced.';
 return result;
}
function cfApplyScheduleRoster12PZ(){
 if(PLANT._schedLoadFailed12PP)return {changed:false,status:'read-failed'};
 var result=cfScheduleRosterUpdate12PZ(PLANT.sched);
 PLANT._schedRosterNotice12PZ=result.message||'';
 if(result.changed)schedDbSave(PLANT.sched);
 return result;
}
function cfScheduleRosterNotice12PZ(){
 var message=PLANT._schedRosterNotice12PZ||'';
 return message?'<p data-sched-roster12pz="true" role="status" style="margin:8px 0;padding:10px;border:1px solid #b79351;border-radius:6px;background:#fff3d3;color:#3e301b">'+schedEsc(message)+'</p>':'';
}

function schedShiftFor(S,empId,dateStr){
 var manual=(S.shifts[empId]||{})[dateStr];
 if(manual!=null)return manual; /* explicit entry (including a cover-day override) always wins */
 var rot=S.rotations&&S.rotations[empId];
 if(rot){
  if(rot.effectiveFrom&&dateStr<rot.effectiveFrom)return ''; //12PZ: no invented pre-start shifts.
  var d0=new Date(rot.cycleStart+'T00:00:00'),d1=new Date(dateStr+'T00:00:00');
  var dayNum=Math.round((d1-d0)/86400000);
  var idx=((dayNum%rot.pattern.length)+rot.pattern.length)%rot.pattern.length;
  return rot.pattern[idx];
 }
 return '';
}
function schedSetShift(S,empId,dateStr,code){(S.shifts[empId]=S.shifts[empId]||{})[dateStr]=code;}
function schedHasPattern(S,empId,dateStr){var r=S.rotations&&S.rotations[empId];return !!r&&(!dateStr||!r.effectiveFrom||dateStr>=r.effectiveFrom);}
function schedIsOverride(S,empId,dateStr){return Object.prototype.hasOwnProperty.call(S.shifts[empId]||{},dateStr);}
function schedCellNote(S,empId,dateStr){return (((S.dayNotes||{})[empId]||{})[dateStr]||'');}
function schedSetCellNote(S,empId,dateStr,text){
 if(!S.dayNotes)S.dayNotes={};
 if(!S.dayNotes[empId])S.dayNotes[empId]={};
 text=String(text||'').trim();
 if(text)S.dayNotes[empId][dateStr]=text;else delete S.dayNotes[empId][dateStr];
}
function schedEsc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
/* schedChangeOne / schedPushUndo / schedUndo -- real multi-level undo (up to 20
   steps), not a decorative button. newCode===null means "clear the manual
   override and fall back to the computed rotation pattern" (a real delete of
   the stored key, not setting it to an empty string, which would itself be a
   permanent override of "blank"). Every mutation returns the PRE-change state
   (had the key existed? what was in it?) so undo can restore it exactly,
   including restoring "no override existed" rather than guessing a value. */
function schedChangeOne(S,empId,dateStr,newCode){
 var bucket=S.shifts[empId]||(S.shifts[empId]={});
 var had=Object.prototype.hasOwnProperty.call(bucket,dateStr);
 var prevVal=had?bucket[dateStr]:undefined;
 if(newCode===null){delete bucket[dateStr];}else{bucket[dateStr]=newCode;}
 return {emp:empId,date:dateStr,had:had,val:prevVal};
}
function schedPushUndo(entries){
 if(!entries||!entries.length)return;
 if(PLANT.schedUndo==null)PLANT.schedUndo=[];
 PLANT.schedUndo.push(entries);
 if(PLANT.schedUndo.length>20)PLANT.schedUndo.shift();
}
function schedUndo(){
 if(!PLANT.schedUndo||!PLANT.schedUndo.length){alert('Nothing to undo.');return;}
 var entries=PLANT.schedUndo.pop();
 entries.forEach(function(e){
  var bucket=PLANT.sched.shifts[e.emp]||(PLANT.sched.shifts[e.emp]={});
  if(e.had)bucket[e.date]=e.val;else delete bucket[e.date];
 });
 schedSave();
}
/* Bulk range apply -- one undo-able action covering every date in [startStr,endStr]
   for one employee. Capped at 90 days per application (a sane guard against a
   fat-fingered multi-year range, not a real limitation of the data model). */
function schedBulkApply(S,empId,startStr,endStr,newCode){
 var d0=new Date(startStr+'T00:00:00'),d1=new Date(endStr+'T00:00:00');
 if(isNaN(d0)||isNaN(d1)||d1<d0)return null;
 var entries=[],dd=new Date(d0),n=0;
 while(dd<=d1&&n<90){entries.push(schedChangeOne(S,empId,dd.toISOString().slice(0,10),newCode));dd.setDate(dd.getDate()+1);n++;}
 return entries;
}
/* 12PP: bounded local-archive failures, explicit save status and no data clearing. */
var CF_ARCHIVE_STATUS_12PP=Object.create(null),CF_ARCHIVE_PENDING_12PP=Object.create(null);
var OFF_SESSION_12PP=null,OFF_BLOB_URL_12PP=null,OFF_VIEW_TOKEN_12PP=0,OFF_PAUSE_12PP=null;
function cfArchiveStatus12PP(key,state,message){
 var row=CF_ARCHIVE_STATUS_12PP[key]||(CF_ARCHIVE_STATUS_12PP[key]={state:'not-read',message:'',pending:0});
 row.state=state;row.message=message||'';row.pending=Object.keys(CF_ARCHIVE_PENDING_12PP[key]||{}).length;
 document.querySelectorAll('[data-cf-archive-status12pp="'+key+'"]').forEach(function(el){el.textContent=row.message;el.hidden=!row.message;});
 return row;
}
function cfArchiveNotice12PP(key){var r=CF_ARCHIVE_STATUS_12PP[key],m=r&&r.message||'';return '<div data-cf-archive-status12pp="'+key+'" role="status"'+(!m?' hidden':'')+' style="margin:8px 0;padding:10px;border:1px solid #b79351;border-radius:6px;background:#fff3d3;color:#3e301b;font:13px/1.5 system-ui">'+schedEsc(m)+'</div>';}
function cfArchiveResult12PP(key,ids,ok){
 var p=CF_ARCHIVE_PENDING_12PP[key]||(CF_ARCHIVE_PENDING_12PP[key]=Object.create(null));
 (ids||[]).forEach(function(id){if(ok)delete p[id];else p[id]=true;});
 var count=Object.keys(p).length;
 cfArchiveStatus12PP(key,count?'not-saved':'saved',count?'Local save is NOT confirmed for '+count+' item(s). Changes remain in this tab only. Existing saved records were not cleared. Keep this tab open and retain a backup before retrying.':'');
 return !!ok;
}
function cfArchiveOpen12PP(key,name,store,cb){
 libOpenDatabase(name,1,function(db){if(!db.objectStoreNames.contains(store))db.createObjectStore(store,{keyPath:'id'});},function(db){
  if(!db)cfArchiveStatus12PP(key,'unavailable','Local '+key+' storage is blocked or unavailable. Existing saved data was not cleared. New changes are session-only until a save is confirmed.');
  cb(db);
 });
}
function cfArchiveRead12PP(key,db,store,cb){libReadStore(db,store,function(rows,ok){if(!ok)cfArchiveStatus12PP(key,'read-failed','The saved '+key+' archive could not be read. This is not an empty archive; existing records remain untouched.');else if(!Object.keys(CF_ARCHIVE_PENDING_12PP[key]||{}).length)cfArchiveStatus12PP(key,'ready','');cb(rows,ok);});}
function cfArchiveWrite12PP(key,db,store,rows,cb){
 var ids=rows.map(function(r){return String(r.id);});cfArchiveResult12PP(key,ids,false);
 libWriteStore(db,store,rows,function(ok){cfArchiveResult12PP(key,ids,ok);if(cb)cb(!!ok);});
}
function cfScheduleLoadedShape12PP(saved){
 // Keep dated schedules without rotations. Do not replace user edits with a seed.
 if(!saved||typeof saved!=='object'||!Array.isArray(saved.employees)||!saved.shifts||typeof saved.shifts!=='object'||Array.isArray(saved.shifts))return null;
 var out=JSON.parse(JSON.stringify(saved)),keys=Object.keys(out.shifts),arrays=keys.some(function(k){return Array.isArray(out.shifts[k]);});
 if(arrays){
  // Only the explicitly retained legacy startDate + per-employee offset arrays.
  if(!cfSchedValidDate12NB(out.startDate)||!keys.every(function(k){return Array.isArray(out.shifts[k]);}))return null;
  out.legacySchedule12PP={startDate:out.startDate,shifts:JSON.parse(JSON.stringify(out.shifts))};
  keys.forEach(function(k){var dates={};out.shifts[k].forEach(function(value,i){if(value!==null&&value!==undefined)dates[cfSchedOffset12NB(out.startDate,i)]=value;});out.shifts[k]=dates;});
 }
 if(!keys.every(function(k){var v=out.shifts[k];return v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).every(cfSchedValidDate12NB);}))return null;
 if(!out.rotations)out.rotations={};if(!out.notes)out.notes={};if(!out.dayNotes)out.dayNotes={};return out;
}
