function custodyDbOpen(cb){libOpenDatabase('ClearforkCustodyLog',1,function(db){if(!db.objectStoreNames.contains('readings'))db.createObjectStore('readings',{keyPath:'id'});},function(db){CUSTODYDB=db;cb(db);});}
