function custodyDbAdd(reading,cb){custodyDbOpen(function(db){libWriteStore(db,'readings',[reading],function(ok){if(!ok)PLANT._custodyStorageWarning='Custody reading kept in this tab only; permanent save failed. Existing archive was not cleared.';else PLANT._custodyStorageWarning='';if(cb)cb(ok);});});}
function custodyLogEnsureLoaded(){
 if(PLANT.custodyLog!=null||PLANT._custodyLoading||PLANT._custodyLoadFailed)return;
 PLANT._custodyLoading=true;
 custodyDbLoadAll(function(items,ok){
  PLANT._custodyLoading=false;
  if(!ok){PLANT._custodyLoadFailed=true;PLANT._custodyStorageWarning='Custody archive unavailable in this browser context. Live meters remain active; existing saved data was not cleared. Reopen the page to retry.';return;}
  var seen=Object.create(null),rows=(PLANT.custodyLog||[]).concat(items||[]).filter(function(r){if(!r||!r.id||seen[r.id])return false;seen[r.id]=true;return true;});
  rows.sort(function(a,b){return (b.addedAt||0)-(a.addedAt||0);});PLANT.custodyLog=rows;PLANT._custodyStorageWarning='';
 });
}
var PDFDB=null,PDF_REC_CACHE=null,PDF_REC_LOADING=false,PDF_REC_WAITERS=[];
function pdfDbInvalidate(){PDF_REC_CACHE=null;}
function pdfDbOpen(cb){libOpenDatabase('ClearforkPDFLib',1,function(db){if(!db.objectStoreNames.contains('pdfs'))db.createObjectStore('pdfs',{keyPath:'id',autoIncrement:true});},function(db){PDFDB=db;cb(db);});}
function pdfDbAll(cb,force){if(PDF_REC_CACHE&&!force){cb(PDF_REC_CACHE.slice(),true);return;}if(cb)PDF_REC_WAITERS.push(cb);if(PDF_REC_LOADING)return;PDF_REC_LOADING=true;pdfDbOpen(function(db){libReadStore(db,'pdfs',function(rows,ok){if(ok)PDF_REC_CACHE=rows;PDF_REC_LOADING=false;var result=(PDF_REC_CACHE||[]).slice(),callbacks=PDF_REC_WAITERS.splice(0);if(!ok)libStorageWarning('Attachment storage could not be read. Original attachments were not cleared.');callbacks.forEach(function(fn){try{fn(result,ok);}catch(e){console.error('[Attachment view]',e);}});});});}
function pdfDbAdd(rec,cb){pdfDbOpen(function(db){
 var tx=null,done=false,timer=setTimeout(function(){finish(false);if(tx)try{tx.abort();}catch(e){}},5000);
 function finish(ok){if(done)return;done=true;clearTimeout(timer);if(ok)pdfDbInvalidate();else libStorageWarning('Attachment save was not confirmed. Existing saved attachments were not cleared. Keep the source file and retry when storage is available.');if(cb)cb(ok);}
 if(!db){finish(false);return;}try{tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').add(cfSourceStoredRecord12HO(rec));tx.oncomplete=function(){finish(true);};tx.onerror=tx.onabort=function(){finish(false);};}catch(e){if(tx)try{tx.abort();}catch(ignore){}finish(false);}
 });}
function pdfDbPut(rec,cb){pdfDbPutMany([rec],cb);}
function pdfDbDelete(id,cb){pdfDbOpen(function(db){if(!db){if(cb)cb(false);return;}var tx,done=false;function finish(ok){if(done)return;done=true;if(ok)pdfDbInvalidate();if(cb)cb(ok);}try{tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').delete(id);tx.oncomplete=function(){finish(true);};tx.onerror=tx.onabort=function(){finish(false);};}catch(e){finish(false);}});}

function pdfDbPutMany(items,cb){if(!items||!items.length){if(cb)cb(true);return;}pdfDbOpen(function(db){libWriteStore(db,'pdfs',items,function(ok){if(ok)pdfDbInvalidate();if(cb)cb(ok);});});}
function assetLooksLikePidText(text){return ryanLooksLikePidDescription(text)||/\b\d{6}\s*-\s*AE\s*-\s*DW\s*-\s*M\s*-?\s*\d{4}\b/i.test(String(text||''))||/\bM\s*-?\s*\d{4}\b/i.test(String(text||''));}
function assetRecordType(rec,description){rec=rec||{};var kind=String(rec.kind||'').toLowerCase(),rt=String(rec.recordType||'').toLowerCase(),source=String(rec.recordTypeSource||'').toLowerCase(),txt=[description,rec.description,rec.label,rec.name].filter(Boolean).join(' '),explicitPid=assetLooksLikePidText(txt);if(kind==='image'||/^data:image\//.test(rec.dataUrl||''))return 'attachment';if(source==='pid-library')return 'pid';if(source==='attachment-library')return 'attachment';if(source==='auto')return explicitPid?'pid':'attachment';if(rt==='pid')return 'pid';if(rt==='attachment'||rt==='document')return explicitPid?'pid':'attachment';return explicitPid?'pid':'attachment';}
function assetMetadata(rec,description){rec=rec||{};var desc=String(description!=null?description:(rec.description||((typeof ryanAttachmentDescription==='function')?ryanAttachmentDescription(rec.id):''))||''),label=String(rec.label||rec.name||''),a=ryanSemanticAnchor(desc,label),b=a.referenceBinding||{},folder=b.libraryCategory||a.libraryCategory||b.crossReferenceCategory||'',parentTag=b.parentTag||a.parentTag||'',primaryTag=b.primaryTag||a.primaryTag||'',sys=b.systemTitle||a.system||'';if(!folder&&sys){var sx=ryanSystemFromDescription(sys,parentTag,b.parentInfoKey||'');folder=sx.category||sys;}if(!folder)folder='Unfiled / Description Required';return {description:desc,attachmentFolder:folder,attachmentSystem:sys||folder,parentTag:parentTag,primaryTag:primaryTag,itemType:b.itemType||ryanDescriptionItemType(desc,primaryTag)||((rec.kind==='image')?'Photo / Image':'Supporting Document')};}
function assetNormalizeRecord(rec){var copy=Object.assign({},rec),desc=(typeof ryanAttachmentDescription==='function'?ryanAttachmentDescription(copy.id):'')||copy.description||'',rt=assetRecordType(copy,desc),meta=assetMetadata(copy,desc);copy.recordType=rt;if(!copy.recordTypeSource)copy.recordTypeSource='legacy-auto';copy.description=meta.description;copy.attachmentFolder=meta.attachmentFolder;copy.attachmentSystem=meta.attachmentSystem;copy.parentTag=meta.parentTag;copy.primaryTag=meta.primaryTag;copy.itemType=meta.itemType;return copy;}
var ASSET_MIGRATION_DONE=false,ASSET_MIGRATION_RUNNING=false,ASSET_MIGRATION_WAITERS=[];
function assetMigrateLegacyRecords(cb,force){if(ASSET_MIGRATION_DONE&&!force){if(cb)cb(0);return;}if(cb)ASSET_MIGRATION_WAITERS.push(cb);if(ASSET_MIGRATION_RUNNING)return;ASSET_MIGRATION_RUNNING=true;pdfDbAll(function(recs,readOk){var changes=[],invalid=false;(recs||[]).forEach(function(r){try{var n=assetNormalizeRecord(r),changed=['recordType','recordTypeSource','description','attachmentFolder','attachmentSystem','parentTag','primaryTag','itemType'].some(function(k){return String(r[k]||'')!==String(n[k]||'');});if(changed)changes.push(n);}catch(e){invalid=true;}});function finish(ok){ASSET_MIGRATION_RUNNING=false;ASSET_MIGRATION_DONE=readOk!==false&&ok!==false&&!invalid;var q=ASSET_MIGRATION_WAITERS.splice(0);q.forEach(function(fn){try{fn(ok!==false?changes.length:0);}catch(e){console.error('[Attachment migration view]',e);}});}if(readOk===false){finish(false);return;}if(changes.length)pdfDbPutMany(changes,finish);else finish(true);},true);}
function assetTypeLabel(rec){var rt=assetRecordType(rec);if(rt==='pid')return 'P&ID PDF';if(rec&&rec.kind==='image')return 'image attachment';return 'document attachment';}
function attachmentFolderOptions(selected){var preferred=['Slug Catchers & Inlet','Inlet Compression','Dehydration & Regen','Cryo / Gas-Gas / Reflux','Demethanizer & Reboilers','Refrigeration (Propane)','Inlet Stabilizer','Residue Compression','NGL Product / Pipeline','Hot Oil System','Utilities & Drains','Site / Grounds','Operations, ESD & Troubleshooting','Equipment Reliability History (Real Shift Reports)','Unfiled / Description Required'],seen={},arr=[];preferred.concat(LIB_CATS.map(function(c){return c[0];})).forEach(function(x){if(!x||x===RYAN_PID_LIBRARY_CATEGORY||seen[x])return;seen[x]=1;arr.push(x);});return arr.map(function(x){return '<option value="'+ryanEscape(x)+'"'+(x===selected?' selected':'')+'>'+ryanEscape(x)+'</option>';}).join('');}
function pdfBytes(n){if(n<1024)return n+' B';if(n<1024*1024)return (n/1024).toFixed(0)+' KB';return (n/1024/1024).toFixed(1)+' MB';}
/* Shared file-ingest logic (added this session): originally a local closure
   inside renderPdfLibrary() only -- pulled out to global scope so the Ryan AI
   attach picker can use the EXACT same drag-and-drop/browse path into the
   SAME local library (window.PDFDB / 'pdfs' store), rather than maintaining a
   second, separate upload mechanism. Anything ingested here shows up in the
   Reference Library's P&ID list too, and vice versa -- one shared store. */
function pdfLibIngestFiles(fileList,cb,options){options=options||{};var mode=options.recordType||'auto',files=Array.from(fileList||[]).filter(function(f){var isPdf=f.type==='application/pdf'||/\.pdf$/i.test(f.name),isImg=/^image\//.test(f.type)||/\.(png|jpe?g|gif|webp)$/i.test(f.name);if(mode==='pid')return isPdf;return isPdf||isImg;});if(!files.length){if(cb)cb([]);return;}var remaining=files.length,newIds=[];files.forEach(function(f){var reader=new FileReader(),isImg=/^image\//.test(f.type)||/\.(png|jpe?g|gif|webp)$/i.test(f.name);reader.onload=function(){var source=mode==='pid'?'pid-library':(mode==='attachment'?'attachment-library':'auto'),rt=isImg?'attachment':(mode==='pid'?'pid':(mode==='attachment'?'attachment':(assetLooksLikePidText(f.name)?'pid':'attachment'))),rec={name:f.name,label:f.name.replace(/\.(pdf|png|jpe?g|gif|webp)$/i,''),dataUrl:reader.result,size:f.size,added:Date.now(),kind:isImg?'image':'pdf',recordType:rt,recordTypeSource:source,description:String(options.description||''),attachmentFolder:String(options.folder||'Unfiled / Description Required'),parentTag:String(options.parentTag||''),primaryTag:String(options.primaryTag||'')};var meta=assetMetadata(rec,rec.description);if(rt==='attachment'){rec.attachmentFolder=options.folder||meta.attachmentFolder;rec.attachmentSystem=meta.attachmentSystem;rec.parentTag=options.parentTag||meta.parentTag;rec.primaryTag=options.primaryTag||meta.primaryTag;rec.itemType=meta.itemType;}pdfDbOpen(function(db){var tx=db.transaction('pdfs','readwrite'),req=tx.objectStore('pdfs').add(cfSourceStoredRecord12HO(rec));req.onsuccess=function(e){newIds.push(e.target.result);remaining--;if(remaining===0){pdfDbInvalidate();if(cb)cb(newIds);}};req.onerror=function(){remaining--;if(remaining===0){pdfDbInvalidate();if(cb)cb(newIds);}};});};reader.readAsDataURL(f);});}
function wireDropZone(zoneId,onFiles){
 var zone=document.getElementById(zoneId); if(!zone)return;
 ['dragenter','dragover'].forEach(function(ev){zone.addEventListener(ev,function(e){e.preventDefault();e.stopPropagation();if(e.dataTransfer)e.dataTransfer.dropEffect='copy';zone.style.background='#28394a';zone.style.borderColor='#4a9eff';});});
 ['dragleave'].forEach(function(ev){zone.addEventListener(ev,function(e){e.preventDefault();e.stopPropagation();zone.style.background='#1c2733';zone.style.borderColor='#3a4a5c';});});
 zone.addEventListener('drop',function(e){e.preventDefault();e.stopPropagation();zone.style.background='#1c2733';zone.style.borderColor='#3a4a5c';if(e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files.length)onFiles(e.dataTransfer.files);});
}
function renderPdfLibraryLegacy12LQ(){var listEl=document.getElementById('libList'),detEl=document.getElementById('libDetail');if(!listEl||!detEl)return;listEl.innerHTML='<div style="padding:14px;"><div id="pdfDropZone" style="background:#1c2733;border:1.5px dashed #3a4a5c;border-radius:6px;padding:14px;text-align:center;color:#9fb0c0;font-size:13px;"><div style="margin-bottom:8px;">Learn from P&amp;ID PDFs — sources are temporary in this tab</div><button type="button" id="pdfBrowseBtn" style="background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:6px 14px;cursor:pointer;font:700 12.5px inherit;">Select P&amp;ID to learn…</button><input id="pdfUpload" type="file" accept="application/pdf,.pdf" multiple style="display:none;"></div><div style="color:#5a6b7c;font-size:10.5px;margin-top:6px;">Only P&amp;ID PDF drawings are listed here. Photos, data plates, screenshots and non-drawing documents belong in the separate Attachments popup.</div></div><div id="pdfListItems" style="padding:0 8px;"></div>';function handleFiles(fileList){pdfLibIngestFiles(fileList,function(){renderPdfLibrary();},{recordType:'pid'});}var upl=document.getElementById('pdfUpload');upl.addEventListener('change',function(e){handleFiles(e.target.files);});var browseBtn=document.getElementById('pdfBrowseBtn');browseBtn.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();upl.click();});wireDropZone('pdfDropZone',handleFiles);assetMigrateLegacyRecords(function(){pdfDbAll(function(all){var recs=all.filter(function(r){return assetRecordType(r)==='pid';}).sort(function(a,b){return (b.added||0)-(a.added||0);}),itemsEl=document.getElementById('pdfListItems');if(!itemsEl)return;if(!recs.length){itemsEl.innerHTML='<div style="color:#5a6b7c;font-size:12.5px;padding:10px;">No P&amp;ID PDFs added yet — use the button above.</div>';detEl.innerHTML='<div style="color:#5a6b7c;font-size:13px;">Select a P&amp;ID from the list, or add a PDF drawing above.</div>';return;}if(!recs.some(function(r){return String(r.id)===String(libSel.key);}))libSel.key=null;itemsEl.innerHTML=recs.map(function(r){return '<div class="pdfitem'+(String(libSel.key)===String(r.id)?' act':'')+'" data-id="'+r.id+'" style="padding:10px 8px;border-bottom:1px solid #1c2530;cursor:pointer;color:'+(String(libSel.key)===String(r.id)?'#fff':'#dce6ee')+';background:'+(String(libSel.key)===String(r.id)?'#1c2733':'transparent')+';font-size:13px;"><div style="font-weight:600;">'+ryanEscape(r.label)+'</div><div style="color:#5a6b7c;font-size:11px;">'+pdfBytes(r.size)+' · '+new Date(r.added).toLocaleDateString()+' · P&amp;ID PDF</div></div>';}).join('');itemsEl.querySelectorAll('.pdfitem').forEach(function(el){el.addEventListener('click',function(){var id=el.getAttribute('data-id'),rec=recs.filter(function(r){return String(r.id)===String(id);})[0];if(rec){libSel.key=id;renderPdfDetail(rec);itemsEl.querySelectorAll('.pdfitem').forEach(function(x){var on=x===el;x.style.background=on?'#1c2733':'transparent';x.style.color=on?'#fff':'#dce6ee';});}});});if(!libSel.key)detEl.innerHTML='<div style="color:#5a6b7c;font-size:13px;">Select a P&amp;ID from the list, or add a PDF drawing above.</div>';});});}
function dataUrlToBlobUrl(dataUrl){
 try{
  var parts=dataUrl.split(',');
  var mime=(parts[0].match(/:(.*?);/)||[])[1]||'application/pdf';
  var bin=atob(parts[1]);
  var arr=new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);
  return URL.createObjectURL(new Blob([arr],{type:mime}));
 }catch(e){return dataUrl;}
}
function renderPdfDetail(rec){
 var detEl=document.getElementById('libDetail'); if(!detEl)return;
 var blobUrl=dataUrlToBlobUrl(rec.dataUrl);
 var isImg=rec.kind==='image'||(!rec.kind&&/^data:image\//.test(rec.dataUrl||''));
 detEl.innerHTML='<div style="font-size:18px;font-weight:700;color:#eef2f7;margin-bottom:4px;">'+rec.label+'</div>'+
  '<div style="font-size:11px;color:#5a6b7c;margin-bottom:16px;">'+pdfBytes(rec.size)+' \u00b7 added '+new Date(rec.added).toLocaleString()+(isImg?' \u00b7 image':' \u00b7 PDF')+'</div>'+
  '<div style="margin-bottom:14px;">'+
  '<a data-act="pdfopen" href="'+blobUrl+'" target="_blank" rel="noopener" style="display:inline-block;text-decoration:none;background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:8px 16px;cursor:pointer;font:700 13px inherit;margin-right:8px;">Open full-size \u25B6</a>'+
  '<button data-act="pdfrename" style="background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:8px 16px;cursor:pointer;font:700 13px inherit;margin-right:8px;">Rename</button>'+
  '<button data-act="pdfdelete" style="background:#4a2020;border:1px solid #6a3030;color:#ffb0b0;border-radius:4px;padding:8px 16px;cursor:pointer;font:700 13px inherit;">Delete</button>'+
  '<div id="pdfInlineAction" style="margin-top:10px;"></div></div>'+
  (isImg?'<img src="'+blobUrl+'" style="width:100%;max-height:70vh;object-fit:contain;border:1px solid #2a3542;border-radius:4px;background:#fff;">'
        :'<embed src="'+blobUrl+'" type="application/pdf" style="width:100%;height:60vh;border:1px solid #2a3542;border-radius:4px;background:#fff;">');
 detEl.querySelector('[data-act="pdfrename"]').addEventListener('click',function(){
  var box=document.getElementById('pdfInlineAction');
  box.innerHTML='<input id="pdfRenameInput" type="text" value="'+rec.label.replace(/"/g,'&quot;')+'" style="padding:6px 8px;background:#0a0e13;border:1px solid #2c3844;border-radius:4px;color:#dce6ee;font:13px inherit;width:220px;">'+
   '<button data-act="pdfRenameOk" style="margin-left:6px;background:#1a8f3a;border:none;color:#fff;border-radius:4px;padding:6px 12px;cursor:pointer;font:700 12px inherit;">Save</button>'+
   '<button data-act="pdfRenameCancel" style="margin-left:4px;background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:6px 12px;cursor:pointer;font:700 12px inherit;">Cancel</button>';
  document.getElementById('pdfRenameInput').focus();
  box.querySelector('[data-act="pdfRenameOk"]').addEventListener('click',function(){
   var nn=document.getElementById('pdfRenameInput').value.trim();
   if(nn){rec.label=nn;pdfDbPut(rec,function(){renderPdfLibrary();renderPdfDetail(rec);});}
  });
  box.querySelector('[data-act="pdfRenameCancel"]').addEventListener('click',function(){box.innerHTML='';});
 });
 detEl.querySelector('[data-act="pdfdelete"]').addEventListener('click',function(){
  var box=document.getElementById('pdfInlineAction');
  box.innerHTML='<span style="color:#ffb0b0;font-size:12.5px;">Delete "'+rec.label+'" \u2014 this cannot be undone.</span> '+
   '<button data-act="pdfDeleteOk" style="margin-left:6px;background:#a83030;border:none;color:#fff;border-radius:4px;padding:6px 12px;cursor:pointer;font:700 12px inherit;">Yes, delete</button>'+
   '<button data-act="pdfDeleteCancel" style="margin-left:4px;background:#243140;border:1px solid #3a4a5c;color:#cfe6ff;border-radius:4px;padding:6px 12px;cursor:pointer;font:700 12px inherit;">Cancel</button>';
  box.querySelector('[data-act="pdfDeleteOk"]').addEventListener('click',function(){pdfDbDelete(rec.id,function(){libSel.key=null;renderPdfLibrary();});});
  box.querySelector('[data-act="pdfDeleteCancel"]').addEventListener('click',function(){box.innerHTML='';});
 });
}

var ATTACH_SEL={folder:'All Attachments',id:null,search:''},ATTACH_RETURN_TO_LIBRARY=false,ATTACH_BLOB_URL=null,ATTACH_SEARCH_TIMER=null;
function attachmentRecords(cb){assetMigrateLegacyRecords(function(){pdfDbAll(function(recs){cb(recs.filter(function(r){return assetRecordType(r)==='attachment';}).map(assetNormalizeRecord));});});}
