function c2advisorSectionHtml(tgtC2ngl){
 var s=C2CALC_STATE, gpm=s._liveGpm, curC2=s._liveC2ngl;
 var curBPD=c2bpd(gpm,curC2);
 var haveTarget=!isNaN(tgtC2ngl);
 var targetBPD=haveTarget?c2bpd(gpm,tgtC2ngl):null;
 var stdTargets=[0.5,1,2,3,5,8,10,15,20];
 var tableRows=stdTargets.map(function(p){
  var bpd=c2bpd(gpm,p),delta=bpd-curBPD;
  return '<tr'+(haveTarget&&Math.abs(p-tgtC2ngl)<0.001?' style="background:#1c2a1c;"':'')+'>'+
   '<td style="padding:3px 8px;color:#9fb0c0;">'+p.toFixed(2)+'%</td>'+
   '<td style="padding:3px 8px;color:#eef2f7;font-family:Consolas,monospace;">'+Math.round(bpd).toLocaleString()+'</td>'+
   '<td style="padding:3px 8px;color:'+(delta>=0?'#9fe6c0':'#ffb0a0')+';font-family:Consolas,monospace;">'+(delta>=0?'+':'')+Math.round(delta).toLocaleString()+'</td>'+
  '</tr>';
 }).join('');
 var match=haveTarget?c2advisorTrendMatch(tgtC2ngl):null;
 var trendHtml;
 if(!haveTarget){
  trendHtml='<div style="color:#8a7a5a;font-size:12px;">Enter a target C2-in-NGL above (section 2) to see barrels-per-day and a trend-based confidence check.</div>';
 } else if(!match){
  trendHtml='<div style="color:#8a7a5a;font-size:12px;">Not enough trend history yet to check confidence (need at least 2 samples of C2-in-NGL/bottoms-temp/tower-pressure recorded together \u2014 open the EQT board and let the plant run a bit; trend history is only recorded while that board is open).</div>';
 } else {
  var confColor=match.confidence.indexOf('High')===0?'#9fe6c0':(match.confidence.indexOf('Medium')===0?'#ffd98a':'#ffb0a0');
  trendHtml='<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px 20px;font-size:12.5px;margin-bottom:8px;">'+
   c2calcResult('Confidence',match.confidence,'')+
   c2calcResult('Nearest trend sample distance',match.dist.toFixed(3),'mol% C2')+
   c2calcResult('Bottoms temp at nearest match',match.bottomsAtMatch.toFixed(1),'\u00b0F')+
   c2calcResult('Tower pressure at nearest match',match.pressureAtMatch.toFixed(0),'psig')+
   c2calcResult('Best C2 seen in current trend window',match.hi.toFixed(2),'mol%')+
   c2calcResult('Lowest C2 seen in current trend window',match.lo.toFixed(2),'mol%')+
   c2calcResult('Trend samples available',match.n+' / '+TREND_MAX,'(rolling window)')+
  '</div>'+
  '<div style="background:#0a0e13;border:1px solid '+confColor+';border-radius:4px;padding:6px 10px;font-size:11.5px;color:'+confColor+';">'+
   (match.outsideRange?'Target is outside anything this plant has actually shown in its recent trend window \u2014 treat the bottoms/top-temp suggestion in section 2 as an educated estimate, capped by real operating limits, not a confirmed operating point.':
   'Target falls within the range this plant has actually shown recently \u2014 the nearest real trend sample above is a reasonable cross-check for the section-2 suggestion.')+
  '</div>';
 }
 return '<div style="background:#14201a;border:1px solid #2a5a3a;border-radius:6px;padding:10px 12px;margin-bottom:14px;">'+
  '<div style="font-weight:700;color:#9ff0b6;margin-bottom:4px;">3) C2 Barrels-Per-Day + trend-based confidence (Ryan\u2019s C2 Advisor v19 spreadsheet)</div>'+
  '<div style="font-size:11px;color:#8a97a4;margin-bottom:8px;">Formula: C2 BPD = NGL GPM \u00d7 (C2% \u00f7 100) \u00d7 34.2857. Uses live GPM ('+gpm.toFixed(0)+' GPM, same number as the FT-8000A custody meter) and live C2-in-NGL ('+curC2.toFixed(2)+' mol%). Unit note: the spreadsheet defines this in LIQUID VOLUME %, this sim tracks MOL% \u2014 treat BPD here as an approximation using the same formula, not a rigorous LV% conversion.</div>'+
  c2calcResult('Current C2 BPD',Math.round(curBPD).toLocaleString(),'bbl/d')+
  (haveTarget?c2calcResult('Target C2 BPD (from section 2 input)',Math.round(targetBPD).toLocaleString(),'bbl/d'):'')+
  (haveTarget?c2calcResult('Additional BPD vs. current',(targetBPD-curBPD>=0?'+':'')+Math.round(targetBPD-curBPD).toLocaleString(),'bbl/d'):'')+
  '<div style="margin:10px 0 4px;font-weight:700;color:#dce6ee;font-size:12px;">Quick lookup table (live GPM held constant)</div>'+
  '<table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:12px;"><thead><tr style="color:#6a7684;text-align:left;"><th style="padding:3px 8px;">Target C2</th><th style="padding:3px 8px;">BPD</th><th style="padding:3px 8px;">vs. current</th></tr></thead><tbody>'+tableRows+'</tbody></table>'+
  '<div style="font-weight:700;color:#dce6ee;margin-bottom:6px;font-size:12px;">Trend-based confidence check</div>'+
  trendHtml+
 '</div>';
}
function c2calcField(id,label,val,optional){
 return '<div><label style="display:block;color:#9fb0c0;font-size:11px;margin-bottom:2px;">'+label+(optional?' <i style="color:#5a6b7c;">(optional)</i>':'')+'</label>'+
  '<input id="'+id+'" type="number" step="any" value="'+(val===''?'':val)+'" style="width:100%;background:#0a0e13;border:1px solid #2c3844;border-radius:4px;color:#dce6ee;padding:6px 8px;font:13px Consolas,monospace;box-sizing:border-box;"></div>';
}
function c2calcResult(label,val,unit){
 return '<div style="display:flex;justify-content:space-between;border-bottom:1px solid #1c2530;padding:2px 0;"><span style="color:#8a97a4;">'+label+'</span><span style="color:#eef2f7;font-weight:700;font-family:Consolas,monospace;">'+val+' <span style="color:#5a6b7c;font-weight:400;">'+unit+'</span></span></div>';
}
