function ryanSaveConversationHistory(){try{var compact=RYAN_AI_HISTORY.slice(-20).map(function(m){return {role:m.role,content:String(m.content||'').slice(0,6000),mode:m.mode||null,scanLabel:m.scanLabel||null,cost:m.cost||null,lotoId:m.lotoId||null,workplan:m.workplan||null,createdAt:m.createdAt||null,qaArchiveId:m.qaArchiveId||null,qaArchiveCache:!!m.qaArchiveCache,qaAnsweredAt:m.qaAnsweredAt||null,qaPartial:!!m.qaPartial,qaDurable:m.qaDurable!==false};});localStorage.setItem('ryanAiConversationHistory',JSON.stringify(compact));}catch(_e){}}
