function ryanMemoryMatches(q,m){var toks=String(q||'').toLowerCase().split(/[^a-z0-9-]+/).filter(function(t){return t.length>2;});if(!toks.length)return true;var h=(m.title+' '+m.text+' '+(m.tags||[]).join(' ')+' '+(m.equipmentIds||[]).join(' ')).toLowerCase();return toks.some(function(t){return h.indexOf(t)>=0;});}
