function ryanNormalizeOperatingProfile(raw,meta){raw=raw||{};meta=meta||{};var title=String(raw.title||meta.title||'Operating experience').trim().slice(0,220),summary=String(raw.summary||meta.summary||'').trim().slice(0,5000),sourceType=String(meta.sourceType||raw.sourceType||'HISTORICAL_OPERATING_EVIDENCE').slice(0,80),sourceId=String(meta.sourceId||raw.sourceId||'').slice(0,240),sourceLabel=String(meta.sourceLabel||raw.sourceLabel||'').slice(0,240),startTime=ryanOpIso(raw.startTime||meta.startTime),endTime=ryanOpIso(raw.endTime||meta.endTime),stable=[sourceType,sourceId,title,startTime,endTime].join('|'),id='op-'+ryanHash(stable),old=(RYAN_CACHE.operatingProfiles||[]).filter(function(x){return x.id===id;})[0],now=new Date().toISOString();return {id:id,kind:String(meta.kind||raw.kind||'OPERATING_EPISODE').slice(0,80),title:title||'Operating experience',summary:summary,system:String(raw.system||meta.system||'').slice(0,160),equipmentIds:ryanOpArray(raw.equipmentIds||meta.equipmentIds,40,80),tags:ryanOpArray(raw.tags||meta.tags,60,100),conditions:ryanOpArray(raw.conditions,30,900),responses:ryanOpArray(raw.responses,30,900),relationships:ryanOpArray(raw.relationships,30,1000),normalRanges:ryanOpArray(raw.normalRanges,30,700),outliers:ryanOpArray(raw.outliers,20,800),troubleshootingCues:ryanOpArray(raw.troubleshootingCues,30,1000),doNotTreatAs:ryanOpArray(raw.doNotTreatAs,20,700),confidence:String(raw.confidence||meta.confidence||'medium').toLowerCase().slice(0,20),evidenceCount:Math.max(0,Number(raw.evidenceCount||meta.evidenceCount||0)||0),sourceType:sourceType,sourceId:sourceId,sourceLabel:sourceLabel,trust:String(meta.trust||raw.trust||'HISTORICAL_OPERATING_EVIDENCE').slice(0,80),verificationStatus:String(meta.verificationStatus||raw.verificationStatus||'HISTORICAL_OPERATING_EVIDENCE').slice(0,100),status:String(raw.status||meta.status||'active').slice(0,30),startTime:startTime,endTime:endTime,provenance:String(meta.provenance||raw.provenance||sourceLabel||sourceType).slice(0,600),autoInstalled:!!meta.autoInstalled,createdAt:old&&old.createdAt?old.createdAt:now,updatedAt:now};}
function ryanSaveOperatingProfiles(records,meta,cb){var src=Array.isArray(records)?records:[],items=src.map(function(r){return ryanNormalizeOperatingProfile(r,meta);}).filter(function(r){return r.summary||r.conditions.length||r.responses.length||r.relationships.length||r.normalRanges.length;});if(!items.length){if(cb)cb([],false);return;}ryanStoreAll('operatingProfiles',items,function(ok){if(ok===false){if(cb)cb([],false);return;}ryanRefreshCache(function(){if(cb)cb(items,true);});});}
function ryanDeleteOperatingProfile(id){try{var a=ryanBrainFallbackLoad('operatingProfiles').filter(function(x){return x.id!==id;});localStorage.setItem(ryanBrainFallbackKey('operatingProfiles'),JSON.stringify(a));}catch(_e){}ryanBrainOpen(function(db){if(!db||!db.objectStoreNames.contains('operatingProfiles')){ryanRefreshCache(function(){askRyanRender();});return;}try{var tx=db.transaction('operatingProfiles','readwrite');tx.objectStore('operatingProfiles').delete(id);tx.oncomplete=function(){ryanRefreshCache(function(){askRyanRender();});};tx.onerror=function(){ryanRefreshCache(function(){askRyanRender();});};}catch(e){ryanRefreshCache(function(){askRyanRender();});}});}
function ryanOperatingProfileScore(q,p){var toks=String(q||'').toLowerCase().split(/[^a-z0-9-]+/).filter(function(t){return t.length>2&&!CF_STOPWORDS[t];}),head=(String(p.title||'')+' '+String(p.system||'')+' '+(p.equipmentIds||[]).join(' ')+' '+(p.tags||[]).join(' ')+' '+String(p.sourceLabel||'')).toLowerCase(),all=(head+' '+String(p.summary||'')+' '+(p.conditions||[]).join(' ')+' '+(p.responses||[]).join(' ')+' '+(p.relationships||[]).join(' ')+' '+(p.troubleshootingCues||[]).join(' ')).toLowerCase(),score=0;toks.forEach(function(t){if(head.indexOf(t)>=0)score+=6;else if(all.indexOf(t)>=0)score+=2;});if(/report|shift|histor|normal|usual|previous|past/i.test(q)&&/REPORT/.test(p.sourceType||''))score+=3;if(/trend|changed|first|drift|oscillat/i.test(q)&&/TREND/.test(p.sourceType||''))score+=3;return score;}
