function ryanSelfLearnFromExchange(userText,assistantText){
 if(localStorage.getItem('ryanSelfLearn')==='off')return;
 var combined=String(userText||'').trim(); if(combined.length<12)return;
 ryanFetch({message:'Extract durable plant-specific memories from this exchange. Return JSON only: {"memories":[{"text":"...","title":"...","equipmentIds":[],"tags":[],"confidence":"high|medium|low"}]}. Keep only facts/preferences/operating observations explicitly supplied by the operator or clearly supported by the supplied simulator context. Do not store generic theory, guesses, temporary live values, passwords, API keys, or safety-critical setpoints unless explicitly source-backed. If nothing durable, return {"memories":[]}.\n\nOPERATOR:\n'+combined+'\n\nRYAN RESPONSE:\n'+String(assistantText||'').slice(0,5000),context:'',mode:'memory_extract',history:[],password:RYAN_AI_PW}).then(function(res){
  if(!res.ok||!res.d)return; var obj=res.d.memoryExtraction||null;if(!obj){try{obj=JSON.parse(res.d.reply||'{}');}catch(e){return;}} var arr=(obj&&obj.memories)||[];
  arr.slice(0,8).forEach(function(x){var txt=String(x.text||'').trim();if(!txt)return;var dup=(RYAN_CACHE.memories||[]).some(function(m){return m.text.toLowerCase()===txt.toLowerCase();});if(dup)return;ryanSaveMemory(txt,{title:x.title||'Ryan self-learned memory',sourceType:'AI_SELF_LEARNED',trust:'PROVISIONAL_SELF_LEARNED',status:'provisional',equipmentIds:x.equipmentIds||[],tags:x.tags||[],provenance:'Automatically extracted from Ryan conversation'});});
 }).catch(function(){});
}
function ryanSeedIfNeeded(){
 ryanLoadAll('documents',function(docs){
  if(docs.length>0){ryanRefreshCache();return;} /* already seeded -- exact dedup-by-identity rule, same as server version */
  var docHash=ryanHash('Ariel KBU-KBZ Maintenance & Repair Manual|Ariel Corporation|2026-04-20');
  var doc={id:'doc-'+docHash,title:'Ariel KBU-KBZ Maintenance & Repair Manual',manufacturer:'Ariel Corporation',equipmentIds:['C-4100','C-4200','C-6100','C-6200','C-6300'],knowledgeClass:'oem_manual',sourceType:'oem_manual',revisionDate:'2026-04-20',status:'active',importedAt:new Date().toISOString()};
  ryanStoreAll('documents',[doc],function(){
   var props=RYAN_SEED_FACTS.map(function(f,i){
    return {id:'prop-'+docHash+'-'+i,sourceDocumentId:doc.id,sourcePage:f.page,equipmentIds:doc.equipmentIds,statement:f.statement,classification:f.classification,status:'staged',approvedAt:null,createdAt:new Date().toISOString()};
   });
   var pmTemplates=RYAN_SEED_PM.map(function(t,i){
    return {id:'pm-'+docHash+'-'+i,sourceDocumentId:doc.id,equipmentIds:doc.equipmentIds,template:t,status:'draft',note:'DRAFT ONLY. Requires reconciliation of duty classification, runtime/start counters, existing CMMS strategy, and packager requirements per unit before any real schedule can be created. NOT APPROVED - FIELD VERIFICATION REQUIRED.',importedAt:new Date().toISOString()};
   });
   ryanStoreAll('proposals',props,function(){
    ryanStoreAll('pmTemplates',pmTemplates,function(){ryanRefreshCache();});
   });
  });
 });
}
function ryanApprove(id){
 /* Deliberately no confirm() gate -- this file has no established pattern of confirm-dialogs
    on other consequential single-click actions (valve toggles, AUTO/MAN switches, etc.), and a
    clearly-labeled "Approve" button click is already the deliberate act; friction beyond that
    wasn't buying real safety here since Reject remains a one-click path either way. */
 var p=RYAN_CACHE.proposals.find(function(x){return x.id===id;}); if(!p||p.status!=='staged')return;
 p.status='approved'; p.approvedAt=new Date().toISOString();
 ryanStoreAll('proposals',[p],function(){ryanRefreshCache(cmdRenderTab);});
}
function ryanReject(id){
 var p=RYAN_CACHE.proposals.find(function(x){return x.id===id;}); if(!p||p.status!=='staged')return;
 var reason=prompt('Reason for rejecting this proposal (optional):','');
 if(reason===null)return;
 p.status='rejected'; p.approvedAt=new Date().toISOString(); p.rejectionReason=reason||null;
 ryanStoreAll('proposals',[p],function(){ryanRefreshCache(cmdRenderTab);});
}
function ryanApprovedSearch(q){
 q=(q||'').toLowerCase(); var terms=q.split(/\s+/).filter(function(t){return t.length>2&&!CF_STOPWORDS[t];});
 if(!terms.length)return [];
 var approved=RYAN_CACHE.proposals.filter(function(p){return p.status==='approved';});
 var scored=approved.map(function(p){
  var hay=p.statement.toLowerCase(); var score=0;
  terms.forEach(function(t){if(hay.indexOf(t)!==-1)score++;});
  return {p:p,score:score};
 }).filter(function(s){return s.score>0;}).sort(function(a,b){return b.score-a.score;});
 return scored.map(function(s){
  var doc=RYAN_CACHE.documents.find(function(d){return d.id===s.p.sourceDocumentId;});
  return {statement:s.p.statement,classification:s.p.classification,equipmentIds:s.p.equipmentIds,citation:doc?{documentTitle:doc.title,page:s.p.sourcePage}:{documentTitle:'unknown source',page:s.p.sourcePage}};
 });
}
if(window.requestIdleCallback)requestIdleCallback(ryanSeedIfNeeded,{timeout:4000});else setTimeout(ryanSeedIfNeeded,50);
/* Uses requestIdleCallback where available -- the correct browser primitive for "run this once
   the main thread actually has free time," rather than hoping a fixed setTimeout delay happens
   to land in a gap. Matters here because the initial Three.js scene build can keep the main
   thread busy for a real, hardware-dependent amount of time (worse under software-rendered
   WebGL than real GPU acceleration), during which IndexedDB's own callbacks are also queued
   behind whatever else is running. The 4000ms timeout is a ceiling, not a target -- it forces
   the seed attempt even if the browser never reports a large-enough idle window, rather than
   waiting forever. Either way, RYAN_CACHE.ready plus the loading-state handling and the
   auto-poll in openCmdCenter()/ryanPollUntilReady() below mean the UI stays honest about
   what's actually loaded rather than showing a confident-looking zero. */
window.RYAN_DEBUG={cache:function(){return RYAN_CACHE;}}; /* read-only inspector, same philosophy as window.CLEARFORK_HEALTH */
