/* ═══ Engineering Review (added this session): a real, deterministic
   continuous-QA report, NOT an AI call -- every line below is a genuine check
   against this file's own live data or its own source text, not a language
   model's impression of the file. Scoped down from the full "equipment
   passport / LOTO-integrated" vision Ryan described: this is a real first
   version covering what can actually be checked mechanically today. Anything
   that vision proposed but this doesn't yet do is named honestly in the
   report itself, not silently dropped. ═══ */
var CMD_ENG_REVIEW={lastRun:null,report:null,running:false};
function engCheckDanglingRefLibLinks(){
 /* Every LIB_CATS entry should point at a real INFO key. A dangling one means
    someone added a category entry but the INFO object entry never got written
    (or was renamed and the category list wasn't updated) -- a genuine,
    testable "broken link" in the Reference Library, at runtime, no source
    fetch needed since both LIB_CATS and INFO are live objects already. */
 var missing=[];
 LIB_CATS.forEach(function(cat){cat[1].forEach(function(k){if(!(k in INFO))missing.push(cat[0]+' \u203a '+k);});});
 return missing;
}
function engCheckDuplicateQuizQuestions(){
 /* QUIZ_BANK is a plain array (unlike INFO, arrays don't silently de-duplicate
    repeated content) so an exact duplicate question really would show up
    twice at runtime -- a genuine, cheap check. */
 var seen={},dups=[];
 QUIZ_BANK.forEach(function(q){var key=(q.q||'').trim().toLowerCase();if(!key)return;if(seen[key])dups.push(q.q);else seen[key]=1;});
 return dups;
}
function engCheckPidReconciliationStatus(){
 /* Pulls real counts out of this file's own pid_m* indexed records (added
    across this and earlier sessions) -- specifically whether each record's
    own MODEL-RECONCILIATION STATUS line says 3D work is still outstanding.
    This is honest text-pattern matching against what WE wrote ourselves, not
    a claim that it independently re-derived P&ID-vs-3D truth from scratch. */
 var pidKeys=Object.keys(INFO).filter(function(k){return k.indexOf('pid_m')===0;});
 var pending=[],done=[];
 pidKeys.forEach(function(k){
  var rec=INFO[k];
  var statusLine=(rec.d||[]).filter(function(line){return /MODEL-RECONCILIATION STATUS/i.test(line);})[0]||'';
  if(/not yet/i.test(statusLine))pending.push(k);
  else if(statusLine)done.push(k);
 });
 return {pending:pending,done:done,total:pidKeys.length};
}
function engCheckDuplicateSourceKeys(src){
 /* Source-level check (needs the actual page text, since by the time INFO/EQP
    exist as live objects, JS's own "last definition wins" behavior has ALREADY
    silently erased any earlier duplicate -- there is no runtime trace left to
    find). Same self-fetch technique Ryan Scan already uses for code-section
    scanning. Looks for duplicate top-level keys inside the INFO{} object
    literal specifically (the highest-value place for this bug, per this
    project's own documented history of "last definition wins" incidents). */
 var m=src.match(/var INFO = \{[\s\S]*?\n\};/);
 if(!m)return {error:'Could not locate the INFO{} object in the fetched source.'};
 var body=m[0];
 var keyRe=/\n\s*([A-Za-z_][A-Za-z0-9_]*):\{/g;
 var counts={},match;
 while((match=keyRe.exec(body))){counts[match[1]]=(counts[match[1]]||0)+1;}
 var dups=Object.keys(counts).filter(function(k){return counts[k]>1;});
 return {dups:dups};
}
function cmdRunEngReview(cb){
 CMD_ENG_REVIEW.running=true;
 var danglingLinks=engCheckDanglingRefLibLinks();
 var dupQuestions=engCheckDuplicateQuizQuestions();
 var pidStatus=engCheckPidReconciliationStatus();
 ryanScanFetchSrc(function(src){ /* reuses the exact same self-fetch cache Ryan Scan already built */
  var dupKeys=src?engCheckDuplicateSourceKeys(src):{error:'Self-fetch failed \u2014 could not read the page\u2019s own source this run.'};
  CMD_ENG_REVIEW.report={
   ts:new Date().toISOString(),
   danglingLinks:danglingLinks,
   dupQuestions:dupQuestions,
   pidStatus:pidStatus,
   dupKeys:dupKeys,
   boardCount:Object.keys(SCR).length
  };
  CMD_ENG_REVIEW.lastRun=Date.now();
  CMD_ENG_REVIEW.running=false;
  if(cb)cb();
 });
}
function cmdEngReviewTab(){
 var r=CMD_ENG_REVIEW.report;
 var html='<div style="font-weight:700;color:#dce6ee;margin-bottom:6px;">\ud83d\udd0e Engineering Review</div>'+
  '<div style="font-size:11.5px;color:#8a97a4;margin-bottom:12px;">Real, deterministic checks against this file\u2019s own live data and its own source text \u2014 not an AI-generated impression of the file. Run it any time after uploading new material or making changes, as a continuous-QA pass instead of waiting for a single big review date.</div>'+
  '<button data-engrun="1" style="background:#1c3a5c;border:1px solid #3a6a9c;color:#bfe0ff;border-radius:4px;padding:8px 16px;cursor:pointer;font:700 12.5px inherit;margin-bottom:14px;">'+(CMD_ENG_REVIEW.running?'Running\u2026':'\u25b6\ufe0f Run Engineering Review')+'</button>';
 if(!r){
  html+='<div style="color:#6a7684;font-size:12px;">No review run yet this session.</div>';
  return html;
 }
 var dq=r.dupQuestions,dl=r.danglingLinks,dk=r.dupKeys,ps=r.pidStatus;
 function line(ok,label){return '<div style="padding:4px 0;border-bottom:1px solid #1c2530;color:'+(ok?'#9fe6c0':'#ffb0a0')+';font-family:Consolas,monospace;font-size:12.5px;">'+(ok?'\u2713 ':'\u2717 ')+label+'</div>';}
 html+='<div style="background:#0a0e13;border:1px solid #2a3542;border-radius:6px;padding:12px 16px;margin-bottom:12px;">'+
  '<div style="color:#6a7684;font-size:10.5px;margin-bottom:8px;">Report generated '+new Date(r.ts).toLocaleString()+'</div>'+
  line(dl.length===0,dl.length+' dangling Reference Library link(s) (category lists a key with no matching INFO entry)')+
  line(dq.length===0,dq.length+' duplicate quiz question(s) found in QUIZ_BANK')+
  (dk.error?line(false,'Duplicate-key source scan: '+dk.error):line(dk.dups.length===0,dk.dups.length+' duplicate INFO{} key(s) found in the page\u2019s own source (silently overwritten by "last definition wins" \u2014 real bug class this project has hit before)'))+
  line(true,r.boardCount+' control board renderer(s) registered (see Board Audit tab for the full list \u2014 existence only, not a functional test)')+
  line(ps.pending.length===0,ps.pending.length+' of '+ps.total+' indexed P&ID drawing(s) still show 3D-reconciliation work outstanding (pulled from each pid_m* record\u2019s own MODEL-RECONCILIATION STATUS line)')+
 '</div>';
 if(dl.length)html+='<div style="margin-bottom:10px;"><b style="color:#ffb0a0;font-size:11.5px;">Dangling links:</b><ul style="margin:4px 0 0 18px;padding:0;font-size:11.5px;color:#c3ccd4;">'+dl.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul></div>';
 if(dq.length)html+='<div style="margin-bottom:10px;"><b style="color:#ffb0a0;font-size:11.5px;">Duplicate quiz questions:</b><ul style="margin:4px 0 0 18px;padding:0;font-size:11.5px;color:#c3ccd4;">'+dq.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul></div>';
 if(!dk.error&&dk.dups.length)html+='<div style="margin-bottom:10px;"><b style="color:#ffb0a0;font-size:11.5px;">Duplicate INFO{} source keys:</b><ul style="margin:4px 0 0 18px;padding:0;font-size:11.5px;color:#c3ccd4;">'+dk.dups.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul></div>';
 if(ps.pending.length)html+='<div style="margin-bottom:10px;"><b style="color:#ffd98a;font-size:11.5px;">P&ID drawings with 3D work still outstanding:</b><ul style="margin:4px 0 0 18px;padding:0;font-size:11.5px;color:#c3ccd4;">'+ps.pending.map(function(x){return '<li>'+x+'</li>';}).join('')+'</ul></div>';
 html+='<div style="background:#1a1710;border:1px solid #5c4a1c;border-radius:6px;padding:10px 12px;font-size:11px;color:#c9b98a;">'+
  '<b style="color:#ffd98a;">Explicitly NOT checked yet</b> (named honestly, not silently skipped): duplicate valve TAGS in the 3D model or on control screens; missing manual valves/PSVs/transmitters compared line-by-line against a specific P&ID (that needs structured per-drawing tag lists this project doesn\u2019t maintain yet, not just prose Reference Library entries); control-board-vs-P&ID discrepancies beyond "does a renderer exist"; equipment-moved detection (nothing currently fingerprints 3D coordinates run-to-run to detect that). These are real, valuable checks for a future version \u2014 this first version only ships checks that could actually be built and verified this session.'+
  '</div>';
 return html;
}

