 h.concerns.forEach(function(c){if(c[0]!=='NONE')lines.push('Concern ['+c[0]+']: '+c[1]);});
 lines.push('--- ROTATING EQUIPMENT ---');
 Object.keys(PLANT.cmp||{}).forEach(function(k){var c=PLANT.cmp[k]||{};lines.push((c.name||k)+': '+(c.run?'RUNNING':'STOPPED')+', step '+(c.step==null?'?':c.step)+'/'+(c.maxstep==null?'?':c.maxstep)+', suction '+fmtRyanNum(c.suc)+' psig, discharge '+fmtRyanNum(c.dis)+' psig, flow '+fmtRyanNum(c.flow)+', oilP '+fmtRyanNum(c.oilP)+' psig, oilT '+fmtRyanNum(c.oilT)+' F, dischargeT '+fmtRyanNum(c.discT)+' F, RPM '+fmtRyanNum(c.rpm));});
 lines.push('--- CONTROL LOOPS / BOARD VALUES ---');
 Object.keys(PLANT.L||{}).forEach(function(k){var l=PLANT.L[k]||{};lines.push(k+': PV '+fmtRyanNum(l.pv)+' '+(l.u||'')+', SP '+fmtRyanNum(l.sp)+' '+(l.u||'')+', OUT '+fmtRyanNum(l.out)+'%, MODE '+(l.man?'MANUAL':'AUTO'));});
 lines.push('--- VALVE / DISCRETE STATES ---');
 Object.keys(PLANT.valves||{}).forEach(function(k){var v=PLANT.valves[k];lines.push(k+': '+(typeof v==='number'?(v>=0&&v<=1?(v?'OPEN':'CLOSED'):fmtRyanNum(v)+'%'):String(v)));});
 if(typeof FILTER_RULES!=='undefined'){lines.push('--- FILTER HEALTH ---');Object.keys(FILTER_RULES).forEach(function(k){var r=FILTER_RULES[k];lines.push(r.name+': '+filterDP(k).toFixed(2)+' '+r.unit+' | '+filterStatus(k)+(r.change!=null?' | change '+r.change:'')+(r.trip!=null?' | trip '+r.trip:''));});}
 if(SCEN&&SCEN.log&&SCEN.log.length){lines.push('--- RECENT / ACTIVE ALARM LOG ---');SCEN.log.slice(0,12).forEach(function(a){lines.push((a&&a.m)||String(a));});}
