function ryanLatestLearnedDocument(){
 try{
  var docs=(RYAN_CACHE.documents||[]).filter(function(d){return d&&(d.sourceType==='ai_digest'||d.knowledgeClass==='ai_digest');});
  if(!docs.length)return null;
  var preferred='';try{preferred=localStorage.getItem('ryanLastLearnedDocId')||'';}catch(_e){}
  if(preferred){var hit=docs.filter(function(d){return String(d.id)===String(preferred);})[0];if(hit)return hit;}
  return docs.slice().sort(function(a,b){return String(b.importedAt||b.revisionDate||'').localeCompare(String(a.importedAt||a.revisionDate||''));})[0]||null;
 }catch(e){return null;}
}
function ryanIsLearnedDocumentQuery(q){
 var t=String(q||'').toLowerCase();
 return /what\s+(did|have)\s+you\s+learn|what\s+you\s+learn|what.*learned.*(p\s*&\s*id|pid|drawing|document|manual)|learned\s+from\s+(the\s+)?(p\s*&\s*id|pid|drawing|document|manual)|according\s+to\s+(the\s+)?(learned|p\s*&\s*id|pid|drawing)|based\s+on\s+(the\s+)?(p\s*&\s*id|pid|drawing)|what.*(p\s*&\s*id|pid).*say/.test(t);
}
function ryanLearnedFactsForQuestion(q,limit){
 try{
  limit=Math.max(1,Math.min(Number(limit)||32,48));
  var props=(RYAN_CACHE.proposals||[]).filter(function(p){return p&&p.statement&&(p.status==='staged'||p.status==='approved');});
  if(!props.length)return [];
  var docs={};(RYAN_CACHE.documents||[]).forEach(function(d){docs[String(d.id)]=d;});
  var latest=ryanLatestLearnedDocument();
  var t=String(q||'').toLowerCase(), general=ryanIsLearnedDocumentQuery(q);
  var terms=t.split(/[^a-z0-9-]+/).filter(function(x){return x.length>2&&!/^(what|did|have|you|learn|learned|from|the|this|that|with|about|tell|show|according|based|pid|document|drawing)$/.test(x);});
  if(!general&&!terms.length)return [];
  var ranked=props.map(function(p){
   var d=docs[String(p.sourceDocumentId)]||{};var hay=(String(p.statement)+' '+String(p.classification||'')+' '+String(p.sourcePage||'')+' '+String(d.title||'')+' '+(p.equipmentIds||[]).join(' ')).toLowerCase();
   var score=0;terms.forEach(function(term){if(hay.indexOf(term)>=0)score+=3;});
   if(latest&&String(p.sourceDocumentId)===String(latest.id))score+=general?20:4;
   if(p.status==='approved')score+=1;
   return {p:p,d:d,score:score};
  }).sort(function(a,b){return b.score-a.score||String(b.d.importedAt||'').localeCompare(String(a.d.importedAt||''));});
  if(!general&&terms.length){if(ranked.some(function(x){return x.score>4;}))ranked=ranked.filter(function(x){return x.score>4;});else return [];}
  else if(general&&latest)ranked=ranked.filter(function(x){return String(x.p.sourceDocumentId)===String(latest.id);});
  return ranked.slice(0,limit).map(function(x){return {statement:String(x.p.statement||'').slice(0,1200),source:(x.d.title||x.p.sourceDocumentId||'learned document'),page:x.p.sourcePage||null,verificationStatus:x.p.verificationStatus||'DOCUMENT_EXTRACTED_UNVERIFIED',classification:x.p.classification||'other',equipmentIds:Array.isArray(x.p.equipmentIds)?x.p.equipmentIds.slice(0,12):[],confidence:x.p.confidence||null};});
 }catch(e){return [];}
}
function ryanLocalLearnedSummary(q){
 if(!ryanIsLearnedDocumentQuery(q))return null;
 var doc=ryanLatestLearnedDocument();if(!doc)return null;
 var props=(RYAN_CACHE.proposals||[]).filter(function(p){return p&&p.statement&&String(p.sourceDocumentId)===String(doc.id)&&(p.status==='staged'||p.status==='approved');});
 if(!props.length)return null;
 var counts={}, tags={}, approved=0;
 props.forEach(function(p){var c=String(p.classification||'other');counts[c]=(counts[c]||0)+1;if(p.status==='approved')approved++;(p.equipmentIds||[]).forEach(function(x){if(x)tags[String(x)]=1;});});
 var cats=Object.keys(counts).sort(function(a,b){return counts[b]-counts[a];}).slice(0,8).map(function(k){return k+' '+counts[k];}).join(', ');
 var samples=props.slice(0,14).map(function(p,i){return (i+1)+'. '+String(p.statement||'').slice(0,260)+(p.sourcePage?' [page/source '+p.sourcePage+']':'');}).join('\n');
 return 'I retained '+props.length+' facts from **'+String(doc.title||'the learned document')+'**. '+(approved?approved+' are approved; ':'')+(props.length-approved)+' remain DOCUMENT_EXTRACTED_UNVERIFIED until reviewed/verified.\n\nIndexed categories: '+(cats||'other')+'.'+(Object.keys(tags).length?'\nEquipment/tag references indexed: '+Object.keys(tags).slice(0,24).join(', ')+(Object.keys(tags).length>24?' …':'')+'.':'')+'\n\nRepresentative retained facts:\n'+samples+'\n\nAsk me about a specific tag, flow path, controller, interlock, reboiler, valve, or LOTO boundary and I will retrieve only the matching retained facts instead of reopening the PDF.';
}
