  attachment.contentFingerprint=ryanAttachmentFingerprint(attachment);var _dup=ryanFindLearnedDuplicate(attachment.contentFingerprint);if(_dup){out.innerHTML='<div style="background:#102a1c;border:1px solid #2a6a3a;border-radius:6px;padding:10px 12px;color:#c9f5d5;font-size:12.5px;"><b>Duplicate source detected.</b><br>This PDF/image has already been fully learned. Ryan did not create duplicate facts.</div>';return;}
  var mt=String(attachment.mediaType||'').toLowerCase();if(mt==='image/jpg')mt='image/jpeg';var isImage=/^image\/(jpeg|png|gif|webp)$/.test(mt);
