wireDropZone('attachmentDropZone',function(files){pdfLibIngestFiles(files,function(ids){if(ids&&ids.length)ATTACH_SEL.id=String(ids[ids.length-1]);renderAttachmentLibrary();},{recordType:'attachment'});});
