var QHD={run:true,timer:null,tag:'C-1140',curKey:'c1140',units:{c1140:true,c1141:false,c1142:false},fans:{a1343a:true,a1343b:true,a1343c:true},Nrun:1,pduty:440,capSP:17.0,actual:19.0,suctP:19.0,suctT:-3.2,suctSH:10,discP:207.9,discT:167.7,discSH:32,oilP:192.2,oilT:140.2,sep:168.3,filt:-2.6,amps:126,fla:71,kw:785,runhrs:21584,vibDE:0.40,vibODE:0.35,capSlide:74,volSlide:2.5,tevap:7,chill:13,tcond:120,cr:5.0,cop:2.33,kwton:1.51,duty:520,condDuty:743,pegged:false};
/* ═══ Refrig compressor "Popup_Refrig_Compr_Data" real data (added this session):
   confirmed real, direct photo of the real DCS popup (Ryan, uploaded screenshot).
   These are the REAL fields shown on the real popup for ALL THREE units side by
   side -- a genuinely different view than the single-selected-unit Quantum HD
   detail above (QHD only ever tracks one unit's full dynamic model at a time,
   a real architectural limit documented elsewhere in this file). Rather than
   leave C-1141/C-1142 with zero data whenever they aren't the QHD-selected unit,
   this gives every unit a real baseline (the exact values from the photo) that
   gently jitters -- honestly simplified vs. the selected unit's full dynamic
   model, and documented as such in the screen's own note text. */
var REFRIG_REAL_BASELINE={
 /* 2026-08-18 simultaneous HMI snapshot: only C-1140 RUNNING. 1141/1142 are stopped/equalizing. */
 c1140:{sucP:19.0,discP:207.9,oilP:192.2,oilFiltP:194.8,sucT:-3.2,discT:167.7,oilT:140.2,sepT:168.3,status:0},
 c1141:{sucP:19.5,discP:62.5,oilP:61.5,oilFiltP:60.1,sucT:84.4,discT:93.2,oilT:74.0,sepT:118.1,status:0},
 c1142:{sucP:18.7,discP:59.9,oilP:58.5,oilFiltP:57.8,sucT:75.2,discT:92.1,oilT:74.5,sepT:117.9,status:0}
};
var REFRIG_UNIT_DATA={
 c1140:Object.assign({},REFRIG_REAL_BASELINE.c1140),
 c1141:Object.assign({},REFRIG_REAL_BASELINE.c1141),
 c1142:Object.assign({},REFRIG_REAL_BASELINE.c1142)
};
/* 12EJ individual Frick package state.  Common suction/discharge remain shared system
   variables, but each running RWF-II package now owns its own load, power, oil temperature,
   filter DP, vibration and thermal lag. Exact unit performance maps are still pending
   package-specific OEM data, so these are normalized around the verified common model. */
var REFRIG_PACKAGE_STATE={
 c1140:{capBias:1.00,effBias:1.000,thermal:0,oilFiltDP:-2.6,vib:0.40,runHours:21584},
 c1141:{capBias:0.985,effBias:0.992,thermal:0,oilFiltDP:1.4,vib:0.41,runHours:18869},
 c1142:{capBias:1.015,effBias:1.006,thermal:0,oilFiltDP:0.7,vib:0.39,runHours:17867}
};
function refrigPackageModels(common){
 var runKeys=['c1140','c1141','c1142'].filter(function(k){return !!(QHD&&QHD.units&&QHD.units[k]);});
 var n=Math.max(1,runKeys.length), totalLoad=Math.max(0,Number(QHD&&QHD.pduty)||0);
 var out={}, capSum=0;
 runKeys.forEach(function(k){capSum+=REFRIG_PACKAGE_STATE[k].capBias;});
 ['c1140','c1141','c1142'].forEach(function(k){
  var st=REFRIG_PACKAGE_STATE[k], run=runKeys.indexOf(k)>=0;
  if(!run){st.thermal+=(0-st.thermal)*0.025;st.vib+=(0.34-st.vib)*0.04;out[k]={run:false,loadTons:0,loadPct:0,kw:0,amps:0,oilT:(PLANT.weather&&PLANT.weather.ambientTemp)||80,oilFiltDP:st.oilFiltDP,vib:st.vib};return;}
  var share=st.capBias/Math.max(0.1,capSum), loadTons=totalLoad*share;
  var baseDuty=Math.max(1,(common&&common.duty)||loadTons), loadPct=clmp((common&&common.capSlide||70)*(loadTons/(totalLoad/n||1)),15,100);
  var loadFrac=clmp(loadPct/100,0.15,1.10), cr=(common&&common.cr)||5;
  var kw=Math.max(80,((common&&common.kw)||780)*(loadTons/baseDuty)/Math.max(0.75,st.effBias));
  var amps=kw*1000/(1.732*4160*0.90*0.96);
  st.thermal+=(loadFrac-0.70)*0.012;st.thermal=clmp(st.thermal,-0.12,0.30);
  st.oilFiltDP=clmp(st.oilFiltDP+0.0000025*loadFrac,0.5,15);
  st.vib=clmp(0.34+0.07*loadFrac+0.015*Math.max(0,cr-5)+0.02*Math.abs(st.thermal),0.25,1.5);
  st.runHours+=1/3600;
  out[k]={run:true,loadTons:loadTons,loadPct:loadPct,kw:kw,amps:amps,oilT:clmp(((common&&common.oilT)||128)+st.thermal*35,70,210),oilFiltDP:st.oilFiltDP,vib:st.vib};
 });
 PLANT.v.refrigPackages=out;
 return out;
}

function refrigUnitTick(){
 /* 12BK plantwide correlation: all three Frick packages share the same suction,
    interstage/discharge network. A running non-selected package must not keep
    wandering around a stale photographed baseline while the common QHD plant
    conditions change. The selected unit remains the deepest model; other RUNNING
    units follow the same common headers with small package-specific offsets, while
    STOPPED units relax toward equalized/ambient-like values. */
 function jc(v,amt,lo,hi){var nv=v+(Math.random()-0.5)*amt; return Math.max(lo,Math.min(hi,nv));}
 var amb=(PLANT&&PLANT.weather&&isFinite(PLANT.weather.ambientTemp))?PLANT.weather.ambientTemp:90;
 ['c1140','c1141','c1142'].forEach(function(k,idx){
  var d=REFRIG_UNIT_DATA[k], base=REFRIG_REAL_BASELINE[k], isRun=!!(QHD&&QHD.units&&QHD.units[k]);
  if(isRun&&QHD){
   var off=(idx-1)*0.18, pkg=(PLANT.v.refrigPackages&&PLANT.v.refrigPackages[k])||{};
   var loadPct=clmp(pkg.loadPct==null?(QHD.capSlide||70):pkg.loadPct,15,100);
   d.loadPct=loadPct; d.vi=clmp((QHD.volSlide||2.5)+(loadPct-(QHD.capSlide||70))*0.006,2.2,5.0);
   d.sucP=jc(QHD.suctP+off,0.10,QHD.suctP-1,QHD.suctP+1);
   d.discP=jc(QHD.discP+off*2,0.35,QHD.discP-2,QHD.discP+2);
   d.oilP=jc(Math.max(0,QHD.oilP+off),0.25,0,700);
   d.oilFiltP=Math.max(0,d.oilP+(base.oilFiltP-base.oilP));
   d.sucT=jc(QHD.suctT+off*2,0.20,QHD.suctT-2,QHD.suctT+2);
   d.discT=jc(QHD.discT+off*2+(loadPct-(QHD.capSlide||70))*0.035,0.30,QHD.discT-4,QHD.discT+4);
   d.oilT=jc(pkg.oilT==null?QHD.oilT:pkg.oilT,0.20,60,215);
   d.sepT=jc(QHD.sep+off+(d.oilT-QHD.oilT)*0.12,0.30,QHD.sep-5,QHD.sep+8);
   d.kw=pkg.kw||0;d.amps=pkg.amps||0;d.vib=pkg.vib||0.4;
   d.status=(QHD.curKey===k?base.status:1);
  }else{
   var eqP=(QHD?Math.max(0,QHD.actual):19), _hpNow=(QHD?QHD.discP:207.9);
   var _sucEq=eqP+(base.sucP-19.0), _discEq=base.discP+0.18*(_hpNow-207.9);
   d.sucP+=(_sucEq-d.sucP)*0.08; d.discP+=(_discEq-d.discP)*0.06;
   var _eqOilP=d.discP+(base.oilP-base.discP), _eqFiltP=d.discP+(base.oilFiltP-base.discP);
   d.oilP+=(_eqOilP-d.oilP)*0.08; d.oilFiltP+=(_eqFiltP-d.oilFiltP)*0.08;
   var _ambShift=amb-75;
   d.sucT+=(base.sucT+_ambShift*0.45-d.sucT)*0.035; d.discT+=(base.discT+_ambShift*0.30-d.discT)*0.035; d.oilT+=(base.oilT+_ambShift*0.20-d.oilT)*0.03; d.sepT+=(base.sepT+_ambShift*0.15-d.sepT)*0.03;
   d.loadPct=0; d.vi=2.0; d.status=0;
  }
 });
}
/* ===== Propane R-290 saturation P(psia)-T(F) + screw-compressor refrigeration model ===== */
/* 12GA: NIST propane saturation function below replaces the old interpolated P/T table.
   Overlapping valid Antoine fits are blended only within their published ranges.
   Simulation assumptions: local atmospheric pressure 14.7 psia; gas approach 3.2 F. */
function prPsat(T){
 var K=Math.max(166.02,Math.min(360.8,(Number(T)-32)/1.8+273.15));
 function p(a,b,c){return Math.pow(10,a-b/(K+c))*14.5037738;}
 var low=p(4.01158,834.26,-22.763),mid=p(3.98292,819.296,-24.417),high=p(4.53678,1149.36,24.906);
 if(K<230.6)return low;
 if(K<231.41){var w=(K-230.6)/0.81;return low*(1-w)+mid*w;}
 if(K<310)return mid;
 if(K<320.7){var w2=(K-310)/10.7;return mid*(1-w2)+high*w2;}
 return high;
}
function prTsat(P){
 var lo=(166.02-273.15)*1.8+32,hi=(360.8-273.15)*1.8+32;
 P=Number(P);if(!isFinite(P))return NaN;
 if(P<=prPsat(lo))return lo;if(P>=prPsat(hi))return hi;
 for(var i=0;i<48;i++){var mid=(lo+hi)/2;if(prPsat(mid)<P)lo=mid;else hi=mid;}
 return (lo+hi)/2;
}
var RPamb=95,RPload=220,RPtotal=440,RPcondTD=25,ATM=14.7,SHt=3.5,APP=3.2,KEXP=0.115; /* 12EL: 19.0 psig propane suction corresponds to ~-6.5 F saturation; observed -3.2 F suction gives ~3.3 F superheat. */ /* 2026-08-13 Clear Fork live calibration: one running refrigeration compressor, PIC-1441C SP 17 psig, actual suction ~18 psig. Old 1040-ton assumption forced false ~45.6 psig suction. */
function _etav(CR){return Math.max(0.62,Math.min(0.95,1-0.045*(CR-1)));}
function _qfac(Tc,Te){return Math.max(0.72,1-0.0035*((Tc-Te)-100));}
function _qfull(Pa,Pc,Tc){var Te=prTsat(Pa),Ts=Te+SHt,CR=Pc/Pa;return (Pa/(Ts+460))*_etav(CR)*_qfac(Tc,Te);}
function _work(Pa,Pc){var Te=prTsat(Pa),Ts=Te+SHt,CR=Pc/Pa;return (Pa/(Ts+460))*_etav(CR)*(Ts+460)*(Math.pow(CR,KEXP)-1);}
var _Tc0=RPamb+25,_Pc0=prPsat(_Tc0),_Pa0=30+ATM,_QF0=_qfull(_Pa0,_Pc0,_Tc0),_W0=_work(_Pa0,_Pc0),CQ=800/_QF0,CB=1244/_W0; /* Clear Fork calibration: one Frick unit can normally hold ~17-18 PSIG suction without falsely pegging capacity. */
function cfRefrigPoint12GA(psig,discPsig,slide,loadTons,econ){
 var Pa=Math.max(1,Number(psig)+ATM),Pc=Math.max(Pa+0.01,Number(discPsig)+ATM);
 var Te=prTsat(Pa),Tc=prTsat(Pc),cr=Pc/Pa;
 var reference=_qfull(17+ATM,208+ATM,prTsat(208+ATM));
 var full=620*_qfull(Pa,Pc,Tc)/reference; // assumed available full-slide tons per unit
 full=Math.max(15,Math.min(1900,full));
 slide=Math.max(0,Math.min(100,slide));
 var delivered=full*slide/100;
 var baseCop=0.52*((Te-32)/1.8+273.15)/Math.max(12,(Tc-Te)/1.8);
 var partLoad=0.70+0.30*slide/100; // empirical screw part-load penalty
 var cop=Math.max(0.5,Math.min(8,baseCop*partLoad));
 var kw=delivered*3.51685284/cop*(1+0.20*Math.max(0,econ||0));
 var discT=Te+SHt+((Te+SHt+459.67)*(Math.pow(cr,KEXP)-1))/0.72+16;
 return {fullTons:full,availableTons:delivered,actual:psig,suctP:psig,discP:Pc-ATM,
  suctT:Te+SHt,suctSH:SHt,discT:discT,discSH:discT-Tc,oilP:Math.max(0,discPsig-15.7),
  oilT:0.45*discT+64.7,sep:discT+0.6,capSlide:slide,volSlide:Math.max(2,Math.min(5,0.38+0.46*cr)),
  tevap:Te,chill:Te+APP,tcond:Tc,cr:cr,kw:kw,amps:kw*1000/(1.732*4160*0.90*0.96),
  fla:kw*1000/(1.732*4160*0.90*0.96)/177*100,
  duty:Math.min(Math.max(0,loadTons),delivered),cop:kw>0?delivered*3.51685284/kw:0,
  kwton:delivered>0?kw/delivered:0,condDuty:delivered+kw/3.51685284};
}
function cfRefrigStep12GA(duty,ambient,dt){
 var V=PLANT.v,L=PLANT.L,ctl=L.PIC1441C;
 dt=Math.max(0,Math.min(5,Number(dt)||1));
 var n=Object.keys(QHD.units).filter(function(k){return QHD.units[k];}).length;
 QHD.Nrun=n;QHD.systemRun=n>0;QHD.run=!!QHD.units[QHD.curKey];
 var p=isFinite(V.refrigSuction12GA)?V.refrigSuction12GA:(isFinite(QHD.actual)?QHD.actual:17);
 var hp=isFinite(QHD.discP)?QHD.discP:208;
 var econ=Number(V.refrigInterstageLoadFrac)||0;
 var full=cfRefrigPoint12GA(p,hp,100,duty/Math.max(1,n),econ).fullTons;
 // PCV-1441A remains a separate suction-network valve, not a second copy of SP.
 var lineAvail=L.PIC1441?clmp(L.PIC1441.out/100,0,1):1;
 var available=full*n*lineAvail;
 var balanced=available>0?100*duty/available:100;
 var error=p-QHD.capSP;
 var demand=ctl.man?clmp(ctl.out,0,100):clmp(balanced+5*error,15,100);
 if(!ctl.man)ctl.out=n?demand:0;
 var slide=isFinite(QHD.capSlide)?QHD.capSlide:75;
 if(n){slide+=clmp((demand-slide)*(1-Math.exp(-dt/6)),-0.8*dt,0.8*dt);}
 else slide=0;
 slide=clmp(slide,0,100);
 var removed=available*slide/100;
 var imbalance=duty-removed;
 // Vapor-holdup pressure balance: loads/lost machinery can exceed SP. Not a PV clamp.
 if(n)p+=clmp(imbalance/440*0.45,-0.65,0.65)*dt;
 else p+=(Math.max(17,Math.min(hp,prPsat(ambient)-ATM))-p)*(1-Math.exp(-dt/240));
 p=clmp(p,-10,Math.max(18,hp-1));
 var lowSupport=L.PCV1441B?clmp(L.PCV1441B.out/100,0,1):0;
 // Existing low-pressure support has bounded effect; it is not an infinite pressure source.
 if(n&&p<(L.PCV1441B?L.PCV1441B.sp:12)&&lowSupport>0)p+=lowSupport*0.008*dt;
 V.refrigSuction12GA=p;QHD.actual=QHD.suctP=p;QHD.capSlide=slide;
 ctl.sp=QHD.capSP;ctl.pv=p;if(L.PIC1441)L.PIC1441.pv=p;
 var point=cfRefrigPoint12GA(p,hp,slide,duty/Math.max(1,n),econ);
 if(!n){point.kw=point.amps=point.fla=point.duty=point.condDuty=point.cop=point.kwton=0;point.discT=ambient;point.oilT=ambient;point.sep=ambient;}
 ['suctT','suctSH','tevap','chill','tcond','cr','volSlide','kw','amps','fla','cop','kwton'].forEach(function(k){QHD[k]=point[k];});
 ['discT','discSH','oilT','sep','oilP'].forEach(function(k){QHD[k]+=(point[k]-QHD[k])*(1-Math.exp(-dt/25));});
 QHD.duty=n?Math.min(duty/n,point.availableTons*lineAvail):0;
 QHD.pduty=QHD.duty*n;QHD.totalKw=QHD.kw*n;
 QHD.totalCondDuty=QHD.pduty+QHD.totalKw/3.51685284;
 QHD.condDuty=n?QHD.totalCondDuty/n:0;
 QHD.pegged=n>0&&slide>99&&p>QHD.capSP+0.5;
 V.refrigCapacityLimited=QHD.pegged;V.refrigTurndownLimited=n>0&&slide<15.1&&p<QHD.capSP-0.5;
 V.refrigCapacityTons12GA=available;V.refrigPressureError12GA=p-QHD.capSP;
 V.refrigVaporImbalanceTons12GA=imbalance;
 V.refrigSuctionAuthority12GA=!n?'NO RUNNING COMPRESSOR':(ctl.man?'MANUAL SLIDE':(QHD.pegged?'AUTO - CAPACITY LIMITED':(V.refrigTurndownLimited?'AUTO - MINIMUM SLIDE LIMITED':'AUTO - SUCTION PRESSURE')));
 return point;
}
function cfRefrigSync12GA(){
 var L=PLANT.L,p=QHD.actual;
 if(L.PIC1441C){L.PIC1441C.sp=QHD.capSP;L.PIC1441C.pv=p;}
 if(L.PIC1441){L.PIC1441.pv=p;if(!L.PIC1441.man)L.PIC1441.out=clmp(100-(p-L.PIC1441.sp)*14,0,100);}
 PLANT.v.refrigSuctionPressure=p;
}
function cfRefrigEffectsPanel12GA(){
 var V=PLANT.v,L=PLANT.L;
 return '<div class="sect">Refrigeration suction - cause and effect | 12GA</div><div class="erow">'+
 '<div class="eb"><span>PIC-1441C SP / PV (PSIG)</span><b>'+QHD.capSP.toFixed(2)+' / '+QHD.actual.toFixed(2)+'</b></div>'+
 '<div class="eb"><span>R-290 saturation / gas outlet (F)</span><b>'+QHD.tevap.toFixed(1)+' / '+Number(V.te1241c||0).toFixed(1)+'</b></div>'+
 '<div class="eb"><span>Slide / total power estimate</span><b>'+QHD.capSlide.toFixed(1)+'% / '+Number(QHD.totalKw||0).toFixed(0)+' kW</b></div>'+
 '<div class="eb"><span>Simulated C3 recovery / NGL C2</span><b>'+Number(V.c3MaterialRecoveryPct||0).toFixed(2)+'% / '+Number(V.c2ngl||0).toFixed(2)+'%</b></div></div>'+
 '<div class="note"><b>'+ryanEscape(V.refrigSuctionAuthority12GA||'Initializing')+'</b>. Lower suction SP in AUTO loads the slide, then lowers propane boiling temperature when capacity permits. Higher SP unloads and warms it. In MAN, output controls the slide; changing SP alone does not control pressure. Cooler feed tends to retain more C3+ and can increase ethane stripping/reboil duty in FULL REJECTION. Watch TIC-1225 output and the delayed GC; the operating mode and tower-pressure SP do not change automatically. More cold is not automatically better. Head pressure, wetting, moisture, capacity and heat availability still constrain performance.</div>'+
 '<div class="note">Source physics: NIST propane data; FRICK Quantum capacity-control manual; Campbell refrigeration study; UOP rejection overview. Model gains, 3.2 F approach, capacity and energy estimates are empirical training assumptions, not guaranteed plant performance. See Reference Library: Refrigeration Suction - Full Rejection (12GA).</div>';
}
function cfRsvFilterPanel12GA(){
 var r=filterRec('f1438'),dp=filterDP('f1438'),due=dp>=10;
 return '<section id="rsvFilterService12GA" class="popf" style="margin-top:12px;border:2px solid '+(due?'#bc7b15':'#688998')+';border-radius:6px">'+
 '<div class="sect">F-1438 RSV filter - Change Filter</div><div class="erow">'+
 '<div class="eb"><span>PDT-1438</span><b>'+dp.toFixed(2)+' PSID</b></div>'+
 '<div class="eb"><span>Change threshold / existing path trip</span><b>10.00 / 15.00 PSID</b></div>'+
 '<button data-act="filterchanged" data-f="f1438" style="padding:10px 18px;height:auto">Change Filter</button></div>'+
 '<div class="note"><b>'+(dp>=15?'RSV PATH TRIP THRESHOLD':(due?'FILTER CHANGE DUE':'Below change threshold'))+'</b>. Records a simulated element replacement after confirmation. The 10 PSID point is a maintenance threshold, not an automatic facility shutdown.</div>'+
 '<div class="note">This is not a valve lineup or authorization to open a pressurized housing. Use approved isolation/LOTO, depressurization and zero-energy verification for actual work; shared RSV/seal-gas consumers must be evaluated. No isolation or restart is performed by this button.</div>'+
 '<div class="note">'+ryanEscape(PLANT.v.rsvServiceStorageWarning||'')+'</div>'+'<div class="note">Replacements recorded: '+Number(r&&r.changeCount||0)+(r&&r.changedAtIso?' | Last: '+ryanEscape(r.changedAtIso):'')+'. A confirmed change resets only this modeled element DP; a tripped XV-1438B remains closed.</div></section>';
}
function cfRsvServicePersist12GA(){
 try{localStorage.setItem('clearForkRsvFilterService12GA',JSON.stringify(filterRec('f1438')));PLANT.v.rsvServiceStorageWarning='';return true;}
 catch(e){PLANT.v.rsvServiceStorageWarning='Service record is session-only: browser storage write failed.';return false;}
}
function cfRsvServiceRestore12GA(){
 try{var saved=JSON.parse(localStorage.getItem('clearForkRsvFilterService12GA')||'null'),r=filterRec('f1438');if(!saved||!r)return;
  if(typeof saved.dp==='number'&&isFinite(saved.dp)&&saved.dp>=0&&saved.dp<=16&&Number(saved.changeCount)>=1){
   r.dp=saved.dp;r.changedAt=Number(saved.changedAt)||0;r.changeCount=Math.max(0,Math.min(100000,Number(saved.changeCount)||0));r.changedAtIso=String(saved.changedAtIso||'').slice(0,80);PLANT.v.pdt1438=r.dp;
  }
 }catch(e){PLANT.v.rsvServiceStorageWarning='Stored service record could not be read; existing saved data was not deleted.';}
}
function cfChangeRsvFilter12GA(){
 var r=filterRec('f1438');if(!r)return false;
 if(!window.confirm('SIMULATION ONLY - F-1438 element replacement\n\nConfirm the simulated maintenance has been completed under the applicable isolation/LOTO and zero-energy verification requirements. This does not provide a field valve lineup or operate isolation valves.\n\nRecord replacement and reset only F-1438 differential pressure? XV-1438B will NOT be reopened.'))return false;
 r.dp=0.18;r.changedAt=PLANT.simSeconds||0;r.changedAtIso=new Date().toISOString();r.changeCount=Number(r.changeCount||0)+1;
 cfRsvServicePersist12GA();
 PLANT.v.pdt1438=r.dp;filterClearAlarmLatch('f1438','change',true);filterClearAlarmLatch('f1438','trip',true);
 alarm('F-1438 FILTER CHANGED (simulation record) - modeled clean DP 0.18 PSID; valve positions unchanged.');return true;
}
function qmodel(SP,run,Nrun){
 /* Compatibility steady-state preview. Master physics uses cfRefrigStep12GA,
    never writes PV from SP and never guarantees an unattainable setpoint. */
 var n=Math.max(1,Nrun||1),dp=prPsat(RPamb+RPcondTD)-ATM;
 if(!run){var z=cfRefrigPoint12GA(SP,dp,0,0,0);z.kw=z.amps=z.fla=z.duty=z.condDuty=z.cop=z.kwton=0;return z;}
 var p=SP;
 for(var i=0;i<120;i++){var cap=cfRefrigPoint12GA(p,dp,100,RPtotal/n,0).fullTons;if(cap*n>=RPtotal||p>=65)break;p+=0.5;}
 var slide=Math.max(15,Math.min(100,100*RPtotal/n/cap));
 var m=cfRefrigPoint12GA(p,dp,slide,RPtotal/n,0);m.pegged=p>SP+0.5;return m;
}
function qS(id,v){var e=document.getElementById(id); if(e)e.textContent=v;}
function qhdRender(){qS('qSuctP',QHD.suctP.toFixed(1)+' PSIG');qS('qSuctT',QHD.suctT.toFixed(1)+' \u00B0F');qS('qSuctSH',QHD.suctSH.toFixed(1)+' \u00B0F');qS('qDiscP',QHD.discP.toFixed(1)+' PSIG');qS('qDiscT',QHD.discT.toFixed(1)+' \u00B0F');qS('qDiscSH',QHD.discSH.toFixed(1)+' \u00B0F');qS('qOilP',QHD.oilP.toFixed(1)+' PSIG');qS('qOilT',QHD.oilT.toFixed(1)+' \u00B0F');qS('qSep',QHD.sep.toFixed(1)+' \u00B0F');qS('qFilt',QHD.filt.toFixed(1)+' PSI');qS('qAmps',Math.round(QHD.amps)+' A');qS('qFla',QHD.fla.toFixed(1)+' %');qS('qKw',Math.round(QHD.kw)+' kW');qS('qRun',Math.round(QHD.runhrs)+' HRS');qS('qVibDE',QHD.vibDE.toFixed(3)+' gF');qS('qVibODE',QHD.vibODE.toFixed(3)+' gF');qS('qSP',QHD.capSP.toFixed(0));qS('qSP2',QHD.capSP.toFixed(0));qS('qActual',QHD.actual.toFixed(1));qS('qActual2',QHD.actual.toFixed(1));qS('qCapSlide',QHD.capSlide.toFixed(1));qS('qVolSlide',QHD.volSlide.toFixed(2));qS('qTevap',QHD.tevap.toFixed(1)+' \u00B0F');qS('qChill',QHD.chill.toFixed(1)+' \u00B0F');qS('qTcond',QHD.tcond.toFixed(1)+' \u00B0F');qS('qCR',QHD.cr.toFixed(2)+' : 1');qS('qDuty',Math.round(QHD.duty)+' tons');qS('qKwTon',QHD.kwton.toFixed(2)+' kW/ton');qS('qCOP',QHD.cop.toFixed(2));qS('qCompState',QHD.run?'Running':'Off');qS('qOilPump',QHD.run?'On':'Off');qS('qReady',QHD.run?'Running':'Ready');qS('qNrun',QHD.Nrun+' of 3');qS('qPduty',Math.round(QHD.pduty)+' tons');['c1140','c1141','c1142'].forEach(function(u){var el=document.getElementById('u_'+u);if(el){el.classList.toggle('on',!!QHD.units[u]);el.textContent=u.toUpperCase().replace('C','C-')+(QHD.units[u]?' \u25CF':' \u25CB');}});['a1343a','a1343b','a1343c'].forEach(function(fk){var el=document.getElementById('f_'+fk);if(el){el.classList.toggle('on',!!QHD.fans[fk]);el.textContent='Fan '+fk.slice(-1).toUpperCase()+(QHD.fans[fk]?' \u25CF':' \u25CB');}});qS('qFans',((QHD.fans.a1343a?1:0)+(QHD.fans.a1343b?1:0)+(QHD.fans.a1343c?1:0))+' of 3');var pe=document.getElementById('qPeg');if(pe)pe.style.display=(QHD.pegged&&QHD.actual>QHD.capSP+2)?'block':'none';var sl=document.getElementById('qSlider');if(sl&&document.activeElement!==sl)sl.value=QHD.capSP.toFixed(0);
 var selected=!!QHD.units[QHD.curKey],d=REFRIG_UNIT_DATA[QHD.curKey]||{},pkg=(PLANT.v.refrigPackages||{})[QHD.curKey]||{};
 qS('qCompState',selected?'Running':'Stopped');qS('qReady',selected?'Running':'Stopped');qS('qOilPump',selected?'On':'Off');
 qS('qMode',PLANT.L.PIC1441C.man?'MANUAL SLIDE':'AUTO SUCTION');
 if(!selected){qS('qAmps','0 A');qS('qFla','0 %');qS('qKw','0 kW');qS('qCapSlide','0.0');qS('qDuty','0 tons');qS('qCOP','0.00');qS('qKwTon','0.00');}
 if(isFinite(d.sucT))qS('qSuctT',d.sucT.toFixed(1)+' F');
 if(!selected&&isFinite(d.discP))qS('qDiscP',d.discP.toFixed(1)+' PSIG');
 if(!selected&&isFinite(d.discT))qS('qDiscT',d.discT.toFixed(1)+' F');
 if(!selected&&isFinite(d.oilT))qS('qOilT',d.oilT.toFixed(1)+' F');
 var bt=document.getElementById('qStart');if(bt)bt.textContent=selected?'Stop this unit':'Start this unit';
 qS('qChill',Number(PLANT.v.te1241c==null?QHD.chill:PLANT.v.te1241c).toFixed(1)+' F');
}
function qRnd(a){return (Math.random()*2-1)*a;}
/* 12DE PLANTWIDE DYNAMIC CAUSE/EFFECT AUDIT.
   Deterministic process dynamics used by the physics engine.  Unlike display-side
   transmitter breathing, these functions change the simulated PROCESS state and are
   therefore used only where a physical inventory/pressure/thermal response exists. */
function cfProcPhase(key){key=String(key||'');var h=2166136261>>>0;for(var i=0;i<key.length;i++){h^=key.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}return (h%6283)/1000;}
function cfProcWave(key,amp,period){var t=(PLANT&&isFinite(PLANT.simSeconds))?PLANT.simSeconds:0;return Number(amp||0)*(0.72*Math.sin(t/Math.max(2,period||30)+cfProcPhase(key))+0.28*Math.sin(t/Math.max(3,(period||30)*2.7)+cfProcPhase(key)*0.61));}
function cfLag(obj,key,target,tau,lo,hi){if(!obj||!isFinite(target))return target;var cur=obj[key];if(!isFinite(cur))cur=target;var dt=1;var a=1-Math.exp(-dt/Math.max(0.25,tau||1));cur+= (target-cur)*a;if(isFinite(lo))cur=Math.max(lo,cur);if(isFinite(hi))cur=Math.min(hi,cur);obj[key]=cur;return cur;}
function cfLagLoop(loop,target,tau,lo,hi){if(!loop||!isFinite(target))return target;var cur=isFinite(loop.pv)?loop.pv:target;var a=1-Math.exp(-1/Math.max(0.25,tau||1));cur+=(target-cur)*a;if(isFinite(lo))cur=Math.max(lo,cur);if(isFinite(hi))cur=Math.min(hi,cur);loop.pv=cur;return cur;}

function qhdTick(){
 var V=PLANT.v,L=PLANT.L;
 RPamb=PLANT.weather&&isFinite(PLANT.weather.ambientTemp)?clmp(PLANT.weather.ambientTemp,-20,125):75;
 var flow=isFinite(V.flowCryoPropagated)?V.flowCryoPropagated:PLANT.in.flow;
 var tin=isFinite(V.e1241FeedT)?V.e1241FeedT:2, tout=isFinite(V.e1241OutT)?V.e1241OutT:-7.6;
 var cond=isFinite(V.coldCondFrac)?V.coldCondFrac:0.55;
 var target=440*clmp(flow/223.37,0,1.4)*clmp(0.40+0.025*Math.max(0,tin-tout)+0.375*(cond/0.55),0.40,1.65);
 // No invented evaporation duty when process gas is colder than the refrigerant.
 // 3-ton parasitic heat leak is an explicit training assumption, not measured data.
 var driving=clmp((tin-prTsat(QHD.actual+ATM))/Math.max(0.5,APP),0,1);
 target=target*driving+3;
 RPtotal+=(clmp(target,0,850)-RPtotal)*(1-Math.exp(-1/25));QHD.processDutyTarget=RPtotal;
 var fans=(QHD.fans.a1343a?1:0)+(QHD.fans.a1343b?1:0)+(QHD.fans.a1343c?1:0);
 var heat=Math.max(0,QHD.totalCondDuty||650);
 RPcondTD=clmp(14+13*Math.pow(clmp(heat/650,0.20,2.1)/Math.max(0.08,fans/3),0.72),15,100);
 var headTarget=prPsat(clmp(RPamb+RPcondTD,-10,188))-ATM;
 // Existing high-pressure control/backpressure demand can raise head, not lower ambient limit.
 if(L.PIC1140D)headTarget=Math.max(headTarget,L.PIC1140D.sp);
 QHD.discP+=(headTarget-QHD.discP)*(1-Math.exp(-1/45));
 cfRefrigStep12GA(RPtotal,RPamb,1);cfRefrigSync12GA();
 QHD.filt=Math.max(0,1+qRnd(0.03));
 if(QHD.systemRun){QHD.runhrs+=1/3600;QHD.vibDE=0.40+qRnd(0.02);QHD.vibODE=0.35+qRnd(0.02);}
 else{QHD.vibDE=QHD.vibODE=0;}
 refrigPackageModels(QHD);
 if(document.getElementById('qhd')&&document.getElementById('qhd').style.display!=='none')qhdRender();
}
function toggleRefrigUnit(u){
 if(!QHD||!QHD.units||!(u in QHD.units))return false;
 var isOn=!!QHD.units[u],running=Object.keys(QHD.units).filter(function(k){return QHD.units[k];}).length;
 if(!isOn&&PLANT.esd){alarm('Cannot start refrigeration compressor - facility ESD active');return false;}
 if(!isOn&&PLANT.v&&PLANT.v.refrigESD){alarm('Cannot start '+u.toUpperCase()+' — REFRIGERATION ESD LATCHED; lower V-1444 below 75% and RESET');return false;}
 if(!isOn&&PLANT.redtag&&PLANT.redtag[u]){alarm('Cannot start '+u.toUpperCase()+' - RED TAGGED');return false;}
 if(!isOn&&running>=2&&!PLANT.in.allCompressorsScenario12FZ){alarm('Start inhibited - refrigeration normally uses one compressor and a maximum of two may run; three-compressor operation is not permitted');return false;}
 QHD.units[u]=!isOn;QHD.Nrun=Object.keys(QHD.units).filter(function(k){return QHD.units[k];}).length;QHD.systemRun=QHD.Nrun>0;QHD.run=!!QHD.units[QHD.curKey];return true; /* 12CH: command changes state immediately but does not advance refrigeration thermodynamics outside the master plant tick. */
}
function qhdClock(){var e=document.getElementById('qhdclock');if(!e)return;var d=new Date();function p(n){return (n<10?'0':'')+n;}e.textContent=p(d.getMonth()+1)+'/'+p(d.getDate())+'/'+d.getFullYear()+' - '+p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());}
function openQHD(ck){var map={c1140:'C-1140',c1141:'C-1141',c1142:'C-1142'};QHD.curKey=(ck&&map[ck])?ck:'c1140';QHD.tag=map[QHD.curKey];qS('qhdtag',QHD.tag);document.getElementById('qhd').style.display='block';var sb=document.getElementById('qStart');if(sb){sb.textContent=QHD.units[QHD.curKey]?'Stop this unit':'Start this unit';sb.classList.toggle('on',QHD.units[QHD.curKey]);}qhdRender();qhdClock();if(QHD.timer)clearInterval(QHD.timer);QHD.timer=setInterval(function(){qhdClock();qhdRender();},1000);}
function closeQHD(){document.getElementById('qhd').style.display='none';if(QHD.timer){clearInterval(QHD.timer);QHD.timer=null;}}
document.getElementById('qhdbtn').addEventListener('click',function(){openQHD('c1140');});
document.getElementById('qClose').addEventListener('click',closeQHD);
document.getElementById('qStart').addEventListener('click',function(){toggleRefrigUnit(QHD.curKey);this.textContent=QHD.units[QHD.curKey]?'Stop this unit':'Start this unit';this.classList.toggle('on',QHD.units[QHD.curKey]);qhdRender();});
['c1140','c1141','c1142'].forEach(function(u){var el=document.getElementById('u_'+u);if(el)el.addEventListener('click',function(){toggleRefrigUnit(u);if(u===QHD.curKey){var sb=document.getElementById('qStart');sb.textContent=QHD.units[u]?'Stop this unit':'Start this unit';sb.classList.toggle('on',QHD.units[u]);}qhdRender();});});
['a1343a','a1343b','a1343c'].forEach(function(fk){var el=document.getElementById('f_'+fk);if(el)el.addEventListener('click',function(){QHD.fans[fk]=!QHD.fans[fk];qhdRender();});});
function qSetSP(v){v=Number(v);if(!isFinite(v))return;QHD.capSP=Math.max(8,Math.min(28,v));if(PLANT&&PLANT.L&&PLANT.L.PIC1441C)PLANT.L.PIC1441C.sp=QHD.capSP;qhdRender();}
document.getElementById('qUp').addEventListener('click',function(){qSetSP(QHD.capSP+1);});
document.getElementById('qDn').addEventListener('click',function(){qSetSP(QHD.capSP-1);});
document.getElementById('qSlider').addEventListener('input',function(){qSetSP(parseFloat(this.value));});
document.getElementById('qhd').addEventListener('click',function(e){if(e.target===this)closeQHD();});
