var CTRL={open:false,timer:null,L:{},meta:[
 ['LIC1421','LIC-1421','Cold-sep V-1421 level',2],
 ['PIC1521DJT','PIC-1521D JT','Tower pressure - JT valve',1],
 ['PIC1521DEX','PIC-1521D EX','Tower pressure - expander IGV',1],
 ['TIC1225','TIC-1521','Column bottom temp (reboiler)',1],
 ['FIC1422','FIC-1422','NGL recycle (FCV-1422)',10],
 ['PIC1441','PIC-1441A','Refrig suction pressure',2],
 ['PCV1444','PIC-1444','Refrig HP accumulator pressure',5],
 ['TIC1241C','TIC-1241C','Gas chiller (E-1241) outlet temp',1],
 ['FIC7100A','FIC-7100A','Hot oil circulation flow',20],
 ['PIC5700A','PIC-5700A','Overhead source header to C-5700 suction',5]
]};
function ctBuild(){var b=document.getElementById('ctbody');if(!b)return;var html='';
  CTRL.meta.forEach(function(m){var id=m[0];CTRL.L[id]=PLANT.L[id];var L=CTRL.L[id];
  html+='<tr><td><b>'+m[1]+'</b></td><td>'+m[2]+'</td>'+
  '<td><b id="pv_'+id+'"></b></td>'+
  '<td><button class="spb" data-sp="'+id+'" data-d="-1">&minus;</button> <span id="sp_'+id+'"></span> <button class="spb" data-sp="'+id+'" data-d="1">+</button></td>'+
  '<td><span class="obar"><i id="ob_'+id+'"></i></span><span id="ov_'+id+'"></span></td>'+
  '<td><button class="modebtn auto" id="md_'+id+'" data-md="'+id+'">AUTO</button></td></tr>';});
  b.innerHTML=html;
  b.querySelectorAll('[data-sp]').forEach(function(btn){btn.addEventListener('click',function(){var id=this.getAttribute('data-sp'),d=parseFloat(this.getAttribute('data-d')),L=CTRL.L[id],step=CTRL.meta.filter(function(m){return m[0]===id;})[0][3];if(id==='PIC1521DEX'||id==='PIC1521DJT'){expDispatch(L.man?(id==='PIC1521DEX'?'boardDemand':'jtCV'):(id==='PIC1521DEX'?'exSP':'jtSP'),(L.man?L.out:L.sp)+d*step,'CONTROLS TABLE');}else if(L.man){L.out=Math.max(0,Math.min(100,L.out+d*5));}else{L.sp+=d*step;}ctRender();});});
  b.querySelectorAll('[data-md]').forEach(function(btn){btn.addEventListener('click',function(){var id=this.getAttribute('data-md'),L=CTRL.L[id];if(id==='PIC1521DEX'||id==='PIC1521DJT')expDispatch(id==='PIC1521DEX'?'mode':'jtMode',null,'CONTROLS TABLE');else L.man=!L.man;ctRender();});});
}
function ctRender(){CTRL.meta.forEach(function(m){var id=m[0];var L=CTRL.L[id];if(!L)return;var uu=(L.u||'').toUpperCase();
  qS('pv_'+id,L.pv.toFixed(uu==='PSIG'||uu==='GPM'?0:1)+' '+L.u);qS('sp_'+id,L.sp.toFixed(0)+(L.man?'':' '+L.u));var ob=document.getElementById('ob_'+id);if(ob)ob.style.width=L.out.toFixed(0)+'%';qS('ov_'+id,L.out.toFixed(0)+'%');var md=document.getElementById('md_'+id);if(md){md.textContent=L.man?'MAN':'AUTO';md.className='modebtn '+(L.man?'man':'auto');}});
  var chill=(typeof QHD!=='undefined')?QHD.chill:13, suct=(typeof QHD!=='undefined')?QHD.actual:30;
  var V=PLANT.v;
  /* Defensive guard added this session: this whole indicator block previously
     referenced CTRL.L.PIC1521/TIC1225/FIC1422 etc. directly with no null-check.
     All nine keys were verified present in PLANT.L, so this hasn't been observed
     to actually throw -- but if a future edit ever renames/removes one of these
     controllers, this used to mean a silent, uncaught exception here would aborp
     the rest of ctRender() (everything below this point, including this whole
     indicator table) with no visible error. Wrapping it means a future breakage
     degrades to a missing row instead of a fully dead-looking popup. */
  try{
  var ind=[['PT-1521','Demethanizer pressure',PLANT.L.PIC1521.pv.toFixed(0)+' psig'],
   ['TI-1521A','Column overhead temp',(-130+PLANT.L.PIC1521.pv*0.06).toFixed(0)+' \u00B0F'],
   ['TI-1521B','Column bottom temp',CTRL.L.TIC1225.pv.toFixed(0)+' \u00B0F'],
   ['AI-1521','C2 in NGL (bottoms)',(V.c2ngl!=null?V.c2ngl:Math.max(0.2,(8-(CTRL.L.TIC1225.pv-50)*0.16))).toFixed(1)+' mol%'],
   ['TI-1241','Chiller gas outlet (E-1241)',chill.toFixed(1)+' \u00B0F  \u2190 refrig'],
   ['TI-1201','Demethanizer feed temp',(chill-10).toFixed(1)+' \u00B0F'],
   ['PT-1141','Propane suction header',suct.toFixed(1)+' psig  \u2190 Quantum HD'],
   ['FT-1422','NGL recycle flow',CTRL.L.FIC1422.pv.toFixed(0)+' GPM'],
   ['TI-101','Expander outlet \u2192 T-1521',(typeof EXP!=='undefined'?EXP.expOutT:-107).toFixed(0)+' \u00B0F  \u2190 ACMTC 1039'],
   ['PT-4250A','Inlet compressor discharge header',(V.inlHdr!=null?V.inlHdr:860).toFixed(0)+' psig  \u2190 C-4100/4200 load'],
   ['PT-6050C','Residue compressor discharge header',(V.resHdr!=null?V.resHdr:920).toFixed(0)+' psig  \u2190 C-6100/6200/6300 load'],
   ['FT-8210A','Residue gas sales rate',(V.resRate!=null?V.resRate:0).toFixed(0)+' MMSCFD'],
   ['FT-8000A','NGL product rate',(V.nglRate!=null?V.nglRate:0).toFixed(1)+' MMSCFD'],
   ['XI-5700','C-5700 overhead compressor',(PLANT.cmp.c57&&PLANT.cmp.c57.run)?'RUNNING':'STOPPED'],
   ['TI-202','Hot oil heater (H-7100) outlet',(PLANT.in.heaterSP-7).toFixed(0)+' \u00B0F  \u2190 Remote Heater SP']];
  var ib=document.getElementById('itbody');if(ib){var h2='';ind.forEach(function(r){h2+='<tr><td style="color:#8fa0b2;width:78px;">'+r[0]+'</td><td>'+r[1]+'</td><td class="v" style="text-align:right;color:#eef2f7;"><b>'+r[2]+'</b></td></tr>';});ib.innerHTML=h2;}
  }catch(_indErr){var ib2=document.getElementById('itbody');if(ib2)ib2.innerHTML='<tr><td colspan="3" style="color:#ffb0b0;">Indicator table error: '+(_indErr&&_indErr.message?_indErr.message:_indErr)+'</td></tr>';}
}
function ctTick(){ctRender();var e=document.getElementById('ctrlclock');if(e){var d=new Date();function p(n){return(n<10?'0':'')+n;}e.textContent=p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());}} /* 12BK correlation fix: the always-on plantRuntime timer is the ONLY owner of PLANT.tick(). This popup timer renders only. Previously opening the Control Center added a second physics tick every second, so the exact same plant state evolved faster merely because a popup was open. */
