 var flowNow=(typeof PLANT!=='undefined'&&PLANT.v&&PLANT.v.expanderInletFlow!=null)?PLANT.v.expanderInletFlow:((typeof PLANT!=='undefined'&&PLANT.in)?(PLANT.in.flow||222)*0.82:182);
