 aS('aExpVibX',EXP.expVibX.toFixed(2)+' MILS');aS('aExpVibY',EXP.expVibY.toFixed(2)+' MILS');aS('aThrust',EXP.thrust.toFixed(0)+' PSIG');
 aS('aLubeDP',EXP.lubeDP.toFixed(0)+' PSID');aS('aExpBrg',EXP.expBrgT.toFixed(0)+' \u00B0F');
 aS('aCompSuc',EXP.compSuc.toFixed(0)+' PSIG');aS('aCompDis',EXP.compDis.toFixed(0)+' PSIG');aS('aAcfm',Math.round(EXP.acfm)+' ACFM');
 aS('aPdi',EXP.pdi.toFixed(0)+' "H2O');aS('aCompVibX',EXP.compVibX.toFixed(2)+' MILS');aS('aCompVibY',EXP.compVibY.toFixed(2)+' MILS');
 aS('aSealDP',EXP.sealDP.toFixed(0)+' PSID');aS('aCompBrg',EXP.compBrgT.toFixed(0)+' \u00B0F');
 var st=document.getElementById('aStatus');if(st){st.textContent=EXP.run?'RUNNING':'STOPPED';st.className=EXP.run?'arun':'astop';}
 var state=expControlState(),pc=state.ex;
 var sl=document.getElementById('aSlider');if(sl){sl.disabled=state.remote||!EXP.run;if(document.activeElement!==sl)sl.value=EXP.localDemand.toFixed(0);}
 ['aDn','aUp'].forEach(function(id){var el=document.getElementById(id);if(el)el.disabled=state.remote||!EXP.run;});
