document.getElementById('acmtcbtn').addEventListener('click',openACMTC);
/* =================== EQT CONTROL BOARD (reactive plant model) =================== */
function clmp(x,a,b){return Math.max(a,Math.min(b,x));}
var PLANT=cfPayload12PJ.create("p57");
cfRestoreResidueStepRange12PT(PLANT.cmp);
/* Operator-supplied Clear Fork filter-management rules, 2026-08-09.
   These are deliberately centralized so the control boards, alarm bell, Ryan context,
   and process physics all read the SAME filter state. Unknown change thresholds remain
   null/Pending Verification rather than being guessed. */
var FILTER_RULES={
 f5015:{name:'F-5015 Stabilizer Inlet Solids Filter',group:'stab',change:5,trip:null,unit:'PSID',shutdownChange:false,frequency:'Often after roughly 3-5 slug-catcher drain cycles; operator-observed, condition dependent'},
 f5016:{name:'F-5016 Stabilizer Inlet Solids Filter',group:'stab',change:5,trip:null,unit:'PSID',shutdownChange:false,frequency:'Often after roughly 3-5 slug-catcher drain cycles; operator-observed, condition dependent'},
 f1416:{name:'F-1416 Dehy Dust Filter',group:'dust',change:15,trip:20,unit:'PSID',shutdownChange:false,frequency:'Normally infrequent; operator reports roughly twice per year at most'},
 f1417:{name:'F-1417 Dehy Dust Filter',group:'dust',change:15,trip:20,unit:'PSID',shutdownChange:false,frequency:'Normally infrequent; operator reports roughly twice per year at most'},
 f1412:{name:'F-1412 Dehy Inlet Filter/Coalescer',group:'inlet',change:15,trip:20,unit:'PSID',shutdownChange:true,frequency:'Operator reports roughly 1-2 changes per year; replacement requires total facility shutdown'},
 f6800:{name:'F-6800 Residue Filter',group:'residue',change:10,trip:null,unit:'PSID',shutdownChange:true,frequency:'Operator reports roughly 1-2 changes per year; replacement requires total facility shutdown'},
 f1050:{name:'F-1050 Slug-Catcher Liquid Filter',group:'slug',change:8,trip:12,unit:'PSID',shutdownChange:false,frequency:'Duty/standby pair; swap at 8 PSID and change the dirty housing. At 12 PSID the dirty in-service housing stops liquid flow until swapped or changed.'},
 f1055:{name:'F-1055 Slug-Catcher Liquid Filter',group:'slug',change:8,trip:12,unit:'PSID',shutdownChange:false,frequency:'Duty/standby pair; swap at 8 PSID and change the dirty housing. At 12 PSID the dirty in-service housing stops liquid flow until swapped or changed.'},
 f1438:{name:'F-1438 RSV Filter/Coalescer',group:'rsv',change:10,trip:15,unit:'PSID',shutdownChange:false,frequency:'Operator rule: alarm/change at 10 PSID; 15 PSID shuts down the RSV filter/recycle path (XV-1438B closes), not the entire facility.'},
 f7600:{name:'F-7600 Hot Oil Filter',group:'hotoil',change:8,trip:null,unit:'PSID',shutdownChange:false,frequency:'Operator rule: alarm/change element at 8 PSID.'}
};
function filterRec(key){var r=FILTER_RULES[key],g=r&&PLANT.filterHealth[r.group];return r&&g&&g[key]?g[key]:null;}
function filterDP(key){return cfFilterOperating12MZ(key).dp;}
function filterInService(key){var r=FILTER_RULES[key],g=r&&PLANT.filterHealth[r.group];return !!(g&&(!g.service||g.service===key));}
function filterStatus(key){var r=FILTER_RULES[key],dp=filterDP(key);if(!r)return 'UNKNOWN';if(r.group==='slug'&&filterRec(key)&&filterRec(key).slugFlowBlocked12PV)return 'TRIP';if(r.trip!=null&&dp>=r.trip)return 'TRIP';if(r.change!=null&&dp>=r.change)return 'CHANGE';return filterInService(key)?'IN SERVICE':'STANDBY';}
function filterColor(key){var st=filterStatus(key);return st==='TRIP'?'#d7191c':st==='CHANGE'?'#ff9a2f':st==='IN SERVICE'?'#1ea84a':'#6d7f90';}
function filterServiceCard(key,x,y,w){var r=FILTER_RULES[key],dp=filterDP(key),st=filterStatus(key);w=w||150;return '<g data-hmi-equipment12pw="filter" data-filter-key12pw="'+key+'"><rect x="'+x+'" y="'+y+'" width="'+w+'" height="46" rx="4" fill="#e8edf1" stroke="'+filterColor(key)+'" stroke-width="2"/><text x="'+(x+7)+'" y="'+(y+13)+'" fill="#14202a" font-size="8" font-weight="700">'+r.name.split(' ')[0]+'  '+st+'</text><text x="'+(x+7)+'" y="'+(y+29)+'" fill="#14202a" font-size="11" font-family="Consolas,monospace" font-weight="700">DP '+dp.toFixed(2)+' '+r.unit+'</text><text x="'+(x+w-7)+'" y="'+(y+29)+'" fill="'+filterColor(key)+'" font-size="8" text-anchor="end">'+(r.change!=null?'CHANGE '+r.change:'CHANGE PV')+(r.trip!=null?' / TRIP '+r.trip:'')+'</text></g>';}
function filterAlarmOnce(key,kind,msg){if(!PLANT._filterAlarmState)PLANT._filterAlarmState={};var id=key+'_'+kind;if(!PLANT._filterAlarmState[id]){PLANT._filterAlarmState[id]=true;alarm(msg);} }
function filterClearAlarmLatch(key,kind,cond){if(!PLANT._filterAlarmState)return;if(cond)PLANT._filterAlarmState[key+'_'+kind]=false;}
function tickFilterHealth(dt){
 dt=Math.max(0,Number(dt)||0);var F=PLANT.filterHealth,flow=Math.max(0,PLANT.in.flow||0),running=!!(PLANT.in.stabFeedActive||((PLANT.v&&PLANT.v.fit5000a)||0)>0.5);
 /* 12EB: stabilizer-liquid filter loading follows actual condensate movement, not the downstream product-pump state. */
 var sk=F.stab.service||'f5015',sr=F.stab[sk];if(running&&sr){var _stabLiq=Math.max(0,(PLANT.v&&PLANT.v.fit5000a)||0);sr.dp=clmp(sr.dp+dt*(0.000010+_stabLiq*0.00000020),0.05,12);}
 /* Slug-catcher liquid filters: one housing is always selected as duty. DP rises only
    when liquid is actually moving toward the stabilizer; pig/slug liquid accelerates loading. */
 var sgk=F.slug.service||'f1050',sgr=F.slug[sgk];
 var slugLevel=((PLANT.L.LIC1020&&PLANT.L.LIC1020.pv)||0)+((PLANT.L.LIC1025&&PLANT.L.LIC1025.pv)||0)+((PLANT.L.LIC1030&&PLANT.L.LIC1030.pv)||0);
 if(running&&sgr){var slugLoad=(PLANT.in.pigActive?0.00018:0)+(slugLevel/300)*0.000018; sgr.dp=clmp(sgr.dp+dt*(0.000010+slugLoad),0.05,14);}
 if(sgr&&filterDP(sgk)>=12)sgr.slugFlowBlocked12PV=true; /*12PV existing rule stays blocked until swap/change, not self-cleared by zero flow.*/
 PLANT.in.slugFilterBlocked=!!(sgr&&sgr.slugFlowBlocked12PV);
 PLANT.v.pdt1051=sgr?filterDP(sgk):0;
 /* Very slow condition-based fouling for long-life filters. Rates are simulator scaling,
    not claimed real calendar predictions; operator frequency notes are displayed separately. */
 var dk=F.dust.service||'f1416';if(F.dust[dk])F.dust[dk].dp=clmp(F.dust[dk].dp+dt*(flow>20?0.000004:0),0.05,25);
 if(F.inlet.f1412)F.inlet.f1412.dp=clmp(F.inlet.f1412.dp+dt*(flow>20?0.000003:0),0.05,25);
 if(F.residue.f6800)F.residue.f6800.dp=clmp(F.residue.f6800.dp+dt*((PLANT.cmp.c61.run||PLANT.cmp.c62.run||PLANT.cmp.c63.run)?0.000002:0),0.05,15);
 if(F.rsv.f1438)F.rsv.f1438.dp=clmp(F.rsv.f1438.dp+dt*((PLANT.valves.xv1438b>0&&(PLANT.v.ft1438||0)>0.1)?0.0000012:0),0.05,16);
 if(F.hotoil.f7600)F.hotoil.f7600.dp=clmp(F.hotoil.f7600.dp+dt*((PLANT.in.heaterRun!==false)?0.0000025:0),0.05,10);
 if(F.rsv.f1438&&F.rsv.f1438.changeCount&&((PLANT.simSeconds||0)%60===0)&&!IS_CLIENT)cfRsvServicePersist12GA();
 /* Existing process variables now read the common filter model. */
 PLANT.v.pdt1412=filterDP('f1412');PLANT.v.pdt1416a=filterDP(dk);PLANT.v.pdt1438=filterDP('f1438');PLANT.v.pdit7600a=filterDP('f7600');
 /* Operator-facing alarms and shutdowns. */
 Object.keys(FILTER_RULES).forEach(function(k){var r=FILTER_RULES[k],dp=filterDP(k),svc=filterInService(k);if(!svc&&r.group!=='inlet'&&r.group!=='residue'&&r.group!=='rsv'&&r.group!=='hotoil')return;
  if(r.change!=null&&dp>=r.change){filterAlarmOnce(k,'change','FILTER HIGH DP — '+r.name+' '+dp.toFixed(1)+' '+r.unit+' (change/swap threshold '+r.change+'). Send operator to change filter.');}
  else filterClearAlarmLatch(k,'change',true);
  if(r.trip!=null&&dp>=r.trip){filterAlarmOnce(k,'trip','FILTER DP HI-HI — '+r.name+' '+dp.toFixed(1)+' '+r.unit+' reached '+r.trip+' '+r.unit+' shutdown/no-flow threshold.');if((k==='f1412'||k==='f1416'||k==='f1417')&&!PLANT.esd){PLANT.esd=true;['c41','c42','c61','c62','c63'].forEach(function(c){if(PLANT.cmp[c])(PLANT.cmp[c].run=false,cfResetInletStopped12MF(PLANT.cmp[c]));});if(EXP)EXP.run=false;} if(k==='f1438'&&PLANT.valves){PLANT.valves.xv1438b=0;} }
  else filterClearAlarmLatch(k,'trip',true);
 });
}
/* Clear Fork reciprocating-compressor capacity model — operator-confirmed cumulative logic.
   Load-step NUMBER is cumulative: moving to a higher step RETAINS every earlier loaded
   capacity block and adds the next one. Steps do not replace each other.

   Valid steps are 0 through 6 on inlet and 0 through 9 on residue packages (12PT operator correction). At 80% Remote Capacity:
     step 0 = the package's minimum loaded/base capacity;
     step 1 ADDS the largest capacity block;
     step 3 ADDS the second-largest capacity block;
     steps 2, 4, 5 and 6 each ADD the same smaller capacity block; residue steps 7, 8 and 9 add that same small block.

   Remote Capacity is a separate continuous multiplier: 50% = unloaded, 80% = usual full
   operating point, and 100% = maximum modeled package capacity. Exact cylinder maps are
   not available, so the additive block sizes are empirical training calibration values.
   They preserve the operator-confirmed simultaneous anchors:
     C-4100 alone at cumulative step 6 / 80% -> FIT-1045A about 128 MMSCFD;
     C-6100 cumulative step 3 plus C-6300 step 0 / 80% -> about 128 MMSCFD gross residue
     compressor capacity before the normal 10-18 MMSCFD plant shrinkage to sales. */
/* 12FZ: operator-requested running scenario; empirical simulator calibration only.
   One-time seed, never a per-tick RUN override. Existing storage is not cleared. */
var CF_SOURCE_12MF=cfPayload12PJ.create("p58");
function cfInletCapacityNote12MF(source){
 return {t:source.title,d:[source.scope].concat(source.newEntries.map(function(e){return (e.authority?e.authority+': ':'OPERATOR OBSERVATION: ')+e.text;}))};
}
/* 12MF - inlet only. All numerical trim gains here are simulator calibration,
 * not a package performance guarantee or a new field protection setpoint. */
function cfResetInletStopped12MF(c){
 if(c&&c.type==='inlet'&&!c.run){c.remCapSP=50;c.sequenceState=null;c.sequenceTimer=0;}
 return c;
}
function cfInletCapacityNext12MF(value,direction){
 var v=Number(value),d=Number(direction);if(!isFinite(v))v=80;
 if(!isFinite(d)||d===0)return clmp(v,50,100);
 return clmp((d>0?Math.floor((v+1e-8)/5)+1:Math.ceil((v-1e-8)/5)-1)*5,50,100);
}
function cfAdjustInletCapacity12MF(c,direction){
 if(!c||c.type!=='inlet')return false;
 if(!c.run){cfResetInletStopped12MF(c);alarm(c.name+' is STOPPED at 50% Remote Capacity. START retains Step 0 / 50%.');return false;}
 // An old saved automatic STOPPING state must not take over manual rundown.
 if(c.sequenceState==='STOPPING'){c.sequenceState=null;c.sequenceTimer=0;}
 var next=cfInletCapacityNext12MF(c.remCapSP==null?80:c.remCapSP,direction);
 if(next===50&&(c.step||0)>0){alarm('SIMULATOR SHUTDOWN PREPARATION - remove '+c.name+' load steps to Step 0 before selecting 50%. Normal loaded 75 / 80 / 85% trimming remains available.');return false;}
 c.remCapSP=next;
 if(c.sequenceState==='STARTING'&&next>=80){c.sequenceState=null;c.sequenceTimer=0;alarm(c.name+' Remote Capacity 80% reached - load-step increases are enabled.');}
 return true;
}
function cfInletShutdownGuide12MF(c){
 if(!c||!c.run)return 'STOPPED - Remote Capacity 50%. START remains Step 0 / 50%.';
 if((c.step||0)>0)return 'Normal reference 80%. Controlled shutdown: remove all load steps, then reduce capacity by 5 points to 50%, then press SHUTDOWN.';
 if(Number(c.remCapSP)>50)return 'All load steps are out. Reduce Remote Capacity by 5 points to 50%, then press SHUTDOWN. No automatic rundown.';
 return 'Step 0 / Remote Capacity 50% - ready for SHUTDOWN. The driver keeps running until you press SHUTDOWN.';
}
