function trendAvg(key){
 /* Honest approximation, not a real time-windowed shift average: TREND_LOG only
    keeps a timestamped rolling 72-hour history, so
    this is "average of recent trend history," not "average since shift start."
    Labeled as such everywhere it's displayed rather than implying more precision
    than the underlying data actually has. */
 var arr=TREND_LOG[key];
 if(!arr||!arr.length)return 0;
 var sum=0; for(var i=0;i<arr.length;i++)sum+=arr[i];
 return sum/arr.length;
}
function sparkline(key,w,h,color){
 var arr=TREND_LOG[key];
 w=w||80;h=h||20;color=color||'#5fa8f5';
 if(!arr||arr.length<2)return '<svg width="'+w+'" height="'+h+'"></svg>';
 var lo=Math.min.apply(null,arr),hi=Math.max.apply(null,arr);
 var range=(hi-lo)||1;
 var pts=arr.map(function(v,i){var x=(i/(arr.length-1))*w;var y=h-((v-lo)/range)*h;return x.toFixed(1)+','+y.toFixed(1);}).join(' ');
 return '<svg width="'+w+'" height="'+h+'" style="vertical-align:middle;"><polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="1.3"/></svg>';
}
function shiftExportCSV(){return cfOpsCSV12OU();}
function recordTrend(key, value){
 if(!CF_TREND_RECORDING_12OQ||typeof value!=='number'||!Number.isFinite(value))return;
 if(CF_TREND_CHANNELS_12OQ[key]&&!CF_TREND_SAMPLING_12OQ)return;
 var now=cfSimulationTimestamp12OO();
 var arr=TREND_LOG[key];if(!arr){arr=[];TREND_LOG[key]=arr;}
 var ta=TREND_TIME[key];if(!ta){ta=[];TREND_TIME[key]=ta;}
 /* Keep long trends readable and browser-friendly: one point every 60 s, but update
    the newest point in between so CURRENT remains live. */
 if(ta.length && now-ta[ta.length-1] < TREND_MIN_SAMPLE_MS){arr[arr.length-1]=value;return; /* retain bucket start; moving it every tick prevented all later 60-second samples */}
 arr.push(value);ta.push(now);
 var cutoff=now-TREND_RETENTION_MS;
 while(ta.length && (ta[0]<cutoff || arr.length>TREND_MAX)){ta.shift();arr.shift();}
}
