 s+=mPipe('M900 170 V205 H1010')+mValve(1010,205,'xv5040a')+mPipe('M1025 205 H1160')+mArr(1160,205,'TO V-5010 FLASH TANK',false);
 s+='<text x="925" y="123" fill="#283038" font-size="6.3">NORMAL PRODUCT</text><text x="925" y="226" fill="#283038" font-size="6.3">RECYCLE / RETURN</text>';
 /* ZONE 3: C-5700 overhead compressor (y 260-560, right side) */
 s+='<g data-act="cpop" data-c="c57" style="cursor:pointer">';
