/*12OV CONTROL-BOARD FINISH ONLY. Exact existing diagram shapes are identified by
  screen, coordinates, paint and action ancestry. No control/source/state mutation,
  route change, valve styling, new hardware, geometry or interactive target is made.
  Added SVG nodes are noninteractive decorative paint over existing silhouettes.*/
var CF_HMI_PAINT_MANIFEST_12OV=cfPayload12PJ.create("p59");
var CF_HMI_PAINTED_12OV=new WeakSet(),CF_HMI_PAINT_SEQUENCE_12OV=0;
function cfHmiShapeKey12OV(el){
 var fields={rect:['x','y','width','height','rx','ry'],circle:['cx','cy','r'],ellipse:['cx','cy','rx','ry'],path:['d'],line:['x1','y1','x2','y2'],polyline:['points'],polygon:['points']};
 var tag=el.localName;return tag+'|'+(fields[tag]||[]).map(function(k){return el.getAttribute(k)||'';}).join('|')+'|'+(el.getAttribute('transform')||'');
}
function cfPolishControlGraphics12OV(root,screenKey){
 if(!root||root.id!=='eqtscr')return;
 var rules=CF_HMI_PAINT_MANIFEST_12OV[screenKey];if(!rules||!Object.keys(rules).length)return;
 var ns='http://www.w3.org/2000/svg';
 function make(tag,attrs){var el=document.createElementNS(ns,tag);Object.keys(attrs).forEach(function(k){el.setAttribute(k,String(attrs[k]));});return el;}
 function action(el){var a=[];for(var p=el.parentElement;p;p=p.parentElement)if(p.hasAttribute('data-act'))a.push((p.getAttribute('data-act')||'')+':'+(p.getAttribute('data-c')||'')+':'+(p.getAttribute('data-v')||''));return a.join('|');}
 var svgs=Array.from(root.querySelectorAll('.mwrap > svg')).filter(function(s){return !s.closest('.pop');});
 svgs.forEach(function(svg,index){
  if(CF_HMI_PAINTED_12OV.has(svg))return;
  var shapes=Array.from(svg.querySelectorAll('rect,circle,ellipse,path,line,polyline,polygon')),defs=null,gradients={},prefix='cf-hmi-finish12ov-'+(++CF_HMI_PAINT_SEQUENCE_12OV)+'-';
  function gradient(kind){
   if(gradients[kind])return gradients[kind];
   if(!defs){defs=make('defs',{'data-cf-cosmetic12ov':'paint-definitions','aria-hidden':'true'});svg.insertBefore(defs,svg.firstChild);}
   var dark=/Dark$/.test(kind),type=kind.replace(/Dark$/,''),id=prefix+kind,g;
   if(type==='round')g=make('radialGradient',{id:id,cx:'.32',cy:'.28',r:'.82',fx:'.28',fy:'.24'});
   else g=make('linearGradient',{id:id,x1:'0',y1:'0',x2:type==='horizontal'?'0':'1',y2:type==='vertical'?'0':'1'});
   var stops=type==='round'?[[0,'#ffffff',dark?.32:.65],[.35,'#ffffff',dark?.10:.22],[.72,'#172e40',.12],[1,'#11212f',.48]]:
    type==='panel'?[[0,'#ffffff',.5],[.28,'#ffffff',.08],[.58,'#ffffff',0],[1,'#143047',dark?.28:.26]]:
    [[0,'#142b3d',dark?.25:.34],[.18,'#ffffff',dark?.20:.48],[.4,'#ffffff',dark?.10:.18],[.7,'#16364b',.12],[1,'#102536',dark?.42:.38]];
   stops.forEach(function(st){g.appendChild(make('stop',{offset:st[0],'stop-color':st[1],'stop-opacity':st[2]}));});defs.appendChild(g);gradients[kind]=id;return id;
  }
  shapes.forEach(function(el){
   if(el.closest('defs,clipPath,mask')||el.hasAttribute('data-cf-cosmetic12ov'))return;
   var spec=rules[index+'|'+cfHmiShapeKey12OV(el)];if(!spec||action(el)!==spec.action)return;
   var paintOk=spec.paints.some(function(p){return Object.keys(p).every(function(k){return (el.getAttribute(k)||'')===p[k];});});if(!paintOk)return;
   var copy=make(el.localName,{'data-cf-cosmetic12ov':spec.kind==='pipe'?'pipe':'body','aria-hidden':'true',focusable:'false','pointer-events':'none',style:'pointer-events:none!important;user-select:none'});
   ['x','y','width','height','rx','ry','cx','cy','r','d','points','x1','y1','x2','y2','transform','fill-rule','stroke-linecap','stroke-linejoin','stroke-miterlimit','vector-effect','pathLength','clip-path','mask','opacity','visibility','display'].forEach(function(k){if(el.hasAttribute(k))copy.setAttribute(k,el.getAttribute(k));});
   if(spec.kind==='pipe'){
    var width=Number(el.getAttribute('stroke-width'));if(!Number.isFinite(width)||width<=0)return;
    copy.setAttribute('fill','none');copy.setAttribute('stroke','#ffffff');copy.setAttribute('stroke-width',String(width*.30));copy.setAttribute('stroke-opacity','.34');
   }else{copy.setAttribute('fill','url(#'+gradient(spec.kind)+')');copy.setAttribute('stroke','none');}
   el.parentNode.insertBefore(copy,el.nextSibling);
  });
  CF_HMI_PAINTED_12OV.add(svg);
 });
}
