/* 12EW: multi-point empirical rod-load interpolation. Exact photographed points are honored at their observed load-step/pressure conditions. Between points, each throw is weighted independently by step and pressure proximity; outside the observed range, only a modest pressure/load extrapolation is allowed. This is training calibration, not an Ariel Performance replacement. */
function calibratedRodLoads(c){
 var pts=(c&&c.rodCal)||null;if(!pts||!pts.length)return c&&c.rodBase?c.rodBase:[];
 var step=Number(c.step||0), suc=Number(c.suc||0), dis=Number(c.dis||0), curDP=Math.max(1,dis-suc), out=[];
 var nearest=null,nearestD=1e9;
 for(var i=0;i<pts.length;i++){var q=pts[i],d=Math.abs(step-q.step)*2.6+Math.abs(suc-q.suc)/18+Math.abs(dis-q.dis)/28;if(d<nearestD){nearestD=d;nearest=q;}}
 if(nearest&&nearestD<0.03)return nearest.loads.map(function(v){return [v[0],v[1]];});
 for(var t=0;t<6;t++){
  var sw=0,cv=0,tv=0,refDP=0,refStep=0;
  for(var j=0;j<pts.length;j++){var p0=pts[j],d0=Math.abs(step-p0.step)*2.6+Math.abs(suc-p0.suc)/18+Math.abs(dis-p0.dis)/28;var w=1/Math.pow(0.08+d0,2);sw+=w;cv+=w*p0.loads[t][0];tv+=w*p0.loads[t][1];refDP+=w*Math.max(1,p0.dis-p0.suc);refStep+=w*p0.step;}
  cv/=sw;tv/=sw;refDP/=sw;refStep/=sw;
  {var pFac=clmp(Math.pow(curDP/refDP,0.32),0.88,1.14);var stepFac=clmp(1+(step-refStep)*0.035,0.82,1.20);cv*=pFac*stepFac;tv*=pFac*stepFac;}
  out.push([cv,tv]);
 }
 return out;
}
