/* ===== valve tag -> plain-English identification (type + associated equipment) ===== */
var VALVE_PREFIX={
 xv:'Block valve (ESD-actuated on/off)', xxy:'Solenoid pilot valve (drives an XV)',
 lcv:'Level control valve', pcv:'Pressure control valve', tcv:'Temperature control valve',
 fcv:'Flow control valve', fv:'Flow control valve', pdcv:'Differential-pressure control valve',
 pv:'Pressure relief/control valve', tv:'Temperature control valve', lv:'Level control valve',
 esd:'Emergency shutdown valve', rcy:'Recycle/spillback valve', fcv1121:'C-1121 booster anti-surge recycle valve'
};
var VALVE_SERVICE={
 1000:'V-1000 pig receiver / plant inlet',1010:'Plant inlet pressure control',1040:'V-1040 inlet vortex separator',
 1410:'V-1410 inlet gas separator',1412:'F-1412 dehy inlet filter',1421:'V-1421 cold separator',
 1422:'V-1422 / T-1521 demethanizer surge & bottoms',1438:'F-1438 RSV recycle coalescer',1441:'V-1441/refrigeration suction',
 1442:'V-1442 refrigerant economizer',1444:'V-1444 refrigerant accumulator',1521:'T-1521 demethanizer',
 1619:'P-1619/1620 product booster pumps',1620:'P-1619/1620 product booster pumps',1650:'V-1650 cold drain tank',
 4100:'C-4100 inlet compressor',4200:'C-4200 inlet compressor',4250:'Inlet compressor discharge header',
 5000:'E-5000 inlet stabilizer preheater',5001:'Methanol injection to E-5000',5005:'E-5000 temperature control',
 5010:'V-5010 inlet stabilizer flash tank',5020:'FIC-5020 stabilizer feed flow',5030:'T-5030 stabilizer pressure',
 5040:'E-5040 / TIC-5040 stabilizer reboiler hot oil',6810:'Inlet compressor suction header',
 8000:'V-8000 NGL pig launcher / custody metering',8207:'Residue pig launcher isolation',8220:'Fuel-gas takeoff isolation',
 9110:'Instrument air header',1140:'C-1140 refrigeration compressor discharge',143:'FIC-143S RSV recycle split',
 1223:'Gas/gas exchanger reflux split (TCV-1223)',1221:'Gas/gas exchanger main split (TCV-1221)',1222:'FFIC-1222 gas/gas recycle flow'
};
function valveInfo(vk){
 var low=vk.toLowerCase();
 var pfx=null;
 ['xxy','xv','lcv','pcv','tcv','pdcv','fcv','esd','rcy','fv','tv','lv','pv'].forEach(function(p){
  if(!pfx && low.indexOf(p)===0) pfx=p;
 });
 var typeDesc=pfx?VALVE_PREFIX[pfx]:'Valve';
 var numMatch=low.match(/(\d{3,4})/);
 var svc=numMatch?(VALVE_SERVICE[parseInt(numMatch[1])]||('Line/equipment '+numMatch[1])):'';
 var exact=cf3dDeviceRecord(vk)||cf3dDeviceRecord(typeof cfRefResolve==='function'?cfRefResolve(vk):'');
 if(exact&&(exact.assetId==='cf3d_fcv1211a'||exact.assetId==='cf3d_cv_tcv1223'))svc=exact.service;
 return {type:typeDesc, service:svc};
}
function showValveInfo(vk,isOpen){
 var info=valveInfo(vk);
 var vp=document.getElementById('valveInfoPopup');
 if(!vp){
  vp=document.createElement('div'); vp.id='valveInfoPopup';
  vp.style.cssText='position:fixed;z-index:999;background:rgba(10,14,20,0.96);border:1px solid #3a4a5c;border-radius:6px;padding:10px 14px;font:12px Consolas,monospace;color:#dce6ee;box-shadow:0 6px 20px rgba(0,0,0,0.5);max-width:280px;pointer-events:none;';
  document.body.appendChild(vp);
 }
 vp.innerHTML='<div style="font-weight:700;color:#fff;margin-bottom:4px;">'+vk.toUpperCase()+'</div>'+
  '<div style="color:#9ec8ff;margin-bottom:3px;">'+info.type+'</div>'+
  (info.service?'<div style="color:#b8c4cc;margin-bottom:3px;">Service: '+info.service+'</div>':'')+
  '<div style="color:'+(isOpen?'#5cff8f':'#ff8a7a')+';font-weight:700;">'+(isOpen?'OPEN':'CLOSED')+'</div>';
 vp.style.display='block';
 clearTimeout(window.__vpTimer);
 window.__vpTimer=setTimeout(function(){vp.style.display='none';},4000);
}
function cfDiscreteValveCommand(vk){
 var discrete=(vk==='esd1000d'||vk==='xv1040a');
 if(!discrete)return false;
 var key=vk+'State', cur=PLANT.in[key]||(PLANT.valves[vk]?'OPEN':'CLOSED');
 if(PLANT.esd&&vk==='esd1000d'){PLANT.in[key]='TRIPPED';PLANT.valves[vk]=0;alarm('ESD-1000D TRIPPED — reset facility ESD before opening');return true;}
 if(cur==='OPEN'||cur==='OPENING'){PLANT.in[key]='CLOSING';}
 else if(cur==='CLOSED'||cur==='CLOSING'){PLANT.in[key]='OPENING';}
 else if(cur==='TRIPPED'){alarm(vk.toUpperCase()+' is TRIPPED — RESET required');return true;}
 PLANT.in[key+'Ticks']=0; return true;
}
function cfTickDiscreteValve(vk){
 var key=vk+'State', st=PLANT.in[key]; if(!st){PLANT.in[key]=PLANT.valves[vk]?'OPEN':'CLOSED';return;}
 if(st==='OPENING'||st==='CLOSING'){
  var tk=(PLANT.in[key+'Ticks']||0)+1; PLANT.in[key+'Ticks']=tk;
  if(tk>=3){PLANT.in[key]=(st==='OPENING'?'OPEN':'CLOSED');PLANT.valves[vk]=(st==='OPENING'?1:0);}
 }
}
