/* ===== more mimics: 60/40 split (TCVs), demeth fix, inlet/dehy/stab/hot-oil ===== */
PLANT.split={tcvA:60,tcvB:40};
/* Dehy automatic switch-valve state. The simulator convention is A/B = process
   inlet/outlet and C/D = reverse-flow regeneration inlet/outlet. This is the
   convention already used by the control-board model; the source drawings prove
   the four-valve-per-bed topology but do not justify inventing any different
   suffix mapping. Sequence ownership is automatic: operators may inspect these
   valves but cannot manually defeat the bed sequence from the mimic. */
function syncDehySequenceValves(){
 if(!PLANT||!PLANT.valves||!PLANT.v)return;
 var V=PLANT.v;if(V.dehyRegenBed==null)V.dehyRegenBed=2;if(!V.dehyPhase)V.dehyPhase='HEAT';
 [1413,1414,1415].forEach(function(tag,i){var process=(i!==V.dehyRegenBed);
  PLANT.valves['xv'+tag+'a']=process?1:0; /* process inlet */
  PLANT.valves['xv'+tag+'b']=process?1:0; /* process outlet */
  PLANT.valves['xv'+tag+'c']=process?0:1; /* regen inlet */
  PLANT.valves['xv'+tag+'d']=process?0:1; /* regen outlet */
 });
}
