 var modeled=all.filter(function(r){return r.modeled;}).length;
 cfDeviceListElement('p',all.length+' current records | '+modeled+' linked to model devices | '+(all.length-modeled)+' reference / pending records',host,'cf-reg-count');
 cfDeviceListElement('p',kind==='psv'?
  'One place for every currently modeled PSV, dedicated relief reference, pending source slot, and uploaded PSV-tag record. Select a row for set pressure, protected equipment, physical location, P&ID page / revision / grid, discharge destination, source information, and linked uploads.':
  'Control, shutdown and automatic sequence valve records. Select a row to view the same source-labelled information shown by the 3D model.',host,'cf-reg-note');
 cfDeviceListElement('p','This is a working source register, not a verified complete facility inventory. Pending fields are not inferred from equipment pressure ratings. Model coordinates are schematic, not surveyed field locations. Uploaded information retains its source and verification status.',host,'cf-reg-warning');
 var wrap=cfDeviceListElement('div',null,host,'cf-reg-table-wrap'),table=cfDeviceListElement('table',null,wrap,'cf-reg-table');
 var tr=cfDeviceListElement('tr',null,cfDeviceListElement('thead',null,table));
