function cfDeviceListSourceNotes(row,host){
 if(!row.references.length&&!row.learned.length)return;
 var section=cfDeviceListElement('section',null,host,'cf-reg-sources');cfDeviceListElement('h3','Linked source notes',section);
 var seen=Object.create(null);
 row.references.forEach(function(key){var info=INFO[key];if(!info)return;var sig=JSON.stringify(info);if(seen[sig])return;seen[sig]=true;
  var details=cfDeviceListElement('details',null,section);cfDeviceListElement('summary',info.t+' ['+key+']',details);
  (info.d||[]).forEach(function(text){cfDeviceListElement('p',text,details);});
 });
 var learned=libLearnedRecords();row.learned.forEach(function(key){var r=learned[key];if(!r)return;
  var details=cfDeviceListElement('details',null,section);details.open=true;
  cfDeviceListElement('summary','Uploaded / extracted: '+(r.primaryTitle||r.tag),details);
  (r.operatorDescriptions||[]).forEach(function(s){cfDeviceListElement('p',s,details);});
  var facts=Array.isArray(r.facts)?r.facts:[];cfDeviceListElement('small',facts.length+' stored fact(s). Original source status is preserved.',details);
  facts.slice(0,60).forEach(function(f){cfDeviceListElement('p',String(f.statement||'')+' [Source: '+(f.sourceTitle||f.sourceDocumentId||'Pending')+(f.page?', page '+f.page:'')+'; '+(f.verificationStatus||'DOCUMENT_EXTRACTED_UNVERIFIED')+']',details);});
  cfDeviceListButton('Open full learned record',details,function(){libSel.cat='learned';libSel.key=key;var e=document.getElementById('libSearch');if(e)e.value='';libRenderCats();libRenderList(null);libRenderDetail();});
 });
}
