/* ===== Material/lighting quality pass, adapted from the handoff's material-tuning
   logic (auditMaterials/tweakMaterial) -- ported for real this time using this file's
   own actual `scene` variable directly, rather than the handoff's window.scene-searching
   helpers (findScene/findRenderer), which is what made it look unportable at first look.
   Subtle: slightly boosts metalness/roughness realism on pipe/steel/vessel surfaces,
   very slightly increases roughness elsewhere, and enables shadow casting/receiving on
   smaller meshes. Purely cosmetic -- does not touch geometry, positions, physics, or any
   process/DCS logic, matching the same "visual-only" boundary the original feature drew. */
var CLEARFORK_WEATHERING=true;
function isPhysicalMesh(o){return o&&o.isMesh&&o.material&&!(o.userData&&(o.userData.isHUD||o.userData.screen||o.userData.overlay));}
function tweakMaterial(m,name){
 if(!m||!m.isMeshStandardMaterial)return;
 var b=CF_MATERIAL_BASE_12ML.get(m);if(!b){b={roughness:m.roughness,metalness:m.metalness};CF_MATERIAL_BASE_12ML.set(m,b);}
 var structural=/pipe|steel|rail|ladder|structure|valve|vessel|tank|compressor|cooler/.test(String(name||'').toLowerCase());
 // Uniform-only material adjustment: preserve color maps, service colors and shared materials.
 m.roughness=CLEARFORK_WEATHERING?structural?Math.max(.38,Math.min(.88,(b.roughness==null?.62:b.roughness)+.08)):Math.max(.48,Math.min(1,(b.roughness==null?.7:b.roughness)+.035)):b.roughness;
 m.metalness=CLEARFORK_WEATHERING&&structural?Math.max(.45,Math.min(.88,(b.metalness==null?.55:b.metalness)+.08)):b.metalness;
}
function auditMaterials(sc){
 var count=0,materials=new Map();
 sc.traverse(function(o){if(!isPhysicalMesh(o))return;
  var mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(function(m){if(!m||!m.isMeshStandardMaterial)return;count++;var prior=materials.get(m);if(prior===undefined||/pipe|steel|rail|ladder|structure|valve|vessel|tank|compressor|cooler/i.test(o.name||''))materials.set(m,o.name||'');});
  if(o.geometry&&o.geometry.attributes&&o.geometry.attributes.position&&o.geometry.attributes.position.count<65000){o.castShadow=true;o.receiveShadow=true;}
 });materials.forEach(function(name,m){tweakMaterial(m,name);});
 CF_SPEED_12ML.materialVisits=count;CF_SPEED_12ML.uniqueMaterials=materials.size;
 window.CLEARFORK_VISUAL_MATERIAL_AUDIT={standardMaterialsAdjusted:materials.size,meshMaterialReferences:count,weathering:CLEARFORK_WEATHERING,checkedAt:new Date().toISOString()};return count;
}
auditMaterials(scene);
document.getElementById('cfWeatherToggle').addEventListener('click',function(){
 CLEARFORK_WEATHERING=!CLEARFORK_WEATHERING;
 this.textContent=(CLEARFORK_WEATHERING?'Weathering: ON':'Weathering: OFF');
 auditMaterials(scene);
});
