function mPipe(d,on){return '<path d="'+d+'" fill="none" stroke="'+(on===false?'#9aa0a4':'#1b1f24')+'" stroke-width="3.5"/>';}
function mDrum(x,y,w,hh,lab){var r=hh/2;return '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" rx="'+r+'" ry="'+r+'" fill="#fbfbfc" stroke="#1b1f24" stroke-width="2"/><text x="'+(x+w/2)+'" y="'+(y+hh/2+4)+'" fill="#10151b" font-size="11" text-anchor="middle">'+lab+'</text>';}
function mCol(x,y,w,hh,lab){var s='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" rx="7" fill="#fbfbfc" stroke="#1b1f24" stroke-width="2"/>';for(var i=1;i<6;i++){var yy=y+hh*i/6;s+='<line x1="'+x+'" y1="'+yy+'" x2="'+(x+w)+'" y2="'+yy+'" stroke="#c2c8cc" stroke-width="1"/>';}return s+'<text x="'+(x+w/2)+'" y="'+(y+hh+14)+'" fill="#10151b" font-size="11" text-anchor="middle">'+lab+'</text>';}
function mExch(x,y,w,hh,lab){var s='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" fill="#fbfbfc" stroke="#1b1f24" stroke-width="2"/>';var zg='M'+(x+6)+' '+(y+hh/2);for(var i=0;i<6;i++){zg+=' L'+(x+6+(i+0.5)*(w-12)/6)+' '+(y+(i%2?hh-8:8))+' L'+(x+6+(i+1)*(w-12)/6)+' '+(y+hh/2);}s+='<path d="'+zg+'" fill="none" stroke="#5a6671" stroke-width="2"/>';return s+'<text x="'+(x+w/2)+'" y="'+(y+hh+13)+'" fill="#10151b" font-size="10" text-anchor="middle">'+lab+'</text>';}
function mComp(x,y,lab){return '<circle cx="'+x+'" cy="'+y+'" r="21" fill="#fbfbfc" stroke="#1b1f24" stroke-width="2"/><path d="M'+(x-11)+' '+(y-10)+' L'+(x+13)+' '+y+' L'+(x-11)+' '+(y+10)+' Z" fill="#c2c8cc" stroke="#1b1f24"/><text x="'+x+'" y="'+(y+36)+'" fill="#10151b" font-size="10.5" text-anchor="middle">'+lab+'</text>';}
function mFan(x,y,lab){return '<rect x="'+(x-26)+'" y="'+(y-9)+'" width="52" height="18" rx="3" fill="#fbfbfc" stroke="#1b1f24" stroke-width="1.5"/><line x1="'+(x-18)+'" y1="'+y+'" x2="'+(x+18)+'" y2="'+y+'" stroke="#5a6671" stroke-width="2"/><text x="'+x+'" y="'+(y+22)+'" fill="#10151b" font-size="9.5" text-anchor="middle">'+lab+'</text>';}
function mValve(x,y,vk){var op=PLANT.valves[vk];var col=op?'#1ea84a':'#c0392b';return '<g data-act="valve" data-v="'+vk+'" style="cursor:pointer"><path d="M'+(x-10)+' '+(y-9)+' L'+x+' '+y+' L'+(x-10)+' '+(y+9)+' Z" fill="'+col+'" stroke="#1b1f24"/><path d="M'+(x+10)+' '+(y-9)+' L'+x+' '+y+' L'+(x+10)+' '+(y+9)+' Z" fill="'+col+'" stroke="#1b1f24"/><text x="'+x+'" y="'+(y-13)+'" fill="#10151b" font-size="8.5" text-anchor="middle">'+vk.toUpperCase()+'</text></g>';}
function mTag(x,y,lab,val,unit){var raw='<g><text x="'+(x+2)+'" y="'+(y+8)+'" fill="#26303a" font-size="8.5">'+lab+'</text><rect x="'+x+'" y="'+(y+11)+'" width="96" height="21" rx="2" fill="#0a0d10" stroke="#3a4148"/>'+cfReadoutSvg12NK(x+5,y+26,86,val,unit,13,8,'#22e34a','#7fb0c0',0)+'</g>';var n=parseFloat(String(val).replace(/,/g,''));if(isFinite(n)&&unit){var k=arguments[5]||lab.replace(/[^A-Za-z0-9]/g,'').toLowerCase();recordTrend(k,n);return cfHmiFaceplate12PU(('<g data-act="trend" data-key="'+k+'" data-label="'+lab+'" data-unit="'+(unit||'')+'" style="cursor:pointer">'+raw+'</g>'),"reading");}return cfHmiFaceplate12PU((raw),"reading");}
function mArr(x,y,lab,left){var p=left?('M'+(x+20)+' '+(y-7)+' L'+x+' '+y+' L'+(x+20)+' '+(y+7)+' Z'):('M'+x+' '+(y-7)+' L'+(x+20)+' '+y+' L'+x+' '+(y+7)+' Z');return '<path d="'+p+'" fill="#1b1f24"/><text x="'+(left?x+24:x-4)+'" data-hmi-destination12pu="true" y="'+(y-11)+'" fill="#26303a" font-size="8.5" text-anchor="'+(left?'start':'end')+'">'+lab+'</text>';}
/* ===== Interlock engine (new) =====
   Real, live-evaluated permissive lists for ESD-1000D, XV-1410, and XV-1040A, built
   from the actual DCS interlock screenshots supplied for this area. Status convention:
   GREEN=healthy, RED=failed/must be corrected, GRAY=evaluation error, YELLOW=overridden.
   Any condition whose real numeric setpoint wasn't given is evaluated against this
   simulator's own existing alarm thresholds where one already exists (e.g. the >85%
   slug-catcher HH indicator already shown on the Plant Inlet screen), and is otherwise
   explicitly marked "Requires Verification" in its own description -- never guessed. */
var CRYO_SECTION_COMMON=[
 {tag:'Plant_ESD',desc:'Main Plant ESD',ok:function(){return !PLANT.esd;}},
 {tag:'PT-1410B',desc:'F-1412 Inlet Gas Pressure High-High Shutdown (setpoint Requires Verification)',ok:function(V){return (V.p1410-1.9)<1100;}},
 {tag:'LSHH-1410',desc:'V-1410 Inlet Gas Separator Liquid Level High-High',ok:function(V){return V.lvl1410<85;}},
 {tag:'PDT-1412',desc:'F-1412 Inlet Filter/Coalescer Differential Pressure High-High Shutdown — operator-confirmed: CHANGE at 15 PSID, facility ESD at 20 PSID',ok:function(V){return V.pdt1412<20;}},
 {tag:'LSHH-1412A',desc:'F-1412 Inlet Gas Filter Upper Liquid Level High-High (75%)',ok:function(V){return V.lvl1412a<75;}},
 {tag:'LSHH-1412B',desc:'F-1412 Inlet Gas Filter Lower Liquid Level High-High (75%)',ok:function(V){return V.lvl1412b<75;}},
 {tag:'PDT-1416A',desc:'Dehy Dust Filter (F-1416/F-1417) Differential Pressure High-High -- confirmed real: 20 PSID trips, 15 PSID means swap needed',ok:function(V){return (V.pdt1416a==null)||V.pdt1416a<20;}},
 {tag:'TE-1416',desc:'Dehy Dust Filter Inlet Temperature High-High -- confirmed real setpoint: 150\u00b0F',ok:function(V){return (V.te1416==null)||V.te1416<150;}},
 {tag:'TE-1417',desc:'Dehy Bed Process Gas Outlet Temperature High-High (setpoint Requires Verification)',ok:function(){return true;}},
 {tag:'TE-1221A',desc:'E-1221/222 Exchanger Gas Side Outlet Temperature Low -- confirmed real (Ryan): shares the identical 40°F low alarm / -15°F low-low facility ESD setpoint already modeled for TE-1221D. Not yet hoisted to its own live PLANT.v variable, so the live check below still proxies off TE-1221D rather than guessing a separate one.',ok:function(V){return (V.te1221d==null)||V.te1221d>-15;}},
 {tag:'TE-1221D',desc:'E-1221/222 Exchanger Gas Side Outlet Temperature Low -- confirmed real: 40\u00b0F low alarm, -15\u00b0F low-low facility ESD',ok:function(V){return (V.te1221d==null)||V.te1221d>-15;}},
 {tag:'PDT-1222C',desc:'E-1221/223 Gas-to-Gas Exchanger Differential Pressure -- confirmed real: 30 PSID high alarm, 40 PSID high-high shutdown. Not yet backed by a live PLANT.v variable, so the check itself still evaluates healthy by default.',ok:function(){return true;}},
 {tag:'LSHH-1421',desc:'V-1421 Cold Separator Liquid Level High-High',ok:function(V,L){return L.LIC1421.pv<90;}},
 {tag:'TE-1421A',desc:'V-1421 Cold Separator Outlet Temperature Low-Low -- confirmed real setpoint: -50\u00b0F',ok:function(V){return (V.te1421a==null)||V.te1421a>-50;}},
 {tag:'PT-1521A',desc:'T-1521 Demethanizer Outlet Pressure High-High -- shares the real facility ESD trip already modeled (PIC-1521 HH 500 psig); confirmed real high ALARM (not shutdown) at 425 psig',ok:function(V,L){return L.PIC1521.pv<500;}},
 {tag:'TE-1521F',desc:'Demethanizer Tower Bottoms Temperature Low-Low Shutdown -- confirmed real: -20\u00b0F LOLO shutdown, 0\u00b0F low alarm, 200\u00b0F high alarm',ok:function(V){return (V.demBot==null)||(V.demBot+0.60)>-20;}},
 {tag:'TE-1521E',desc:'T-1521 Demethanizer Liquid Outlet Temperature Low -- confirmed real: -20\u00b0F LOLO shutdown, 0\u00b0F low alarm, 200\u00b0F high alarm',ok:function(V){return (V.demBot==null)||V.demBot>-20;}},
 {tag:'LSHH-1422',desc:'V-1422 Surge Tank Liquid Level High-High (80% shutdown)',ok:function(V,L){return L.LIC1422.pv<80;}},
 {tag:'TE-1223B',desc:'E-1223 Demethanizer Bottom Reboiler Inlet Temperature (source screenshots repeat this tag twice on some popups -- preserved as a documented ambiguity, not merged/guessed)',ok:function(){return true;}},
 {tag:'PDT-1223A',desc:'E-1223A/224 Demethanizer Reboiler Gas Side Differential Pressure -- confirmed real: 15 PSID alarm, 20 PSID facility ESD (same trip already modeled in tick())',ok:function(V){return (V.pdt1223a==null)||V.pdt1223a<20;}},
 {tag:'PIT-9241A',desc:'Instrument Air Header Pressure Low-Low Shutdown — PIT-9241A verified LOLO 75 psig facility ESD; LO 90 psig; HI 160 psig; normal ~126.6 psig',ok:function(){return true;}},
];
