  s+='<g data-act="mode" data-l="'+key+'" style="cursor:pointer">'+
   '<rect x="'+(x+85)+'" y="'+(y+2)+'" width="16" height="10" fill="'+mc+'" rx="1"/>'+
   '<text x="'+(x+93)+'" y="'+(y+10)+'" fill="#fff" font-size="8" font-weight="700" text-anchor="middle">'+(isM?'M':'A')+'</text></g>';
  s+='<text x="'+(x+3)+'" y="'+(y+26)+'" fill="#6888a8" font-size="7">SP</text>'+
   '<text x="'+(x+18)+'" y="'+(y+26)+'" fill="#1cd840" font-size="12" font-family="Consolas,monospace">'+Lobj.sp.toFixed(2)+'</text>'+
   '<text x="'+(x+101)+'" y="'+(y+26)+'" fill="#4a6888" font-size="7" text-anchor="end">'+units+'</text>';
  s+='<g data-act="sp" data-d="-1" data-l="'+key+'" style="cursor:pointer"><rect x="'+(x+79)+'" y="'+(y+16)+'" width="10" height="9" fill="#182028" stroke="#2e3c48" rx="1"/><text x="'+(x+84)+'" y="'+(y+24)+'" fill="#70b0e8" font-size="11" text-anchor="middle">\u2212</text></g>'+
   '<g data-act="sp" data-d="1" data-l="'+key+'" style="cursor:pointer"><rect x="'+(x+91)+'" y="'+(y+16)+'" width="10" height="9" fill="#182028" stroke="#2e3c48" rx="1"/><text x="'+(x+96)+'" y="'+(y+24)+'" fill="#70b0e8" font-size="11" text-anchor="middle">+</text></g>';
  s+='<text x="'+(x+3)+'" y="'+(y+40)+'" fill="#6888a8" font-size="7">PV</text>'+
   '<text x="'+(x+18)+'" y="'+(y+40)+'" fill="#1cd840" font-size="12" font-family="Consolas,monospace">'+Lobj.pv.toFixed(2)+'</text>'+
   '<text x="'+(x+101)+'" y="'+(y+40)+'" fill="#4a6888" font-size="7" text-anchor="end">'+units+'</text>';
  s+='<text x="'+(x+3)+'" y="'+(y+56)+'" fill="#6888a8" font-size="7">CV</text>'+
   '<text x="'+(x+18)+'" y="'+(y+56)+'" fill="#1cd840" font-size="12" font-family="Consolas,monospace">'+Lobj.out.toFixed(2)+'</text>'+
   '<text x="'+(x+101)+'" y="'+(y+56)+'" fill="#4a6888" font-size="7" text-anchor="end">%</text>';
  s+='<g data-act="cv" data-d="-1" data-l="'+key+'" style="cursor:pointer"><rect x="'+(x+79)+'" y="'+(y+46)+'" width="10" height="9" fill="#182028" stroke="#2e3c48" rx="1"/><text x="'+(x+84)+'" y="'+(y+54)+'" fill="#70b0e8" font-size="11" text-anchor="middle">\u2212</text></g>'+
   '<g data-act="cv" data-d="1" data-l="'+key+'" style="cursor:pointer"><rect x="'+(x+91)+'" y="'+(y+46)+'" width="10" height="9" fill="#182028" stroke="#2e3c48" rx="1"/><text x="'+(x+96)+'" y="'+(y+54)+'" fill="#70b0e8" font-size="11" text-anchor="middle">+</text></g>';
