  var _seq=cfCompressorSequenceLabel(c),_seqActive=(c.sequenceState==='STOPPING'||c.sequenceState==='STARTING');
  var stCol=_seqActive?'#c47a16':(on?'#1a8f3a':'#b02818'), stTx=_seq, stTx2=on?'SAFE':'---';
  s+='<rect x="'+(x+40)+'" y="'+(y+36)+'" width="100" height="16" fill="'+stCol+'" rx="1"/><text x="'+(x+90)+'" y="'+(y+48)+'" fill="#fff" font-size="8.2" text-anchor="middle" font-weight="700">'+stTx+'</text>';
  s+='<text x="'+(x+90)+'" y="'+(y+64)+'" fill="'+(on?'#0a7030':'#a02010')+'" font-size="9" text-anchor="middle" font-weight="700">'+stTx2+'</text>';
  s+='<text x="'+(x-52)+'" y="'+(y+44)+'" fill="#101820" font-size="8">Stop Req</text>';
