 s+=pt(560,58,'PT-1441',L.PCV1441B.pv.toFixed(2),'PSIG',['L','H']);

 /* ROW C: V-1441 + V-1443 vessels (y 150-300), PIC-1442 loop to the right */
 s+='<rect x="55" y="145" width="210" height="155" rx="16" fill="#1b2530" stroke="#9fb0c0" stroke-width="2"/>';
