   +st('SUCT BLOCK VLV',on?'OPEN':'CLOSED',on?grn:red)+st('SUCT CTRL VLV',suctPct.toFixed(0)+'% OPEN',on?grn:red)+st('DSCH BLOCK VLV',on?'OPEN':'CLOSED',on?grn:red)+st('BYPASS VLV',c.byp?'OPEN':'CLOSED',c.byp?grn:red)+st('BLWDN CTRL VLV',bdPct.toFixed(0)+'% OPEN',wht)+st('RECY CTRL VLV',recPct.toFixed(1)+'% OPEN',recPct>0?amb:red)+'</div>';
  body+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:6px 8px;">'
   +'<div>'+vr('Compressor Oil Pressure (PIT-4105)',oilP.toFixed(2),'psig')+vr('1st Stage Suction (PIT-4101)',suc.toFixed(1),'psig')+vr('Final Discharge (PIT-4104)',dis.toFixed(1),'psig')+vr('Main Motor Speed (ST-4101)',rpm.toFixed(0),'RPM')+'</div>'
