 // 12JJ: equipment-focused phase inspection. Functional diagram, not vendor tube geometry.
 function phaseResult(row,S){
  var p=S.PLANT||{},v=p.v||{},r=row.phaseRule,x=r&&r.proxy?num(v[r.proxy]):null,ph=row.phase,why='Normal-service phase reference';
  if(r){
   if(r.kind==='reference'){ph=demo?row.phase:'unknown';why=demo?'Illustrative normal-duty phase change':'This individual outlet phase is not solved';}
   else if(x===null){ph=demo?row.phase:'unknown';why=demo?'Illustrative reference; phase proxy unavailable':'Required phase/heat proxy unavailable';}
   else if(x<=0){ph='unknown';why='No positive phase-change evidence; retained inventory phase is not solved';}
   else{ph=row.phase;why='Qualitative response to '+r.proxy+'; not a vapor fraction';}
  }
  return {phase:ph,phaseReason:why};
 }
 function exchanger(id){return (plan.exchangers||[]).find(function(g){return g.id===id;});}
 function circuitState(c){
  var S=states(),p=S.PLANT||{},v=p.v||{},g=c.oilConsumer?'value:hoFlow'+c.oilConsumer:c.gate;
  var r=read({gate:g,phase:'gas',controls:[]},S),paused=!motion||!!(host.hidden&&host.hidden())||p.simLive===false;
  var pi=c.inPhase,po=c.outPhase,mid=pi,kind='Normal-service reference',heat=c.proxy?num(v[c.proxy]):null;
  if(c.referenceOnly){po=demo?c.outPhase:'unknown';kind=demo?'REFERENCE phase-change illustration':'Outlet phase unavailable - use Reference demonstration for the normal-duty illustration';}
  else if(c.proxy){
   if(heat===null||heat<=0){po=demo?c.outPhase:'unknown';kind=demo?'REFERENCE heat-transfer illustration':'No active phase-change proxy; outlet phase unresolved';}
   else kind='DUTY-LINKED qualitative illustration - not measured phase quality';
  }
  if(po==='unknown')mid='unknown';else if(pi!==po||c.boilingPool)mid='mixed';else mid=po;
  if(c.id==='chillerProcess'&&!demo){pi='unknown';kind+='; inlet phase not independently solved';}
  if(c.id==='side1224'&&!demo){pi='unknown';kind+='; combined inlet quality unresolved';}
  var temps=(c.temperatures||[]).map(function(a){var n=num(v[a[0]]);return {key:a[0],label:a[1],value:n};});
  return {id:c.id,inPhase:pi,midPhase:mid,outPhase:po,run:r.run&&!paused,reason:r.reason,basis:kind,heatProxy:c.proxy||null,temperatures:temps};
 }
 function circuitStates(){var g=exchanger(hxId);return g?g.circuits.map(circuitState):[];}
 function inspectExchanger(id){
  var g=exchanger(id);if(!g)return false;hxId=id;tab='exchangers';focusRoutes=new Set();
  g.circuits.forEach(function(c){c.routeIds.forEach(function(k){focusRoutes.add(k);});});
  Object.keys(active).forEach(function(k){active[k]=false;});plan.routes.forEach(function(r){if(focusRoutes.has(r.id))active[r.system]=true;});
  if(host.publish)host.publish(active);
  try{lastError='';rebuild();}catch(e){lastError=String(e);try{clear();}catch(_){}if(host.warn)host.warn(e);paint();}
  return true;
 }
