function cfOpsNotifications12OU(){var c=cfOpsUpdate12OU(),S=cfOps12OU(),now=PLANT.simSeconds||0;return c.rows.filter(function(r){var e=S.episodes[r.id];if(now-e.firstSim<r.delay)return false;if(r.sev==='CRITICAL')return true;return !PLANT.notifDismissed[r.id]&&!(PLANT.notifSnoozeUntil[r.id]>now);}).map(function(r){return Object.assign({},r,{ack:S.episodes[r.id].ack,firstSim:S.episodes[r.id].firstSim});}).sort(function(a,b){return ({CRITICAL:4,HIGH:3,NORMAL:2,INFO:1}[b.sev]-{CRITICAL:4,HIGH:3,NORMAL:2,INFO:1}[a.sev]);});}
