function cfOpsShiftHero12OY(h){
 var S=cfOps12OU(),P=PLANT,e=cfOpsEscape12OU,b=cfOpsButton12OU,active=!!P.shiftStart,sampler=active&&S.shift&&S.shift.start===P.shiftStart.simSeconds;
 var elapsed=active&&cfOpsNumber12OU(P.simSeconds)!==null&&cfOpsNumber12OU(P.shiftStart.simSeconds)!==null?Math.max(0,P.simSeconds-P.shiftStart.simSeconds):null;
 var minutes=elapsed===null?'Not started':Math.floor(elapsed/3600)+'h '+Math.floor(elapsed%3600/60)+'m '+Math.floor(elapsed%60)+'s';
 var title=active?'Shift in progress':P.lastHandover?'Review the last handover':'Start a shift record';
 var alarms=sampler?Math.max(0,S.alarmSerial-S.shift.alarmSerial):null;
 var critical=h.rows.filter(function(r){return r.sev==='CRITICAL';});
 var html='<section class="ou-hero oy-shift-hero"><div><span class="ou-eyebrow">RECORD / COMPARE / HAND OVER</span><h2>'+title+'</h2><p>'+(active?'Started '+e(new Date(P.shiftStart.wallMs).toLocaleString()):'Use Start shift to collect a new observed time window. Existing handovers and notes stay intact.')+'</p></div><div class="oy-shift-clock"><strong>'+minutes+'</strong><span>Executed simulation time</span></div></section>';
 html+='<div class="ou-summary-grid oy-shift-summary"><div>Observation coverage<strong>'+ (sampler?(S.shift.count.flow||0)+' valid inlet samples':active?'Sampler unavailable':'No active window')+'</strong><small>One sample per observed simulation second</small></div><div>Alarm / event edges<strong>'+cfOpsFmt12OU(alarms,0)+'</strong><small>Since this shift was started</small></div><div>Open outage intents<strong>'+S.plans.filter(function(p){return p.status==='planned';}).length+'</strong><small>Planning only; no automatic shutdown</small></div><div>Handover status<strong>'+(P.lastHandover?P.shiftAcked?'Incoming acknowledged':P.shiftSigned?'Outgoing signed':'Awaiting sign-off':'No completed handover')+'</strong><small>Simulator workflow flags, not verified identity</small></div></div>';
 if(critical.length)html+='<aside class="ou-notice oy-shift-critical"><b>'+critical.length+' critical current condition'+(critical.length===1?'':'s')+'</b><p>'+e(critical.map(function(r){return r.title;}).join(' / '))+'</p>'+b('view','Inspect in Plant health','health')+'</aside>';
 return html;
}
