function cfFindSelect12PG(raw){
 var k=String(raw||'').trim();if(!k)return {ok:false,message:'Choose an equipment tag or line first.'};
 var nav=window.CFNavigation12MJ||window.CFNavigation12IN,ok=false,reason='';
 try{
  if(k==='mval'){showMV=true;var mv=document.getElementById('mvchk');if(mv)mv.checked=true;applyLayers();}
  if(nav&&typeof nav.fly==='function'){
   ok=nav.fly(k,true)===true;
   if(!ok&&nav.status){var s=nav.status();reason=s&&s.last&&s.last.reason||'';}
  }else if(typeof go==='function'){if(walk&&typeof exitWalk==='function')exitWalk();ok=go(k)!==false;}
  if(ok)return {ok:true,message:'3D focus requested. The selected equipment information is available in the equipment panel.'};
  var infoKey=typeof cfRefResolve==='function'?cfRefResolve(k):k;
  var recordKey=typeof CF3D_DEVICE_RECORDS!=='undefined'&&(CF3D_DEVICE_RECORDS[k]?k:(infoKey&&CF3D_DEVICE_RECORDS[infoKey]?infoKey:null));
  if((infoKey&&INFO[infoKey])||recordKey){
   if(infoKey&&INFO[infoKey])show(infoKey);else if(typeof cf3dInspectDevice==='function')cf3dInspectDevice(recordKey);
   var p=document.getElementById('panel');if(p){p.hidden=false;p.style.display='';p.scrollIntoView({block:'start',behavior:'auto'});}
   return {ok:false,referenceOnly:true,message:(reason||'No attached 3D model is available for this exact item.')+' Retained information is shown in the equipment panel.'};
  }
  return {ok:false,message:reason||'No model or retained equipment information is available for this selection. Use Component Finder for a unit-qualified record.'};
 }catch(e){return {ok:false,message:'Find could not show this item: '+String(e&&e.message||e)+'. Open Startup check for initialization errors; do not clear saved data.'};}
}
